class GoldenDUT:
    def __init__(self):
        # Initialize the internal state registers
        self.q_reg = 0  # Initial value of q is set to 0

    def load(self, signal_vector):
        # Load input signals and update internal state
        a = signal_vector['a']
        # Calculate the new state of q based on input a
        self.q_reg = self.calculate_q(a)

    def calculate_q(self, a):
        # Determine the next state of q based on input a and current state
        if a == 0:
            return 1  # q remains 1 if a is 0
        else:
            return 0  # q toggles if a is 1

    def check(self, signal_vector):
        # Check the output of DUT against the expected value
        q_observed = signal_vector['q']
        if signal_vector['check_en']:
            # Compare observed q with expected q_reg
            if q_observed != self.q_reg:
                print(f"Scenario: {signal_vector['scenario']}, expected: q={self.q_reg}, observed q={q_observed}")
                return False
        return True

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
