class GoldenDUT:
    def __init__(self):
        # Initialize internal state variables with default values
        self.q_reg = 0  # Initial value for q
        self.previous_a = 0  # Initiate tracking of `a`'s previous state

    def load(self, signal_vector):
        # Call the core rule function to update internal states based on input signal
        self.q_reg = self.core_rule(signal_vector.get('a', 0))

    def check(self, signal_vector):
        if signal_vector.get('check_en'):
            q_observed = signal_vector.get('q')
            if q_observed != self.q_reg:
                print(f"Scenario: {signal_vector['scenario']}, expected: q={self.q_reg}, observed q={q_observed}")
                return False
        return True

    def core_rule(self, a):
        """
        Function to determine the expected value of 'q' based on the input 'a'
        during a rising clock edge.

        :param a: The value of 'a' at the rising edge of the clock. It should be 0 or 1.
        :return: The expected value of 'q'. Follows the toggle logic.
        """
        if a != self.previous_a:  # Toggle conditionally if 'a' has changed
            self.q_reg = not self.q_reg  # Toggle 'q'
        self.previous_a = a  # Update previous 'a' state
        return self.q_reg
