class GoldenDUT:
    def __init__(self):
        # Initialize internal state
        self.x_reg = 0
        self.z_reg = 0
        self.z_expected = []  # Used to accumulate expected Z values for comparison
        self.carry = 1  # Initial carry for 2's complement calculation

    def load(self, signal_vector):
        # Load input signals and update internal state
        self.x_reg = signal_vector['x']

        # If areset is asserted, reset the internal state
        if signal_vector['areset']:
            self.z_expected = []
            self.carry = 1  # Reset carry to initial state since we start fresh
        else:
            # Continue processing input for 2's complement conversion
            self.process_input()

    def process_input(self):
        z_current = self.calculate_z(self.x_reg)
        self.z_expected.append(z_current)

    def calculate_z(self, x_bit):
        import numpy as np
        inverted_bit = np.logical_not(x_bit).astype(int)

        # 2's complement calculation on a single bit considering carry
        result = inverted_bit + self.carry
        if result == 2:
            z_result = 0
            self.carry = 1
        else:
            z_result = result
            self.carry = 0

        return z_result

    def check(self, signal_vector):
        self.z_reg = signal_vector['z']  # Observed z value from DUT

        # When check_en is True, compare expected and observed, and start new scenario if necessary
        if signal_vector['check_en']:
            if self.z_expected:  # Check to ensure z_expected is not empty
                a_observed = signal_vector['z']
                a_reg = self.z_expected[len(self.z_expected) - 1]
                if a_observed != a_reg:
                    print(f"Scenario: {signal_vector['scenario']}, expected: z={a_reg}, observed z={a_observed}")
                    return False
            # Reset and prepare for new scenario
            self.z_expected = []  
            self.carry = 1  # Reset carry for the next scenario to be independent
        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

