    def __init__(self):
        # Internal state variables with initial values
        self.x_reg = 0
        self.z_reg = 0
        self.prev_x = 0
        self.complement_buffer = []

    def load(self, signal_vector):
        # Load input signals and update internal state
        if signal_vector['areset']:
            self.complement_buffer = []
            self.z_reg = 0
        else:
            self.x_reg = signal_vector['x']
            if len(self.complement_buffer) == 0:
                self.complement_buffer.append(1 - self.x_reg)
            else:
                carry = 1
                for i in range(len(self.complement_buffer)):
                    if self.complement_buffer[i] == 1 and carry == 1:
                        self.complement_buffer[i] = 0
                        carry = 1
                    else:
                        self.complement_buffer[i] = self.complement_buffer[i] + carry
                        carry = 0
                self.complement_buffer.append(1 - self.x_reg)

            self.z_reg = self.complement_buffer.pop(0)

    def check(self, signal_vector):
        if signal_vector['check_en']:
            z_observed = signal_vector['z']
            if self.z_reg != z_observed:
                print(f"Scenario: {signal_vector['scenario']}, expected: z={self.z_reg}, observed z={z_observed}")
                return False
        return True

