class GoldenDUT:
    def __init__(self):
        self.input_sequence = []
        self.processing = False
        self.z_reg = 'x'  # Start with undefined output during reset

    def load(self, signal_vector):
        areset = signal_vector['areset']
        x = signal_vector['x']

        # Check reset condition
        if areset == 1:
            self.processing = False
            self.input_sequence = []
            self.z_reg = 'x'  # Undefined during reset
        else:
            # Process input signal
            self.processing = True
            self.input_sequence.append(x)

    def check(self, signal_vector):
        if not self.processing:
            z_expected = 'x'  # Undefined output if not processing
        else:
            # Calculate expected output for the current cycle
            z_expected = self.calculate_current_twos_complement()

        z_observed = signal_vector['z']

        if z_expected != z_observed:
            print(f"Scenario: {signal_vector['scenario']}, expected: z={z_expected}, observed: z={z_observed}")
            return False
        return True

    def calculate_twos_complement(self):
        """Calculate the complete 2's complement of the accumulated input sequence."""
        binary_number = ''.join(str(bit) for bit in self.input_sequence)
        num = int(binary_number, 2)
        num_complement = (~num & ((1 << len(self.input_sequence)) - 1)) + 1
        twos_complement_bits = list(map(int, bin(num_complement)[2:].zfill(len(self.input_sequence))))
        return twos_complement_bits

    def calculate_current_twos_complement(self):
        """Calculate the 2's complement output bit for the last input in the sequence."""
        current_input = self.input_sequence[-1]
        if len(self.input_sequence) == 1:
            return 1 if current_input == 0 else 0

        twos_complement_bits = self.calculate_twos_complement()
        return twos_complement_bits[-1]

