class GoldenDUT:
    def __init__(self):
        self.message_reg = []     # To store the 3-byte message
        self.collecting_reg = False  # To track if we are collecting
        self.done_reg = 0         # To store the done signal
        self.out_bytes_reg = 0    # To store the 24-bit output message

    def load(self, signal_vector):
        # Load the reset and input signals
        reset = signal_vector['reset']
        in_byte = signal_vector['in']

        # Check reset condition
        if reset:
            self.message_reg = []
            self.collecting_reg = False
            self.done_reg = 0
            self.out_bytes_reg = 0
            return

        # FSM logic
        if not self.collecting_reg:
            if (in_byte & 0b00001000):  # If in[3] is set correctly
                self.collecting_reg = True
                self.message_reg = [in_byte]
                self.done_reg = 0
            else:
                self.done_reg = 0
        else:
            # Ensure only storing exactly 3 message bytes
            if len(self.message_reg) < 3:
                self.message_reg.append(in_byte)

            # When exactly 3 bytes are collected
            if len(self.message_reg) == 3:
                self.collecting_reg = False
                self.done_reg = 1
                # Form 24-bit output message
                self.out_bytes_reg = (self.message_reg[0] << 16) | (self.message_reg[1] << 8) | self.message_reg[2]
                # Reset the message storage for potential next message
                self.message_reg = []  
            else:
                self.done_reg = 0

    def check(self, signal_vector):
        observed_out_bytes = signal_vector['out_bytes']
        observed_done = signal_vector['done']

        expected_out_bytes = self.out_bytes_reg
        expected_done = self.done_reg

        if expected_out_bytes != observed_out_bytes or expected_done != observed_done:
            print(f"Scenario: {signal_vector['scenario']}, "
                  f"expected: out_bytes={expected_out_bytes}, done={expected_done}, "
                  f"observed: out_bytes={observed_out_bytes}, done={observed_done}")
            return False
        return True

