class GoldenDUT:
    def __init__(self):
        self.state_reg = 0  # 0: Waiting, 1: First byte, 2: Second byte
        self.message_buffer_reg = [0, 0, 0]
        self.done_reg = 0
        self.out_bytes_reg = 0
        self.next_state_reg = 0  # Used to manage the next state

    def load(self, signal_vector):
        in_byte = signal_vector['in']
        reset = signal_vector['reset']

        if reset:
            # Reset the FSM
            self.state_reg = 0
            self.message_buffer_reg = [0, 0, 0]
            self.done_reg = 0
            self.out_bytes_reg = 0
            self.next_state_reg = 0
        else:
            if self.state_reg == 0:
                if in_byte & 0b00001000:  # Check if in[3] == 1
                    # Detected start of a message
                    self.message_buffer_reg[0] = in_byte
                    self.next_state_reg = 1
            elif self.state_reg == 1:
                # Record the second byte
                self.message_buffer_reg[1] = in_byte
                self.next_state_reg = 2
            elif self.state_reg == 2:
                # Record the third byte and complete the message
                self.message_buffer_reg[2] = in_byte
                self.done_reg = 1
                self.out_bytes_reg = (
                    (self.message_buffer_reg[0] << 16)
                    | (self.message_buffer_reg[1] << 8)
                    | self.message_buffer_reg[2]
                )
                self.next_state_reg = 0  # Prepare to wait for the next message

            # Update state at the end of cycle
            self.state_reg = self.next_state_reg

        # Done should only be set high immediately after the third byte
        # Ensure it persists for one cycle after out_bytes is set
        if self.state_reg != 2 or reset:
            self.done_reg = 0

    def check(self, signal_vector):
        done_observed = signal_vector['done']
        out_bytes_observed = signal_vector['out_bytes']

        if self.done_reg != done_observed or self.out_bytes_reg != out_bytes_observed:
            print(
                f"Scenario: {signal_vector['scenario']}, "
                f"expected: done={self.done_reg}, out_bytes={self.out_bytes_reg}, "
                f"observed: done={done_observed}, out_bytes={out_bytes_observed}"
            )
            return False
        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

