class GoldenDUT:
    def __init__(self):
        self.current_message_reg = []
        self.done_reg = False
        self.out_bytes_reg = 0

    def load(self, signal_vector):
        # Extract necessary input signals
        in_signal = signal_vector['in']
        reset = signal_vector['reset']

        if reset:
            # Reset the internal state
            self.current_message_reg = []
            self.done_reg = False
            self.out_bytes_reg = 0
        else:
            # Detect the start of a message (in[3] should be 1 for it to be valid)
            if (len(self.current_message_reg) == 0 and (in_signal & 0b00001000) == 0b00001000):
                # Start a new message
                self.current_message_reg.append(in_signal)

            elif len(self.current_message_reg) > 0:
                # Continue building a message if we are in the middle of one
                self.current_message_reg.append(in_signal)

            if len(self.current_message_reg) == 3:
                # Once 3 bytes are collected, complete the message
                self.done_reg = True
                self.out_bytes_reg = ((self.current_message_reg[0] << 16) | 
                                      (self.current_message_reg[1] << 8)  | 
                                       self.current_message_reg[2])
                # Reset for next message
                self.current_message_reg = []
            else:
                self.done_reg = False

    def check(self, signal_vector):
        expected_done = self.done_reg
        expected_out_bytes = self.out_bytes_reg

        observed_done = signal_vector['done']
        observed_out_bytes = signal_vector['out_bytes']

        if expected_done != observed_done or expected_out_bytes != observed_out_bytes:
            print(f"Scenario: {signal_vector['scenario']}, "
                  f"expected: done={expected_done}, out_bytes={expected_out_bytes:x}, "
                  f"observed: done={observed_done}, out_bytes={observed_out_bytes:x}")
            return False
        return True

    # Additional methods can be added here if needed (e.g., for extended functionality)

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

