class GoldenDUT:

    def __init__(self):
        # Initialize the internal state and registers
        self.state_reg = 'IDLE'
        self.message_reg = [0, 0, 0]
        self.out_bytes_reg = 0
        self.done_reg = 0

    def load(self, signal_vector):
        # Reset handling
        if signal_vector['reset']:
            self.__init__()  # Reset the internal state
            return

        # Input byte handling based on current FSM state
        input_value = signal_vector['in']

        if self.state_reg == 'IDLE':
            # Transition to BYTE_1 if input byte has in[3] == 1
            if input_value & 0b1000:
                self.state_reg = 'BYTE_1'
                self.message_reg[0] = input_value
        elif self.state_reg == 'BYTE_1':
            # Capture second byte and move to BYTE_2
            self.state_reg = 'BYTE_2'
            self.message_reg[1] = input_value
        elif self.state_reg == 'BYTE_2':
            # Capture third byte and move to DONE
            self.state_reg = 'DONE'
            self.message_reg[2] = input_value

    def check(self, signal_vector):
        # Initialize expected values
        expected_out_bytes = 'x'
        expected_done = 0

        # If FSM state is DONE, prepare the output and set done flag
        if self.state_reg == 'DONE':
            expected_out_bytes = (
                (self.message_reg[0] << 16) |
                (self.message_reg[1] << 8) |
                self.message_reg[2]
            )
            expected_done = 1
            # Transition to IDLE after output check
            self.__init__()

        # Observed values from simulation
        observed_out_bytes = signal_vector['out_bytes']
        observed_done = signal_vector['done']

        # Check expected vs observed values
        if signal_vector['check_en']:
            if expected_out_bytes != 'x' and expected_out_bytes != observed_out_bytes:
                print(f"Scenario: {signal_vector['scenario']}, expected out_bytes={expected_out_bytes}, observed out_bytes={observed_out_bytes}")
                return False
            if expected_done != observed_done:
                print(f"Scenario: {signal_vector['scenario']}, expected done={expected_done}, observed done={observed_done}")
                return False

        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
