    IDLE = 0
    BYTE_1 = 1
    BYTE_2 = 2
    BYTE_3 = 3

    def __init__(self):
        self.state_reg = self.IDLE
        self.message_reg = [0, 0, 0]
        self.out_bytes_reg = 'x'  # Initial value as 'x'
        self.done_reg = 0

    def load(self, signal_vector):
        # Update DUT state and message based on input signals
        if signal_vector['reset']:
            # Reset logic
            self.state_reg = self.IDLE
            self.message_reg = [0, 0, 0]
            self.out_bytes_reg = 'x' # Set to 'x' when reset
            self.done_reg = 0
        else:
            current_byte = signal_vector['in']
            if self.state_reg == self.IDLE:
                if current_byte & 0b00001000:  # If in[3] == 1
                    self.state_reg = self.BYTE_1
                    self.message_reg[0] = current_byte

            elif self.state_reg == self.BYTE_1:
                self.state_reg = self.BYTE_2
                self.message_reg[1] = current_byte

            elif self.state_reg == self.BYTE_2:
                self.state_reg = self.BYTE_3
                self.message_reg[2] = current_byte
                self.out_bytes_reg = (self.message_reg[0] << 16) | (self.message_reg[1] << 8) | self.message_reg[2]
                self.done_reg = 1

            elif self.state_reg == self.BYTE_3:
                self.done_reg = 0  # Ensure done is cleared after one cycle
                self.message_reg = [0, 0, 0]  # Clear message register for next potential message
                self.state_reg = self.IDLE

    def check(self, signal_vector):
        if signal_vector['check_en']:
            expected_out_bytes = self.out_bytes_reg if self.done_reg else 'x'
            expected_done = self.done_reg

            # Compare expected and actual outputs
            if expected_done != signal_vector['done'] or expected_out_bytes != signal_vector['out_bytes']:
                print(f"Scenario: {signal_vector['scenario']}, expected: done={expected_done}, out_bytes={expected_out_bytes}, observed: done={signal_vector['done']}, out_bytes={signal_vector['out_bytes']}")
                return False
        return True
