class GoldenDUT:
    def __init__(self):
        self.reset_reg = 'x'
        self.state_reg = 'IDLE'
        self.message_reg = [0, 0, 0]
        self.index_reg = 0
        self.done_reg = 0
        self.out_bytes_reg = 0

    def load(self, signal_vector):
        reset = signal_vector['reset']
        in_byte = signal_vector['in']

        if reset:
            self.reset_reg = 1
            self.state_reg = 'IDLE'
            self.index_reg = 0
            self.message_reg = [0, 0, 0]
            self.done_reg = 0
            self.out_bytes_reg = 0
        else:
            self.reset_reg = 0

            if self.state_reg == 'IDLE':
                if in_byte & 0b00001000:  # Check if in[3] == 1
                    self.state_reg = 'COLLECT'
                    self.message_reg[0] = in_byte
                    self.index_reg = 1
                    self.done_reg = 0
                else:
                    self.done_reg = 0

            elif self.state_reg == 'COLLECT':
                if in_byte & 0b00001000 and self.index_reg == 0:
                    # If in_byte indicates a reset start, ignore unless complete message
                    self.state_reg = 'COLLECT'
                    self.message_reg[0] = in_byte
                    self.index_reg = 1
                    self.done_reg = 0
                else:
                    self.message_reg[self.index_reg] = in_byte
                    self.index_reg += 1

                    if self.index_reg == 3:
                        self.state_reg = 'DONE'
                        self.done_reg = 1
                        self.out_bytes_reg = (self.message_reg[0] << 16) | (self.message_reg[1] << 8) | self.message_reg[2]
                    else:
                        self.done_reg = 0

            elif self.state_reg == 'DONE':
                # Changed logic to ensure the DONE state holds for one cycle
                self.done_reg = 1
                self.state_reg = 'IDLE'
                self.index_reg = 0
                self.message_reg = [0, 0, 0]
                # Do not reset out_bytes_reg immediately, allow it to persist in this cycle

    def check(self, signal_vector):
        expected_done = self.done_reg
