    def __init__(self):
        # Define one-hot state encodings
        self.STATE_A = 0b000001
        self.STATE_B = 0b000010
        self.STATE_C = 0b000100
        self.STATE_D = 0b001000
        self.STATE_E = 0b010000
        self.STATE_F = 0b100000

    def load(self, signal_vector):
        y = signal_vector['y']
        w = signal_vector['w']
        return self.expected_Y1_Y3(y, w)

    def check(self, signal_vector):
        expected_Y1, expected_Y3 = self.load(signal_vector)
        actual_Y1 = signal_vector['Y1']
        actual_Y3 = signal_vector['Y3']
        return (expected_Y1 == actual_Y1) and (expected_Y3 == actual_Y3)

    def expected_Y1_Y3(self, y, w):
        # Determine the next state based on current state and input w
        if y == self.STATE_A:
            next_state = self.STATE_B if w == 1 else self.STATE_A
        elif y == self.STATE_B:
            next_state = self.STATE_C if w == 1 else self.STATE_D
        elif y == self.STATE_C:
            next_state = self.STATE_E if w == 1 else self.STATE_D
        elif y == self.STATE_D:
            next_state = self.STATE_F if w == 1 else self.STATE_A
        elif y == self.STATE_E:
