        elif y == self.STATE_F:
            next_state = self.STATE_C if w == 1 else self.STATE_D
        else:
            next_state = y

        # Compute Y1 and Y3 for next state
        Y1 = 1 if next_state & self.STATE_B else 0
        Y3 = 1 if next_state & self.STATE_D else 0

        return Y1, Y3

