class GoldenDUT:
    def __init__(self):
        # Initialize the flip-flop registers to 0
        self.ff1_reg = 0
        self.ff2_reg = 0
        self.ff3_reg = 0

    def load(self, signal_vector):
        x = signal_vector['x']
        # Calculate the D inputs for each flip-flop
        d_ff1 = x ^ self.ff1_reg
        d_ff2 = x & (~self.ff2_reg)  # Corrected to use complemented output
        d_ff3 = x | (~self.ff3_reg)  # Corrected to use complemented output

        # Update the flip-flop registers at the rising edge of the clock
        self.ff1_reg = d_ff1 & 0b1  # Mask to ensure single bit
        self.ff2_reg = d_ff2 & 0b1  # Mask to ensure single bit
        self.ff3_reg = d_ff3 & 0b1  # Mask to ensure single bit

    def check(self, signal_vector):
        z_observed = signal_vector['z']
        # Calculate the expected output of the XNOR gate
        z_expected = ~(self.ff1_reg ^ self.ff2_reg ^ self.ff3_reg) & 0b1  # Mask to ensure single bit

        if z_expected != z_observed:
            print(f"Scenario: {signal_vector['scenario']}, expected: z={z_expected}, observed: z={z_observed}")
            return False
        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
