class GoldenDUT:
    def __init__(self):
        # Initialize the registers
        self.Q1_reg = 0
        self.Q2_reg = 0
        self.Q3_reg = 0

    def load(self, signal_vector):
        # Load input signals and update the internal state
        x = signal_vector['x']

        # Compute D inputs for each flip-flop
        D1 = x ^ self.Q1_reg  # XOR gate with current state
        D2 = x & (~self.Q2_reg & 1)  # AND gate with complementary output, ensure boolean result 
        D3 = x | (~self.Q3_reg & 1)  # OR gate with complementary output, ensure boolean result

        # Update the flip-flops state
        self.Q1_reg = D1
        self.Q2_reg = D2
        self.Q3_reg = D3

    def check(self, signal_vector):
        # Expected output determination using XNOR
        expected_z = ~((self.Q1_reg ^ self.Q2_reg ^ self.Q3_reg) & 1)  # Ensure correct XNOR logic is applied

        # Compare with the output signal from DUT
        z_observed = signal_vector['z']

        if z_observed == expected_z:
            return True
        else:
            scenario = signal_vector['scenario']
            print(f"Scenario: {scenario}, expected: z={expected_z}, observed z={z_observed}")
            return False
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

