class GoldenDUT:
    def __init__(self):
        # Initialize inner states/values
        self.previous_input_reg = 0x00000000
        self.current_output_reg = 0x00000000

    def load(self, signal_vector):
        # Load current inputs and calculate new states
        current_input = signal_vector['in']
        reset = signal_vector['reset']

        # Detect transitions from 1 to 0 using bitwise operations
        transitions = ((self.previous_input_reg & ~current_input) & 0xFFFFFFFF)

        # Update the current output register with detected transitions
        self.current_output_reg |= transitions

        # Apply reset if required
        if reset:
            self.current_output_reg = 0x00000000

        # Update previous input for the next cycle
        self.previous_input_reg = current_input

    def check(self, signal_vector):
        # Expected output vs DUT output comparison
        expected_output = self.current_output_reg
        observed_output = signal_vector['out']

        if expected_output != observed_output:
            print(f"Scenario: {signal_vector['scenario']}, expected: out={expected_output:032b}, observed: out={observed_output:032b}")
            return False
        return True

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

