class GoldenDUT:
    def __init__(self):
        # Initialize the internal state to weakly not-taken (binary 01)
        self.state_reg = 0b01

    def load(self, signal_vector):
        # Update internal state based on the signal vector inputs
        areset = signal_vector['areset']
        train_valid = signal_vector['train_valid']
        train_taken = signal_vector['train_taken']

        # Apply asynchronous reset to the counter
        if areset:
            self.state_reg = 0b01  # Reset state to weakly not-taken
            return

        # State transitions based on train_valid and train_taken inputs
        if train_valid:  
            if train_taken:
                # Increment logic with saturation at the maximum value 0b11
                if self.state_reg < 0b11:
                    self.state_reg += 1
            else:
                # Decrement logic with saturation at the minimum value 0b00
                if self.state_reg > 0b00:
                    self.state_reg -= 1

        # Ensure the state is within the two-bit range
        self.state_reg &= 0b11

    def check(self, signal_vector):
        # Retrieve the observed state from the signal vector
        observed_state = signal_vector['state']

        # Compare the expected state with the observed state of the DUT
        if observed_state != self.state_reg:
            print(f"Scenario: {signal_vector['scenario']}, expected: state={self.state_reg}, observed: state={observed_state}")
            return False
        return True

    # Add any additional methods if necessary

