        # Handle asynchronous reset
        if signal_vector['areset']:
            self.state_reg = 0b01
        else:
            # Apply rules based on train_valid and train_taken
            if signal_vector['train_valid']:
                if signal_vector.get('train_taken', 0):  # Uses default 0 if not provided
                    # Increment state with saturation at 0b11
                    if self.state_reg < 0b11:
                        self.state_reg += 1
                else:
                    # Decrement state with saturation at 0b00
                    if self.state_reg > 0b00:
                        self.state_reg -= 1
            # No need to change state if train_valid is 0 (Scenario: Do nothing when not training)

    def check(self, signal_vector):
        # Expected output state
        expected_state = self.state_reg

        # Observed output from DUT
        observed_state = signal_vector['state']

        # Compare expected and observed values
        if expected_state == observed_state:
            return True
        else:
