        # Obtain expected output values from the golden DUT
        expected_outputs = self.load(signal_vector)

        # Compare expected with actual DUT outputs
        actual_out_sop = signal_vector['out_sop']
        actual_out_pos = signal_vector['out_pos']

        if self.is_nan(expected_outputs['out_sop']): 
            # Check for NaN: True for "never occur" scenarios
            return True  
        else:
            # Return True if both outputs match; False otherwise
            return (expected_outputs['out_sop'] == actual_out_sop) and (expected_outputs['out_pos'] == actual_out_pos)

    def expected_output_sop(self, input_condition):
        # Rules for the SOP form
        if input_condition in self.logic_one_conditions:
            return 1
        elif input_condition in self.logic_zero_conditions:
            return 0
        else:
            raise ValueError(f"Unexpected input condition: {input_condition}")

    def expected_output_pos(self, input_condition):
        # Rules for the POS form
        if input_condition in self.logic_one_conditions:
            return 1
        elif input_condition in self.logic_zero_conditions:
            return 0
        else:
            raise ValueError(f"Unexpected input condition: {input_condition}")

    def is_nan(self, x):
        # Helper function to check for NaN values
        import math
        return math.isnan(x)
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        check_pass = golden_dut.check(vector)
        if check_pass:
            print(f"Passed; vector: {vector}")
        else:
            print(f"Failed; vector: {vector}")
            failed_scenarios.append(vector["scenario"])
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    lines = txt.strip().split("\n")
    signals = []
    for line in lines:
        signal = {}
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1]
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if "x" not in value and "z" not in value:
                    signal[key] = int(value)
                else:
                    signal[key] = value 
        signals.append(signal)
    return signals
