class GoldenDUT:
    def __init__(self):
        # Define logic-1 and logic-0 cases
        self.logic_1_cases = {2, 7, 15}
        self.logic_0_cases = {0, 1, 4, 5, 6, 9, 10, 13, 14}

    def load(self, signal_vector):
        # Extract input signals from the signal vector
        a = signal_vector['a']
        b = signal_vector['b']
        c = signal_vector['c']
        d = signal_vector['d']

        # Calculate the numerical representation of inputs
        input_value = (a << 3) | (b << 2) | (c << 1) | d

        # Determine the expected outputs based on input_value
        if input_value in self.logic_1_cases:
            return 1, 1  # Both out_sop and out_pos should be 1
        elif input_value in self.logic_0_cases:
            return 0, 0  # Both out_sop and out_pos should be 0
        else:
            return None, None  # Unused input condition

    def check(self, signal_vector):
        # Call load to get the expected output values
        expected_out_sop, expected_out_pos = self.load(signal_vector)

        # Retrieve actual output signals from the signal vector
        actual_out_sop = signal_vector['out_sop']
        actual_out_pos = signal_vector['out_pos']

        # Compare expected and actual outputs
        if expected_out_sop is None or expected_out_pos is None:
            # Ignore the cases that should never occur (3, 8, 11, 12)
            return (actual_out_sop is None) and (actual_out_pos is None)

        return (expected_out_sop == actual_out_sop) and (expected_out_pos == actual_out_pos)
