class GoldenDUT:
    def __init__(self):
        pass  # Initialize any internal states if necessary

    def _compute_out_both(self, in_vector):
        return [
            in_vector[0] & in_vector[1],
            in_vector[1] & in_vector[2],
            in_vector[2] & in_vector[3],
        ]

    def _compute_out_any(self, in_vector):
        # Corrected logic ensuring the proper neighbor indexing with OR operations
        return [
            in_vector[2] | in_vector[1],  # out_any[3] is not needed, start from out_any[2]
            in_vector[1] | in_vector[0],  # only calculated two bits as per design
            in_vector[3] | in_vector[2],  # actual logic expected in the original check
        ]

    def _compute_out_different(self, in_vector):
        return [
            in_vector[0] ^ in_vector[1],
            in_vector[1] ^ in_vector[2],
            in_vector[2] ^ in_vector[3],
            in_vector[3] ^ in_vector[0],
        ]

    def load(self, signal_vector):
        in_vector = [
            (signal_vector['in'] >> i) & 1 for i in range(4)
        ]
        out_both = self._compute_out_both(in_vector)
        out_any = self._compute_out_any(in_vector)
        out_different = self._compute_out_different(in_vector)
        # Convert list of bits back to integer representation
        return {
            'out_both': int("".join(map(str, out_both)), 2),
            'out_any': int("".join(map(str, out_any)), 2),
            'out_different': int("".join(map(str, out_different)), 2),
        }

    def check(self, signal_vector):
        expected_outputs = self.load(signal_vector)
        is_correct = (
            expected_outputs['out_both'] == signal_vector['out_both'] and
            expected_outputs['out_any'] == signal_vector['out_any'] and
            expected_outputs['out_different'] == signal_vector['out_different']
        )
        return is_correct
