        # Define the one-hot encoded states
        self.states = {
            'S0': 0b0000000001,
            'S1': 0b0000000010,
            'S2': 0b0000000100,
            'S3': 0b0000001000,
            'S4': 0b0000010000,
            'S5': 0b0000100000,
            'S6': 0b0001000000,
            'S7': 0b0010000000,
            'S8': 0b0100000000,
