class GoldenDUT:
    def __init__(self):
        self.q_reg = 0
        self.prev_a_reg = 0

    def load(self, signal_vector):
        # Update state based on the input signal and the previous value of 'a'
        a = signal_vector['a']
        if a == 1:
            self.q_reg = 0b100
        else:
            self.q_reg = (self.q_reg + 1) % 0b1000

        self.prev_a_reg = a

    def check(self, signal_vector):
        # Compare expected output to actual output
        expected_q = self.q_reg
        observed_q = signal_vector['q']

        if observed_q != expected_q:
            print(f"Scenario: {signal_vector['scenario']}, expected: q={expected_q}, observed: q={observed_q}")
            return False

        return True

    def run(self, signal_vectors):
        for signal_vector in signal_vectors:
            self.load(signal_vector)
            if signal_vector['check_en']:
                if not self.check(signal_vector):
                    return False
        return True

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
