class GoldenDUT:
    STATE_A = 0b00
    STATE_B = 0b01
    STATE_C = 0b10
    STATE_D = 0b11

    def __init__(self):
        self.state_reg = self.STATE_A
        self.g1_reg = 0
        self.g2_reg = 0
        self.g3_reg = 0

    def load(self, signal_vector):
        r1 = signal_vector['r'] & 0b01
        r2 = signal_vector['r'] & 0b10
        r3 = signal_vector['r'] & 0b100

        self.state_reg, self.g1_reg, self.g2_reg, self.g3_reg = self.arbiter_fsm(self.state_reg, r1, r2, r3)

    def check(self, signal_vector):
        if signal_vector['check_en']:
            g_observed = signal_vector['g']
            g_expected = (self.g3_reg << 2) | (self.g2_reg << 1) | self.g1_reg

            if g_observed != g_expected:
                print(f"Scenario: {signal_vector['scenario']}, expected: g={g_expected}, observed: g={g_observed}")
                return False
        return True

    def arbiter_fsm(self, current_state, r1, r2, r3):
        g1, g2, g3 = 0, 0, 0

        if current_state == self.STATE_A:
            if r1:
                next_state = self.STATE_B
                g1 = 1
            elif r2:
                next_state = self.STATE_C
                g2 = 1
            elif r3:
                next_state = self.STATE_D
                g3 = 1
            else:
                next_state = self.STATE_A

        elif current_state == self.STATE_B:
            if r1:
                next_state = self.STATE_B
                g1 = 1
            else:
                next_state = self.STATE_A

        elif current_state == self.STATE_C:
            if r2:
                next_state = self.STATE_C
                g2 = 1
            else:
                next_state = self.STATE_A

        elif current_state == self.STATE_D:
            next_state = self.STATE_A

        return next_state, g1, g2, g3

