class GoldenDUT:
    def __init__(self):
        self.msg_counter_reg = 0
        self.waiting_for_start_reg = True
        self.done_reg = 0

    def load(self, signal_vector):
        if signal_vector['reset']:
            self.msg_counter_reg = 0
            self.waiting_for_start_reg = True
            self.done_reg = 0
            return

        in_3 = (signal_vector['in'] >> 3) & 0x1

        if self.waiting_for_start_reg:
            if in_3 == 1:
                self.msg_counter_reg = 1
                self.waiting_for_start_reg = False
                self.done_reg = 0  # Ensure done is cleared upon message start
        else:
            self.msg_counter_reg += 1
            if self.msg_counter_reg == 3:
                self.done_reg = 1  # Set done_reg to 1 when third byte is received
                # Prepare for next message by resetting necessary registers
                self.msg_counter_reg = 0        # Reset counter after third byte
                self.waiting_for_start_reg = True  # Prepare to capture the next start
            else:
                self.done_reg = 0  # Ensure done_reg is cleared for message counts < 3

        # Masking to assure the bit width correctness
        self.msg_counter_reg &= 0xFF

    def check(self, signal_vector):
        done_observed = signal_vector['done']
        if self.done_reg != done_observed:
            print(f"Scenario: {signal_vector['scenario']}, expected: done={self.done_reg}, observed: done={done_observed}")
            return False
        return True
