        # Extract the input vector in decimal format
        in_vector = signal_vector['in']
        # Compute the expected output values
        expected_out = {
            'out_both': self.expected_out_both(in_vector),
            'out_any': self.expected_out_any(in_vector),
            'out_different': self.expected_out_different(in_vector)
        }
        return expected_out

    def check(self, signal_vector):
        # Load expected outputs based on the input vector
        expected_out = self.load(signal_vector)

        # Compare expected outputs with actual DUT outputs
        return (expected_out['out_both'] == signal_vector['out_both'] and
                expected_out['out_any'] == signal_vector['out_any'] and
                expected_out['out_different'] == signal_vector['out_different'])

    def expected_out_both(self, in_vector):
        out_both = 0
        for i in range(98, -1, -1):  # Iterate from 98 to 0
            if (in_vector >> i) & 1 and (in_vector >> (i + 1)) & 1:
                out_both |= (1 << i)
        return out_both

    def expected_out_any(self, in_vector):
        out_any = 0
        for i in range(99, 0, -1):  # Iterate from 99 to 1
            if (in_vector >> i) & 1 or (in_vector >> (i - 1)) & 1:
                out_any |= (1 << (i - 1))  # Adjust bit position correctly
        return out_any

    def expected_out_different(self, in_vector):
        out_different = 0
        prev_bit = in_vector & 1  # Start with in[0]
        for i in range(99, -1, -1):  # Iterate from 99 to 0
            current_bit = (in_vector >> i) & 1
            if current_bit != prev_bit:
                out_different |= (1 << i)
            prev_bit = current_bit
        # Ensure wrap-around correctness
        if ((in_vector >> 0) & 1) != ((in_vector >> 99) & 1):
            out_different |= 1 << 99  # Add correct bit position for wrap-around
        return out_different

