import numpy as np

class GoldenDUT:
    def __init__(self):
        # Initialization of any internal state if needed
        pass

    def load(self, signal_vector):
        input_vector = self._convert_to_bit_array(signal_vector['in'])
        out_both = self._compute_out_both(input_vector)
        out_any = self._compute_out_any(input_vector)
        out_different = self._compute_out_different(input_vector)
        return out_both, out_any, out_different

    def check(self, signal_vector):
        expected_out_both, expected_out_any, expected_out_different = self.load(signal_vector)
        return (np.array_equal(expected_out_both, signal_vector['out_both']) and
                np.array_equal(expected_out_any, signal_vector['out_any']) and
                np.array_equal(expected_out_different, signal_vector['out_different']))

    def _convert_to_bit_array(self, number):
        # Convert the decimal input to a binary array with 100 bits
        return np.array([int(x) for x in "{:0100b}".format(number)])

    def _compute_out_both(self, input_vector):
        out_both = np.zeros(99, dtype=int)
        for i in range(1, 100):
            out_both[i-1] = int(input_vector[i] == 1 and input_vector[i-1] == 1)
        return out_both

    def _compute_out_any(self, input_vector):
        out_any = np.zeros(99, dtype=int)
        for i in range(99):  # Adjusted to check the current bit and the bit to its right
            out_any[i] = int(input_vector[i] == 1 or input_vector[i + 1] == 1)
        return out_any

    def _compute_out_different(self, input_vector):
        out_different = np.zeros(100, dtype=int)
        for i in range(100):
            if i == 0:
                out_different[i] = int(input_vector[i] != input_vector[99])
            else:
                out_different[i] = int(input_vector[i] != input_vector[i - 1])
        return out_different
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        check_pass = golden_dut.check(vector)
        if check_pass:
            print(f"Passed; vector: {vector}")
        else:
            print(f"Failed; vector: {vector}")
            failed_scenarios.append(vector["scenario"])
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    lines = txt.strip().split("\n")
    signals = []
    for line in lines:
        signal = {}
        line = line.strip().split(", ")
        for item in line:
