class GoldenDUT:
    def __init__(self):
        self.state_reg = 'A'  # Start in state A
        self.w_sequence_reg = [0, 0, 0]  # Holds the last three values of 'w'
        self.z_reg = 0  # Output 'z'
        self.w_count_reg = 0  # Count of cycles processed in state B
        self.pending_z_output = False

    def load(self, signal_vector):
        reset = signal_vector['reset']
        s = signal_vector['s']
        w = signal_vector['w']

        if reset:
            # Reset the state and counters
            self.state_reg = 'A'
            self.w_sequence_reg = [0, 0, 0]
            self.z_reg = 0
            self.w_count_reg = 0
            self.pending_z_output = False
        else:
            if self.state_reg == 'A' and s == 1:
                # Transition to state B if s = 1
                self.state_reg = 'B'
                self.w_count_reg = 0

            # Handle pending z output from previous cycle
            if self.pending_z_output:
                self.z_reg = 1
                self.pending_z_output = False
            else:
                self.z_reg = 0

            if self.state_reg == 'B':
                self.w_sequence_reg[self.w_count_reg % 3] = w
                self.w_count_reg += 1

                if self.w_count_reg == 3:
                    count_w_ones = sum(self.w_sequence_reg)
                    if count_w_ones == 2:
                        # Set flag for z output in the next cycle
                        self.pending_z_output = True
                    # Reset w_count for continuation of checking next cycle
                    self.w_count_reg = 0

    def check(self, signal_vector):
        z_observed = signal_vector['z']
        scenario = signal_vector['scenario']

        if signal_vector['check_en']:
            expected_z = self.z_reg
            if z_observed != expected_z:
                print(f"Scenario: {scenario}, expected: z={expected_z}, observed: z={z_observed}")
                return False
        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

