class GoldenDUT:
    def __init__(self):
        # Initialize internal state and registers
        self.state_reg = 'A'
        self.z_reg = 0
        self.w_reg = []
        self.cycle_count_reg = 0

    def load(self, signal_vector):
        # Capture the input signals
        reset = signal_vector['reset']
        s = signal_vector['s']
        w = signal_vector['w']

        # Handle reset
        if reset:
            self.state_reg = 'A'
            self.z_reg = 0
            self.w_reg = []
            self.cycle_count_reg = 0
            return

        # FSM logic
        if self.state_reg == 'A':
            if s == 1:
                self.state_reg = 'B'
        elif self.state_reg == 'B':
            # Process input w
            if self.cycle_count_reg < 3:
                self.w_reg.append(w)
                self.cycle_count_reg += 1

            # Evaluate z after 3 cycles in state B
            if self.cycle_count_reg == 3:
                # Check the w values collected so far
                if self.w_reg.count(1) == 2:
                    self.z_reg = 1
                else:
                    self.z_reg = 0
                # Reset to analyze the next window of w inputs
                self.w_reg = []
                self.cycle_count_reg = 0

    def check(self, signal_vector):
        # Determine the expected output state
        expected_z = signal_vector['z']
        # Compare the expected output with the DUT output
        if signal_vector['check_en']:
            if expected_z == self.z_reg:
                return True
            else:
                print(f"Scenario: {signal_vector['scenario']}, expected: z={expected_z}, observed z={self.z_reg}")
                return False
        return True

