class GoldenDUT:
    def __init__(self):
        self.current_state_reg = 0b0  # Initial state is OFF
        self.out_reg = 0b0  # Initial output is 0

    def load(self, signal_vector):
        j = signal_vector['j']
        k = signal_vector['k']
        areset = signal_vector['areset']

        # Determine the next state and output based on inputs
        next_state, output = self.moore_machine_next_state(self.current_state_reg, j, k, areset)

        # Update registers with the new state and output
        self.current_state_reg = next_state
        self.out_reg = output

    def check(self, signal_vector):
        expected_out = self.out_reg
        observed_out = signal_vector['out']

        if expected_out != observed_out:
            print(f"Scenario: {signal_vector['scenario']}, expected: out={expected_out}, observed out={observed_out}")
            return False

        return True

    def moore_machine_next_state(self, current_state, j, k, areset):
        OFF = 0b0
        ON = 0b1

        if areset:
            return OFF, 0b0

        if current_state == OFF:
            if j == 0b0:
                return OFF, 0b0
            else:
                return ON, 0b1
        elif current_state == ON:
            if k == 0b0:
                return ON, 0b1
            else:
                return OFF, 0b0

