    def __init__(self):
        # Initialize the Karnaugh map as a dictionary
        self.kmap = {
            (0, 0): {0b00: 0, 0b01: 0, 0b11: 0, 0b10: 1},
            (0, 1): {0b00: 1, 0b01: 0, 0b11: 0, 0b10: 0},
            (1, 1): {0b00: 1, 0b01: 0, 0b11: 1, 0b10: 1},
            (1, 0): {0b00: 1, 0b01: 0, 0b11: 0, 0b10: 1}
        }

    def load(self, signal_vector):
        # Extract input signals from the signal vector
        c = signal_vector.get('c', 0)
        d = signal_vector.get('d', 0)
        a = signal_vector.get('a', 0)
        b = signal_vector.get('b', 0)

        # Calculate selector input from a and b
        ab = (a << 1) | b

        # Determine the expected output mux_in[3:0] based on the selections {a, b}
        mux_in = [0] * 4
        # Populate mux_in based on the current configuration of c and d
        for sel in range(4):
            # Assign the kmap value for (c, d) and the current selector to the correct index
            mux_in[sel] = self.kmap[(c, d)][sel]

        # Convert list of bits to a binary number
        mux_in_bin = (mux_in[3] << 3) | (mux_in[2] << 2) | (mux_in[1] << 1) | mux_in[0]

        return mux_in_bin

    def check(self, signal_vector):
        # Load expected output values
        expected_output = self.load(signal_vector)

        # Get the actual output values from signal vector
        actual_output = signal_vector.get('mux_in', 0)

        # Compare expected and actual output and return boolean result
        return expected_output == actual_output
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        check_pass = golden_dut.check(vector)
        if check_pass:
            print(f"Passed; vector: {vector}")
        else:
            print(f"Failed; vector: {vector}")
            failed_scenarios.append(vector["scenario"])
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    lines = txt.strip().split("\n")
    signals = []
    for line in lines:
        signal = {}
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1]
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if "x" not in value and "z" not in value:
                    signal[key] = int(value)
                else:
                    signal[key] = value 
        signals.append(signal)
    return signals
