class GoldenDUT:
    def __init__(self):
        # Initialize any inner states if needed
        pass

    def load(self, signal_vector):
        # Extract signals from the signal vector
        a = signal_vector.get('a')
        b = signal_vector.get('b')
        c = signal_vector.get('c')
        d = signal_vector.get('d')

        # Call another method to compute expected output
        expected_output = self.evaluate_mux_in(a, b, c, d)

        # Return the expected outputs in a dictionary form
        return {'mux_in': expected_output}

    def check(self, signal_vector):
        # Call load to get expected output values
        expected_outputs = self.load(signal_vector)
        actual_outputs = signal_vector.get('mux_in')

        # Compare expected outputs with actual outputs from DUT
        return expected_outputs['mux_in'] == actual_outputs

    def evaluate_mux_in(self, a, b, c, d):
        cd = (c << 1) | d

        if a == 0 and b == 0:
            # ab = 00
            return 0 if cd == 0b00 else 1
        elif a == 0 and b == 1:
            # ab = 01
            return 0
        elif a == 1 and b == 1:
            # ab = 11
            return 1 if cd == 0b11 else 0
        elif a == 1 and b == 0:
            # ab = 10
            return 1 if cd in [0b00, 0b10, 0b11] else 0

        return 0
