        self.state_reg = "A"
        self.x_reg = 0
        self.z_reg = 0

    def load(self, signal_vector):
        # Load input x and state transitions based on the signal vector
        self.x_reg = signal_vector['x']

        # Check for asynchronous reset
        if signal_vector['areset']:
            self.state_reg = self.asynchronous_reset()

        # Determine next state based on current state and input x
        else:
            self.state_reg = self.next_state(self.state_reg, self.x_reg)

    def check(self, signal_vector):
        # Calculate the expected output z based on current state and input x
        expected_z = self.expected_z(self.state_reg, self.x_reg)

        # Compare with DUT output
        z_observed = signal_vector['z']
        if expected_z == z_observed:
            return True
        else:
            # Print an error message if expected and observed output don't match
            print(f"Scenario: {signal_vector['scenario']}, expected: z={expected_z}, observed z={z_observed}")
            return False

