        # Determine expected value of 'z' based on current state and input 'x'
        if state == "A":
            if x == 0:
                return 0
            elif x == 1:
                return 1
        elif state == "B":
            if x == 0:
                return 1
            elif x == 1:
                return 0
        raise ValueError("Invalid state")

    def next_state(self, state, x):
        # Determine next state based on current state and input 'x'
        if state == "A":
            if x == 0:
                return "A"
            elif x == 1:
                return "B"
        elif state == "B":
            return "B"
        raise ValueError("Invalid state")

