class GoldenDUT:
    def __init__(self):
        # Initialize inner state variables
        self.consecutive_ones_reg = 0
        self.previous_bit_reg = 0
        self.disc_reg = 0
        self.flag_reg = 0
        self.err_reg = 0

    def load(self, signal_vector):
        # Update inner state based on input signal
        if signal_vector['reset']:
            self.consecutive_ones_reg = 0
            self.previous_bit_reg = 0
        else:
            current_bit = signal_vector['in']
            if current_bit == 1:
                self.consecutive_ones_reg += 1
            else:
                self.consecutive_ones_reg = 0

            self.update_outputs(current_bit)
            self.previous_bit_reg = current_bit

    def update_outputs(self, current_bit):
        # Perform output checks based on current state
        if self.previous_bit_reg == 1 and self.consecutive_ones_reg == 5 and current_bit == 0:
            self.disc_reg = 1
        else:
            self.disc_reg = 0

        if self.previous_bit_reg == 1 and self.consecutive_ones_reg == 6 and current_bit == 0:
            self.flag_reg = 1
        else:
            self.flag_reg = 0

        if self.consecutive_ones_reg >= 7:
            self.err_reg = 1
        else:
            self.err_reg = 0

    def check(self, signal_vector):
        # Compare the expected output with the DUT output
        disc_obs = signal_vector['disc']
        flag_obs = signal_vector['flag']
        err_obs = signal_vector['err']

        error_flag = False

        if self.disc_reg != disc_obs:
            print(f"Scenario: {signal_vector['scenario']}, expected: disc={self.disc_reg}, observed: disc={disc_obs}")
            error_flag = True
        if self.flag_reg != flag_obs:
            print(f"Scenario: {signal_vector['scenario']}, expected: flag={self.flag_reg}, observed: flag={flag_obs}")
            error_flag = True
        if self.err_reg != err_obs:
            print(f"Scenario: {signal_vector['scenario']}, expected: err={self.err_reg}, observed: err={err_obs}")
            error_flag = True

        return not error_flag

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

