class GoldenDUT:
    def __init__(self):
        self.consecutive_ones_reg = 0
        self.disc_reg = False
        self.flag_reg = False
        self.err_reg = False

    def load(self, signal_vector):
        # Reset conditions
        if signal_vector['reset']:
            self.consecutive_ones_reg = 0
            self.disc_reg = False
            self.flag_reg = False
            self.err_reg = False
        else:
            if signal_vector['in'] == 1:
                self.consecutive_ones_reg += 1

                # Check for error condition first
                if self.consecutive_ones_reg > 6:
                    self.err_reg = True
                    self.disc_reg = False
                    self.flag_reg = False
                    # No need to immediately reset the counter, let it stay for error state handling
                elif self.consecutive_ones_reg == 6:
                    # Flag condition
                    self.flag_reg = True
                    self.disc_reg = False
            else:
                if self.consecutive_ones_reg == 5:
                    # Discard condition met on seeing 0 after five 1s
                    self.disc_reg = True
                    self.flag_reg = False  # Reset flag to avoid conflicting states
                else:
                    self.disc_reg = False
                    self.flag_reg = False

                # Reset counter after processing the sequence, not before
                self.consecutive_ones_reg = 0

    def check(self, signal_vector):
        if signal_vector['check_en']:
            disc_expected = self.disc_reg
            flag_expected = self.flag_reg
            err_expected = self.err_reg

            disc_observed = signal_vector['disc']
            flag_observed = signal_vector['flag']
            err_observed = signal_vector['err']

            if (disc_expected == disc_observed and
                flag_expected == flag_observed and
                err_expected == err_observed):
                return True
            else:
                print(f"Scenario: {signal_vector['scenario']}, "
                      f"expected: disc={disc_expected}, flag={flag_expected}, err={err_expected}, "
                      f"observed: disc={disc_observed}, flag={flag_observed}, err={err_observed}")
                return False
        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

