        # Initialize state and counters
        self.state_reg = 'RESET'
        self.count_ones_reg = 0
        self.disc_reg = 0
        self.flag_reg = 0
        self.err_reg = 0

    def load(self, signal_vector):
        # Load the signals
        in_signal = signal_vector['in']
        reset = signal_vector['reset']

