        if reset:
            self.state_reg = 'RESET'
            self.count_ones_reg = 0
            self.disc_reg = 0
            self.flag_reg = 0
            self.err_reg = 0
        else:
            # Clear outputs by default unless set during this cycle
            self.disc_reg = 0
            self.flag_reg = 0
            self.err_reg = 0

            # State transition logic based on input signal
            if self.state_reg == 'RESET':
                if in_signal == 0:
                    self.state_reg = 'CHECK_011111'
                    self.count_ones_reg = 0  # Reset the count to prepare for new sequence
                else:
