                    elif self.count_ones_reg == 6:
                        self.state_reg = 'FLAG'
                    self.count_ones_reg = 0  # Reset after handling a sequence

            elif self.state_reg == 'DISCARD':
                self.disc_reg = 1
                self.state_reg = 'CHECK_011111'
                self.count_ones_reg = 0

            elif self.state_reg == 'FLAG':
                self.flag_reg = 1
                self.state_reg = 'CHECK_011111'
                self.count_ones_reg = 0

            elif self.state_reg == 'ERROR':
                self.err_reg = 1
                if in_signal == 0:
                    self.count_ones_reg = 0
                    self.state_reg = 'CHECK_011111'
                else:
                    self.count_ones_reg += 1

    def check(self, signal_vector):
