class GoldenDUT:
    def __init__(self):
        self.s_reg = '000'           # Initial state of sensors as a 3-bit binary string
        self.fr3_reg = 0
        self.fr2_reg = 0
        self.fr1_reg = 0
        self.dfr_reg = 0

    def load(self, signal_vector):
        # Update inner state based on input signals
        if signal_vector['reset']:
            # Set all flow rate outputs to high during reset
            self.s_reg = '000'
            self.fr3_reg = 1
            self.fr2_reg = 1
            self.fr1_reg = 1
            self.dfr_reg = 1
        else:
            self.s_reg = f"{signal_vector['s']:03b}"

    def calculate_flow_rate(self, current_sensors, previous_sensors):
        # Initialize all flow rate outputs to zero
        fr3, fr2, fr1, dfr = 0, 0, 0, 0

        # Define flow rate logic based on current sensor readings
        if current_sensors == '000':
            fr3, fr2, fr1 = 1, 1, 1  # All flow rates high for lowest level
        elif current_sensors == '001':
            fr2, fr1 = 1, 1  # Nominal flow rate just above lowest level
        elif current_sensors == '011':
            fr1 = 1  # Nominal flow rate for between middle and low sensor
        elif current_sensors == '111':
            fr3, fr2, fr1 = 0, 0, 0  # No flow rate above the highest level

        # Determine if the supplemental flow rate control should activate
        if int(previous_sensors, 2) < int(current_sensors, 2):
            dfr = 1  # Increase flow rate if moving to a higher sensor reading level

        return {'fr3': fr3, 'fr2': fr2, 'fr1': fr1, 'dfr': dfr}

    def check(self, signal_vector):
        # Convert signal to binary string representation
        current_sensors = f"{signal_vector['s']:03b}"
        expected_outputs = self.calculate_flow_rate(current_sensors, self.s_reg)

        # Determine if outputs match expected values
        result = True
        if signal_vector['check_en']:
            if (signal_vector['fr3'], signal_vector['fr2'], 
                signal_vector['fr1'], signal_vector['dfr']) != (
                expected_outputs['fr3'], expected_outputs['fr2'], 
                expected_outputs['fr1'], expected_outputs['dfr']):

                print(f"Scenario: {signal_vector['scenario']}, "
                      f"expected: fr3={expected_outputs['fr3']} fr2={expected_outputs['fr2']} "
                      f"fr1={expected_outputs['fr1']} dfr={expected_outputs['dfr']}, "
                      f"observed: fr3={signal_vector['fr3']} fr2={signal_vector['fr2']} "
                      f"fr1={signal_vector['fr1']} dfr={signal_vector['dfr']}")
                result = False

        # Update the internal sensor state for the next cycle
        self.s_reg = current_sensors
        return result
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

