class GoldenDUT:
    def __init__(self):
        self.waiting_for_start_reg = True
        self.data_bits_collected_reg = 0
        self.byte_received_correctly_reg = False
        self.current_data_reg = 0

        # Constants
        self.START_BIT = 0
        self.STOP_BIT = 1
        self.DATA_BIT_COUNT = 8

    def load(self, signal_vector):
        # Reset indication handling
        if signal_vector['reset'] == 1:
            self.__init__()  # Reset state machine
            return

        in_bit = signal_vector['in']

        # FSM Logic
        if self.waiting_for_start_reg:
            if in_bit == self.START_BIT:
                self.waiting_for_start_reg = False
                self.data_bits_collected_reg = 0  # Reset data bit counter
                self.byte_received_correctly_reg = False  # Clear byte reception status
                self.current_data_reg = 0  # Reset the data accumulator
        elif self.data_bits_collected_reg < self.DATA_BIT_COUNT:
            # Shift in the new data bit on each cycle
            self.current_data_reg = (self.current_data_reg >> 1) | (in_bit << (self.DATA_BIT_COUNT - 1))
            self.data_bits_collected_reg += 1
        else:
            # Expecting stop bit
            if in_bit == self.STOP_BIT:
                self.byte_received_correctly_reg = True

            # Reset for the next byte
            self.waiting_for_start_reg = True
            self.data_bits_collected_reg = 0
            self.current_data_reg = 0

    def check(self, signal_vector):
        # If check is enabled, verify correctness
        if signal_vector.get('check_en', False):
            done_observed = signal_vector['done']
            done_expected = self.byte_received_correctly_reg

            if done_expected != done_observed:
                print(f"Scenario: {signal_vector['scenario']}, expected done={done_expected}, observed done={done_observed}")
                return False
        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

