class GoldenDUT:
    START_BIT = 0
    STOP_BIT = 1
    DATA_BITS = 8

    def __init__(self):
        self.state_reg = 'IDLE'
        self.data_buffer_reg = []
        self.done_reg = 0

    def load(self, signal_vector):
        if signal_vector['reset']:
            self.reset_state()
            return

        in_bit = signal_vector['in']

        if self.state_reg == 'IDLE':
            if in_bit == self.START_BIT:
                self.state_reg = 'RECEIVING_DATA'
                self.data_buffer_reg = []

        elif self.state_reg == 'RECEIVING_DATA':
            self.data_buffer_reg.append(in_bit)
            if len(self.data_buffer_reg) == self.DATA_BITS:
                self.state_reg = 'EXPECT_STOP'

        elif self.state_reg == 'EXPECT_STOP':
            if in_bit == self.STOP_BIT:
                self.done_reg = 1
                self.state_reg = 'IDLE'
            else:
                self.state_reg = 'WAIT_FOR_STOP'

        elif self.state_reg == 'WAIT_FOR_STOP':
            if in_bit == self.STOP_BIT:
                # Only reset the flag, don't mark the frame as done
                self.reset_state()  # Reset to idle since stop received, do not set done_reg

    def check(self, signal_vector):
        expected_done = self.done_reg

        if signal_vector['check_en']:
            result = expected_done == signal_vector['done']
            self.done_reg = 0  # Reset done_reg after check
            if not result:
                print(f"Scenario: {signal_vector['scenario']}, expected: done={expected_done}, observed done={signal_vector['done']}")
            return result

        return True

    def reset_state(self):
        self.state_reg = 'IDLE'
        self.data_buffer_reg = []
        self.done_reg = 0

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

