class GoldenDUT:
    IDLE = 0
    START_BIT = 1
    DATA_BITS = 2
    STOP_BIT = 3

    def __init__(self):
        self.state_reg = GoldenDUT.IDLE
        self.data_byte_reg = 0
        self.bit_counter_reg = 0
        self.out_byte_reg = 0
        self.done_reg = False
        self.reset_reg = False
        # Additional noise filter/counter
        self.noise_counter = 0
        self.expected_idle_bits = 10

    def load(self, signal_vector):
        self.reset_reg = signal_vector['reset']
        if self.reset_reg:
            self.__init__()
        else:
            in_signal = signal_vector['in']
            self._fsm_logic(in_signal)

    def _fsm_logic(self, in_signal):
        if self.state_reg == GoldenDUT.IDLE:
            # Introduce noise filtering
            if in_signal == 0:
                if self.noise_counter >= self.expected_idle_bits:
                    self.state_reg = GoldenDUT.START_BIT
                    self.noise_counter = 0  # Reset noise counter
            else:
                self.noise_counter += 1

        elif self.state_reg == GoldenDUT.START_BIT:
            # Verify it's a start bit
            if in_signal == 0:
                self.state_reg = GoldenDUT.DATA_BITS
                self.data_byte_reg = 0
                self.bit_counter_reg = 0

        elif self.state_reg == GoldenDUT.DATA_BITS:
            self.data_byte_reg |= (in_signal << self.bit_counter_reg)
            self.bit_counter_reg += 1
            if self.bit_counter_reg == 8:
                self.state_reg = GoldenDUT.STOP_BIT

        elif self.state_reg == GoldenDUT.STOP_BIT:
            if in_signal == 1:
                self.out_byte_reg = self.data_byte_reg & 0xFF  # Ensure 8 bits
                self.done_reg = True
            else:
                self.out_byte_reg = 0
                self.done_reg = False
            # Return to IDLE only if sufficient idle bits are seen
            self.state_reg = GoldenDUT.IDLE
            self.noise_counter = 0

    def check(self, signal_vector):
        expected_out_byte = self.out_byte_reg if self.done_reg else 'X'
        expected_done = self.done_reg

        observed_out_byte = signal_vector['out_byte']
        observed_done = signal_vector['done']

        if expected_out_byte == 'X':
            return True  # out_byte is don't care if done is False

        if (expected_out_byte == observed_out_byte) and (expected_done == observed_done):
            return True
        else:
            print(f"Scenario: {signal_vector['scenario']}, expected: out_byte={expected_out_byte}, done={expected_done}, observed: out_byte={observed_out_byte}, done={observed_done}")
            return False

    def _reset_to_idle_if_idle_reached(self, in_signal):
        if self.state_reg == GoldenDUT.IDLE and in_signal == 1:
            self.noise_counter += 1
            if self.noise_counter >= self.expected_idle_bits:
                self.noise_counter = 0
                self.state_reg = GoldenDUT.IDLE
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

