class GoldenDUT:
    def __init__(self):
        self.state_reg = 'IDLE'
        self.byte_buffer_reg = 0
        self.bit_count_reg = 0
        self.done_reg = 0
        self.out_byte_reg = 0
        self.in_reg = 0
        self.reset_reg = 0

    def load(self, signal_vector):
        self.in_reg = signal_vector['in']
        self.reset_reg = signal_vector['reset']

        if self.reset_reg:
            self.state_reg = 'IDLE'
            self.byte_buffer_reg = 0
            self.bit_count_reg = 0
            self.done_reg = 0
            self.out_byte_reg = 0
        else:
            self.fsm_logic()

    def check(self, signal_vector):
        if signal_vector['check_en']:
            expected_done = True if self.done_reg else False
            expected_out_byte = self.out_byte_reg if self.done_reg else None

            if (expected_out_byte == signal_vector['out_byte']) and (expected_done == signal_vector['done']):
                return True
            else:
                print(f"Scenario: {signal_vector['scenario']}, expected: out_byte={expected_out_byte}, done={expected_done}, "
                      f"observed: out_byte={signal_vector['out_byte']}, done={signal_vector['done']}")
                return False
        return True

    def fsm_logic(self):
        if self.state_reg == 'IDLE':
            if self.in_reg == 0:
                # Detects start bit
                self.state_reg = 'RECEIVING'
                self.byte_buffer_reg = 0
                self.bit_count_reg = 0
                self.done_reg = 0

        elif self.state_reg == 'RECEIVING':
            if self.bit_count_reg < 8:
                self.byte_buffer_reg |= (self.in_reg << self.bit_count_reg)
                self.bit_count_reg += 1
            elif self.bit_count_reg == 8:
                if self.in_reg == 1:  # Valid stop bit
                    self.done_reg = 1
                    self.out_byte_reg = self.byte_buffer_reg
                    self.state_reg = 'DONE'
                else:
                    self.state_reg = 'WAIT_STOP'

        elif self.state_reg == 'WAIT_STOP':
            if self.in_reg == 1:  # Wait for the correct stop bit
                self.state_reg = 'IDLE'
            self.done_reg = 0

        elif self.state_reg == 'DONE':
            # After done is set, transition back to IDLE on the next cycle
            self.reset_after_done()

    def reset_after_done(self):
        # Ensure that after `done` is set, it resets next cycle in receiving any further bits.
        self.state_reg = 'IDLE'
        self.byte_buffer_reg = 0
        self.bit_count_reg = 0
        self.done_reg = 0
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

