import numpy as np

class GoldenDUT:
    def __init__(self):
        # Initialize inner states/values
        self.PHT_reg = np.zeros(128, dtype=np.int8)
        self.global_history_reg = 0b0000000
        self.predict_taken_reg = 0
        self.predict_history_reg = 0

    def load(self, signal_vector):
        if signal_vector['train_valid']:
            self.handle_training(signal_vector)

        if signal_vector['predict_valid']:
            self.handle_prediction(signal_vector)

    def handle_prediction(self, signal_vector):
        predict_pc = signal_vector['predict_pc']
        index = self.xor_index(predict_pc, self.global_history_reg)

        counter_value = self.PHT_reg[index]
        self.predict_taken_reg = 1 if counter_value >= 2 else 0

        # Compute predict_history_reg based on the predict_taken result
        prediction_history = ((self.global_history_reg << 1) | self.predict_taken_reg) & 0b01111111

        # Only update global history for prediction if no training occurred
        if not signal_vector['train_valid']:
            self.global_history_reg = prediction_history

        self.predict_history_reg = prediction_history

    def handle_training(self, signal_vector):
        train_pc = signal_vector['train_pc']
        train_taken = signal_vector['train_taken']
        train_mispredicted = signal_vector['train_mispredicted']
        train_history = signal_vector['train_history']

        index = self.xor_index(train_pc, train_history)

        if train_taken:
            if self.PHT_reg[index] < 3:
                self.PHT_reg[index] += 1
        else:
            if self.PHT_reg[index] > 0:
                self.PHT_reg[index] -= 1

        # Correctly update global history for misprediction recovery or on normal outcome confirmation
        if train_mispredicted:
            self.global_history_reg = (train_history << 1 | train_taken) & 0b01111111

    def xor_index(self, pc, history):
        return pc ^ history

    def check(self, signal_vector):
        if not signal_vector['predict_valid']:
            return True  # No prediction was made, nothing to check

        expect_taken = self.predict_taken_reg
        expect_history = self.predict_history_reg
        actual_taken = signal_vector['predict_taken']
        actual_history = signal_vector['predict_history']

        if expect_taken != actual_taken or expect_history != actual_history:
            print(f"Scenario: {signal_vector['scenario']}, "
                  f"expected: predict_taken={expect_taken}, predict_history={expect_history}, "
                  f"observed: predict_taken={actual_taken}, predict_history={actual_history}")
            return False

        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

