import numpy as np

class GoldenDUT:
    def __init__(self):
        self.PHT_reg = np.zeros(128, dtype=np.uint8)  # 128-entry table of two-bit saturating counters
        self.global_history_reg = 0b0000000  # 7-bit global history register
        self.predict_taken_reg = 0
        self.predict_history_reg = 0b0000000
        self.current_global_history = 0b0000000  # Initialize the current global history

    def hash_index(self, pc: int, history: int) -> int:
        return pc ^ history

    def load(self, signal_vector):
        if signal_vector['predict_valid']:
            self.predict(signal_vector['predict_pc'])

        if signal_vector['train_valid']:
            self.train(signal_vector['train_pc'], 
                       signal_vector['train_history'], 
                       signal_vector['train_taken'],
                       signal_vector['train_mispredicted'])

    def predict(self, pc: int):
        # Use the hashed index from the current global history
        index = self.hash_index(pc, self.global_history_reg)
        counter = self.PHT_reg[index]

        # Predict 'taken' if counter is in states 2 or 3
        self.predict_taken_reg = (counter >> 1) == 1
        self.predict_history_reg = self.global_history_reg

        # Keep a copy of the current global history
        self.current_global_history = self.global_history_reg

        # Update the global history tentatively
        tentative_history = ((self.global_history_reg << 1) | self.predict_taken_reg) & 0x7F

        # Only apply tentative update at the predict stage
        self.predicted_global_history = tentative_history

    def train(self, pc: int, history: int, actual_taken: bool, mispredicted: bool):
        index = self.hash_index(pc, history)
        counter = self.PHT_reg[index]

        # Adjust counter in PHT based on actual outcome
        if actual_taken:
            if counter < 0b11:
                self.PHT_reg[index] += 1
        else:
            if counter > 0b00:
                self.PHT_reg[index] -= 1

        # Recover global history on misprediction based on post-misprediction operation
        if mispredicted:
            # Roll back to the correct global history state after misprediction
            self.global_history_reg = (history << 1 | int(actual_taken)) & 0x7F
        else:
            # Commit the tentatively updated history if trained correctly
            self.global_history_reg = self.predicted_global_history

    def check(self, signal_vector):
        if not signal_vector['check_en']:
            return True

        a_observed = signal_vector['predict_taken']
        b_observed = signal_vector['predict_history']

        expected_taken = self.predict_taken_reg
        expected_history = self.predict_history_reg

        if a_observed != expected_taken or b_observed != expected_history:
            print(f"Scenario: {signal_vector['scenario']}, "
                  f"expected predict_taken={expected_taken}, observed predict_taken={a_observed}, "
                  f"expected predict_history={expected_history}, observed predict_history={b_observed}")
            return False

        return True

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

