import numpy as np

# Constants for GShare Predictor
PHT_ENTRIES = 128
COUNTER_MAX = 0b11  # Maximum value of 2-bit saturating counters
COUNTER_MIN = 0b00  # Minimum value of 2-bit saturating counters

class GoldenDUT:
    def __init__(self):
        # Initialize internal registers
        self.global_history_reg = 0b0
        self.pht_reg = np.array([1] * PHT_ENTRIES, dtype=int)

    def load(self, signal_vector):
        # Handle asynchronous reset
        if signal_vector['areset']:
            self.global_history_reg = 0b0
            self.pht_reg = np.array([1] * PHT_ENTRIES, dtype=int)
            return  # Ensure no further processing during reset

        if signal_vector['train_valid']:
            # Perform training update
            index = self.xor_index(signal_vector['train_pc'], signal_vector['train_history'])
            self.update_counter(index, signal_vector['train_taken'])

            if signal_vector['train_mispredicted']:
                # Recover global history
                self.global_history_reg = (signal_vector['train_history'] << 1 | signal_vector['train_taken']) & 0b01111111
            else:
                # Update global history with actual outcome
                self.global_history_reg = (self.global_history_reg << 1 | signal_vector['train_taken']) & 0b01111111

        elif signal_vector['predict_valid']:
            # For predictions, global history is not updated here to prevent interference with training
            pass

    def check(self, signal_vector):
        if signal_vector['predict_valid']:
            index = self.xor_index(signal_vector['predict_pc'], self.global_history_reg)
            counter = self.pht_reg[index]
            taken = counter >= 0b10
            predicted_taken = signal_vector['predict_taken']
            predicted_history = signal_vector['predict_history']

            # Check the predicted results
            expected_taken = taken
            expected_history = self.global_history_reg

            if (predicted_taken == expected_taken) and (predicted_history == expected_history):
                return True
            else:
                print(f"Scenario: {signal_vector['scenario']}, expected: taken={expected_taken}, history={expected_history}, observed taken={predicted_taken}, history={predicted_history}")
                return False
        return True

    def xor_index(self, pc, history):
        """Compute the index by XORing the PC and the global history"""
        return (pc ^ history) & 0b01111111  # Ensure 7-bit index

    def update_counter(self, index, taken):
        """Update the counter based on the actual outcome"""
        if taken:
            # Increment counter towards "strongly taken"
            if self.pht_reg[index] < COUNTER_MAX:
                self.pht_reg[index] += 1
        else:
            # Decrement counter towards "strongly not taken"
            if self.pht_reg[index] > COUNTER_MIN:
                self.pht_reg[index] -= 1
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

