import numpy as np

class GoldenDUT:
    def __init__(self):
        # Initialize the pattern history table (PHT) with 2-bit saturating counters set to zero
        self.PHT = np.zeros(128, dtype=np.uint8)
        # Initialize the 7-bit global history register
        self.global_history_reg = 0b0000000
        # Store the last results for comparison
        self.predict_taken_reg = False
        self.predict_history_reg = 0b0000000

    def load(self, signal_vector):
        # Load input signals and update the internal state
        if signal_vector['predict_valid']:
            self.predict(signal_vector['predict_pc'])

        if signal_vector['train_valid']:
            self.train(signal_vector['train_pc'], signal_vector['train_history'],
                       signal_vector['train_taken'], signal_vector['train_mispredicted'])

    def _index(self, pc, history):
        # Calculate the PHT index by XOR'ing the PC and global history
        return pc ^ history

    def predict(self, pc):
        # Generate a prediction based on the PC and the current global history
        index = self._index(pc, self.global_history_reg)
        counter = self.PHT[index]
        # Predict taken based on counter values
        self.predict_taken_reg = counter >= 2  # Counter values 2 or 3 predict taken
        self.predict_history_reg = self.global_history_reg

    def train(self, pc, history, actual_taken, mispredicted):
        # Train the PHT based on actual outcomes
        index = self._index(pc, history)

        # Adjust the counter value based on the actual branch outcome
        if actual_taken:
            if self.PHT[index] < 3:
                self.PHT[index] += 1
        else:
            if self.PHT[index] > 0:
                self.PHT[index] -= 1

        if mispredicted:
            # Recover the global history to the state after the mispredicted branch
            self.global_history_reg = history
        else:
            # Update the global history normally
            self.update_history(actual_taken)

    def update_history(self, taken):
        # Update the internal global history based on branch outcome
        self.global_history_reg = ((self.global_history_reg << 1) | taken) & 0b1111111

    def check(self, signal_vector):
        # Check the expected outputs against the DUT outputs
        predicted_taken = self.predict_taken_reg
        predicted_history = self.predict_history_reg

        observed_taken = signal_vector['predict_taken']
        observed_history = signal_vector['predict_history']

        if predicted_taken == observed_taken and predicted_history == observed_history:
            return True
        else:
            # Print an error message if observed values do not match the expected ones
            print(f"Scenario: {signal_vector['scenario']}, "
                  f"expected: predict_taken={predicted_taken}, predict_history={predicted_history}, "
                  f"observed: predict_taken={observed_taken}, predict_history={observed_history}")
            return False
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

