import numpy as np

# Constants
PHT_SIZE = 128
HISTORY_BITS = 7

class GoldenDUT:
    def __init__(self):
        self.global_history_reg = 0  # Initialize global history
        self.pht = np.ones(PHT_SIZE, dtype=np.uint8)  # Initialize PHT to weakly not taken (01)
        self.predict_taken_reg = 0
        self.predict_history_reg = 0

    def load(self, signal_vector):
        if signal_vector['areset']:
            self.global_history_reg = 0
        else:
            if signal_vector['train_valid']:
                # Prioritize training when both train and predict are valid
                self.train(signal_vector)

            if signal_vector['predict_valid']:
                self.predict(signal_vector)

    def train(self, signal_vector):
        index = self.compute_index(signal_vector['train_pc'], signal_vector['train_history'])
        train_taken = signal_vector['train_taken']

        # Update PHT based on the actual branch outcome
        if train_taken:
            if self.pht[index] < 0b11:
                self.pht[index] += 1
        else:
            if self.pht[index] > 0b00:
                self.pht[index] -= 1

        if signal_vector['train_mispredicted']:
            # Recover the branch history register to the state immediately after the mispredicting branch completes execution
            # This correction ensures the history state is recovered properly
            self.global_history_reg = ((signal_vector['train_history'] << 1) | train_taken) & 0x7F
        else:
            # Update global history register immediately after non-mispredicted training
            self.global_history_reg = ((self.global_history_reg << 1) | train_taken) & 0x7F

    def predict(self, signal_vector):
        index = self.compute_index(signal_vector['predict_pc'], self.global_history_reg)
        self.predict_taken_reg = (self.pht[index] >> 1) & 0b1

        if not signal_vector['train_valid']:
