import numpy as np

# Constants for PHT and history
PHT_SIZE = 128
MAX_COUNTS = 3  # Maximum value for two-bit saturating counter
HISTORY_BITS = 7

class GoldenDUT:
    def __init__(self):
        # Initialize the branch predictor states
        self.global_history_reg = 0
        self.pht_reg = [1] * PHT_SIZE  # Initialize PHT with 1 (weakly taken)

    def saturating_counter_update(self, counter, taken):
        # Update the saturating counter based on branch outcome
        if taken and counter < MAX_COUNTS:
            return counter + 1
        elif not taken and counter > 0:
            return counter - 1
        return counter

    def gshare_predictor(self, predict_pc, global_history):
        # Predict the branch outcome using gshare method
        index = predict_pc ^ global_history  # XOR for index generation
        counter = self.pht_reg[index]
        predict_taken = counter >= 2  # Taken if counter is 2 or 3
        return predict_taken, global_history

    def gshare_train(self, train_pc, train_history, train_taken, train_mispredicted):
        # Update PHT and possibly the global history during training
        index = train_pc ^ train_history
        self.pht_reg[index] = self.saturating_counter_update(self.pht_reg[index], train_taken)

        if train_mispredicted:
            # Update global history based on misprediction recovery
            new_train_history = (train_history << 1) | train_taken
            return new_train_history & ((1 << HISTORY_BITS) - 1)
        else:
            # Correct handling of global history update when not mispredicted
            new_global_history = (self.global_history_reg << 1) | train_taken
            return new_global_history & ((1 << HISTORY_BITS) - 1)

    def load(self, signal_vector):
        if signal_vector['areset']:
            # Reset the branch predictor components
            self.global_history_reg = 0
            self.pht_reg = [1] * PHT_SIZE

        if signal_vector['train_valid']:
            # Update global history register based on training info
            # Ensure training updates the history with highest priority
            self.global_history_reg = self.gshare_train(
                signal_vector['train_pc'],
                signal_vector['train_history'],
                signal_vector['train_taken'],
                signal_vector['train_mispredicted']
            )

    def check(self, signal_vector):
        if signal_vector['check_en']:
            if signal_vector['predict_valid']:
                # Predict and compare to expected output
                predict_taken, predict_history = self.gshare_predictor(
                    signal_vector['predict_pc'],
                    self.global_history_reg
                )
                if (predict_taken != signal_vector['predict_taken'] or
                    predict_history != signal_vector['predict_history']):
                    print(f"Scenario: {signal_vector['scenario']}, expected: predict_taken={predict_taken}, "
                          f"predict_history={predict_history}, observed predict_taken={signal_vector['predict_taken']}, "
                          f"predict_history={signal_vector['predict_history']}")
                    return False
        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
