import numpy as np

# Constants
TABLE_SIZE = 128   # 128-entry table
COUNTER_MAX = 0b11  # 2-bit saturating counter max value
COUNTER_MIN = 0b00  # 2-bit saturating counter min value

class GoldenDUT:
    def __init__(self):
        # Initialize internal registers
        self.global_history_reg = 0b0000000
        self.pht_reg = np.full(TABLE_SIZE, 0b01, dtype=int)  # Weakly not taken
        # Registers to hold prediction results for checking consistency
        self.predict_taken_reg = None
        self.predict_history_reg = None

    def xor_index(self, pc, global_history):
        """Calculate the index in the PHT using XOR of PC and global history."""
        return pc ^ global_history

    def update_counter(self, current_value, taken):
        """Update the 2-bit saturating counter based on the branch outcome."""
        if taken:
            return min(current_value + 1, COUNTER_MAX)
        else:
            return max(current_value - 1, COUNTER_MIN)

    def predict(self, predict_pc):
        """Generate a branch prediction using the PHT and global history register."""
        index = self.xor_index(predict_pc, self.global_history_reg)
        # Corrected prediction logic to ensure MSB is used as a valid predict_taken
        predict_taken = (self.pht_reg[index] >> 1) & 0b1  # Correct usage of MSB for branch prediction
        return predict_taken, self.global_history_reg

    def train(self, train_pc, train_history, train_taken):
        """Update the PHT based on training and adjust the global history register."""
        index = self.xor_index(train_pc, train_history)
        self.pht_reg[index] = self.update_counter(self.pht_reg[index], train_taken)

        # Update the global history register correctly after training
        self.global_history_reg = ((train_history << 1) | train_taken) & 0b1111111

    def handle_misprediction(self, train_history, train_taken):
        """Restore the global history register when a misprediction is detected."""
        # Correct restoration of global history 
        self.global_history_reg = ((train_history << 1) | train_taken) & 0b1111111

    def load(self, signal_vector):
        """Load the important input signals and change inner values accordingly."""
        if signal_vector['train_valid']:
            if signal_vector['train_mispredicted']:
                self.handle_misprediction(signal_vector['train_history'], signal_vector['train_taken'])
            else:
                self.train(signal_vector['train_pc'], signal_vector['train_history'], signal_vector['train_taken'])

        if signal_vector['predict_valid']:
            self.predict_taken_reg, self.predict_history_reg = self.predict(signal_vector['predict_pc'])

    def check(self, signal_vector):
        """Check the expected output values and compare them with DUT."""
        if signal_vector['check_en']:
            expected_predict_taken, expected_predict_history = self.predict(signal_vector['predict_pc'])
            if expected_predict_taken != signal_vector['predict_taken']:
                print(f"Scenario: {signal_vector['scenario']}, expected: predict_taken={expected_predict_taken}, observed predict_taken={signal_vector['predict_taken']}")
                return False

            if expected_predict_history != signal_vector.get('predict_history', 'No value'):
                print(f"Scenario: {signal_vector['scenario']}, expected: predict_history={expected_predict_history}, observed predict_history={signal_vector.get('predict_history', 'No value')}")
                return False

        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

