import numpy as np

class GoldenDUT:
    def __init__(self):
        self.PHT = np.full(128, 0b10, dtype=np.uint8)  # Initialize PHT with 'Weakly Taken'
        self.global_branch_history_reg = 0b0000000  # 7-bit global history
        self.predict_taken_reg = 0  # Predicted branch direction (1: taken, 0: not taken)
        self.predict_history_reg = 0b0000000  # Predicted global history

    def load(self, signal_vector):
        # Load and update internal states according to the input signals for a new clock cycle
        self.predict_valid = signal_vector['predict_valid']
        self.predict_pc = signal_vector['predict_pc']
        self.train_valid = signal_vector['train_valid']
        self.train_taken = signal_vector['train_taken']
        self.train_mispredicted = signal_vector['train_mispredicted']
        self.train_history = signal_vector['train_history']
        self.train_pc = signal_vector['train_pc']

        # Execute training phase first if training is valid
        if self.train_valid:
            self.execute_training()

        # Then execute prediction phase if prediction is valid
        if self.predict_valid:
            self.execute_prediction()

    def execute_prediction(self):
        index = self.get_index(self.predict_pc, self.global_branch_history_reg)
        self.predict_taken_reg = 1 if self.PHT[index] in (0b10, 0b11) else 0
        self.predict_history_reg = self.global_branch_history_reg

        # Update global history after fetching the prediction
        self.global_branch_history_reg = (
            (self.global_branch_history_reg << 1) | self.predict_taken_reg
        ) & 0b1111111  # Ensure 7-bit width

    def execute_training(self):
        index = self.get_index(self.train_pc, self.train_history)

        # Adjust PHT counter based on actual branch outcome
        if self.train_taken:
            self.PHT[index] = min(self.PHT[index] + 1, 0b11)
        else:
            self.PHT[index] = max(self.PHT[index] - 1, 0b00)

        # On misprediction, recover global history to post-misprediction state
        if self.train_mispredicted:
            self.global_branch_history_reg = (
                (self.train_history << 1) | self.train_taken
            ) & 0b1111111

    def get_index(self, pc, history):
        return (pc ^ history) & 0b1111111  # Calculate 7-bit index using XOR

    def check(self, signal_vector):
        if not signal_vector['check_en']:
            return True

        predict_taken_observed = signal_vector.get('predict_taken', 'x')
        predict_history_observed = signal_vector.get('predict_history', 'x')

        # Check if the predicted and actual values match
        if (self.predict_taken_reg != predict_taken_observed or
            self.predict_history_reg != predict_history_observed):
            print(f"Scenario: {signal_vector['scenario']}, "
                  f"expected: predict_taken={self.predict_taken_reg}, "
                  f"predict_history={self.predict_history_reg}, "
                  f"observed predict_taken={predict_taken_observed}, "
                  f"observed predict_history={predict_history_observed}")
            return False

        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

