import numpy as np

class GoldenDUT:
    def __init__(self):
        # Initialize internal state with zeros
        self.q_reg = np.zeros((16, 16), dtype=int)
        self.data_reg = np.zeros((16, 16), dtype=int)

    def load(self, signal_vector):
        # Load data if load signal is high
        if signal_vector['load']:
            self.data_reg = self.convert_to_grid(signal_vector['data'])
            self.q_reg = self.data_reg.copy()

    def check(self, signal_vector):
        if signal_vector['check_en']:
            expected_q = self.expected_next_state(self.q_reg)
            observed_q = self.convert_to_grid(signal_vector['q'])
            if not np.array_equal(expected_q, observed_q):
                print(f"Scenario: {signal_vector['scenario']}, expected: q={expected_q}, observed q={observed_q}")
                return False
        return True

    def update_state(self):
        self.q_reg = self.expected_next_state(self.q_reg)

    @staticmethod
    def get_neighbour_indices(x, y, grid_size):
        return [
            ((x-1) % grid_size, (y-1) % grid_size),
            ((x-1) % grid_size, y % grid_size),
            ((x-1) % grid_size, (y+1) % grid_size),
            (x % grid_size, (y-1) % grid_size),
            (x % grid_size, (y+1) % grid_size),
            ((x+1) % grid_size, (y-1) % grid_size),
            ((x+1) % grid_size, y % grid_size),
            ((x+1) % grid_size, (y+1) % grid_size)
        ]

    def count_live_neighbours(self, grid, x, y):
        grid_size = grid.shape[0]
        neighbours = self.get_neighbour_indices(x, y, grid_size)
        live_neighbours = sum(grid[nx, ny] for nx, ny in neighbours)
        return live_neighbours

    def next_cell_state(self, current_state, live_neighbours):
        if live_neighbours < 2 or live_neighbours > 3:
            return 0
        elif live_neighbours == 3:
            return 1
        else:
            return current_state

    def update_grid(self, grid):
        grid_size = grid.shape[0]
        new_grid = np.zeros_like(grid)
        for x in range(grid_size):
            for y in range(grid_size):
                live_neighbours = self.count_live_neighbours(grid, x, y)
                new_grid[x, y] = self.next_cell_state(grid[x, y], live_neighbours)
        return new_grid

    def expected_next_state(self, current_grid):
        return self.update_grid(current_grid)

    @staticmethod
    def convert_to_vector(grid):
        flat_array = grid.flatten()
        bitstring = ''.join(str(bit) for bit in flat_array)
        return int(bitstring, 2)

    @staticmethod
    def convert_to_grid(vector):
        bitstring = format(vector, '0256b')
        flat_array = np.array([int(bit) for bit in bitstring])
        return flat_array.reshape(16, 16)
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

