import numpy as np

class GoldenDUT:
    def __init__(self):
        # Initialize inner state with zeros
        self.q_reg = 0

    def load(self, signal_vector):
        # Load data into the internal state
        if signal_vector['load']:
            self.q_reg = signal_vector['data']

    def check(self, signal_vector):
        if signal_vector['check_en']:
            expected_output = self.calculate_next_state(self.q_reg)
            observed_output = signal_vector['q']
            if expected_output != observed_output:
                print(f"Scenario: {signal_vector['scenario']}, expected: q={expected_output}, observed: q={observed_output}")
                return False
            return True
        return True

    def calculate_next_state(self, data):
        grid = self.binary_to_grid(data)
        next_grid = self.apply_rules(grid)
        return self.grid_to_binary(next_grid)

    def binary_to_grid(self, data):
        bits = f"{data:0256b}"
        grid = np.array([int(bit) for bit in bits]).reshape((16, 16))
        return grid

    def grid_to_binary(self, grid):
        flat_grid = grid.flatten()
        binary_str = ''.join(str(int(bit)) for bit in flat_grid)
        return int(binary_str, 2)

    def apply_rules(self, grid):
        new_grid = np.zeros_like(grid)
        for row in range(16):
            for col in range(16):
                alive_neighbours = self.count_neighbours(grid, row, col)
                if alive_neighbours < 2 or alive_neighbours > 3:
                    new_grid[row, col] = 0
                elif alive_neighbours == 3:
                    new_grid[row, col] = 1
                else:
                    new_grid[row, col] = grid[row, col]
        return new_grid

    def count_neighbours(self, grid, row, col):
        neighbours = 0
        for r_offset in [-1, 0, 1]:
            for c_offset in [-1, 0, 1]:
                if r_offset == 0 and c_offset == 0:
                    continue
                new_row = (row + r_offset) % 16
                new_col = (col + c_offset) % 16
                neighbours += grid[new_row, new_col]
        return neighbours
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
