class GoldenDUT:
    def __init__(self):
        self.q_reg = np.zeros((16, 16), dtype=int)  # 16x16 grid initialized to 0

    def load(self, signal_vector):
        if signal_vector['load']:
            self.q_reg = self.vector_to_grid(signal_vector['data'])

    def check(self, signal_vector):
        if signal_vector['check_en']:
            expected_state = self.simulate_life_step(self.q_reg)
            observed_state = self.vector_to_grid(signal_vector['q'])

            if np.array_equal(expected_state, observed_state):
                return True
            else:
                print(f"Scenario: {signal_vector['scenario']}, expected: {self.grid_to_vector(expected_state)}, observed: {signal_vector['q']}")
                return False

    def simulate_life_step(self, current_state):
        grid_size = 16
        next_state = np.zeros_like(current_state)

        for i in range(grid_size):
            for j in range(grid_size):
                alive_neighbours = self.count_neighbours(current_state, i, j, grid_size)
                # Apply the game of life rules
                if alive_neighbours == 3:
                    next_state[i, j] = 1
                elif alive_neighbours == 2:
                    next_state[i, j] = current_state[i, j]
                else:
                    next_state[i, j] = 0

        return next_state

    def count_neighbours(self, grid, i, j, grid_size):
        # Count all eight neighbors with toroidal (wrap-around) addressing
        neighbours = [
            grid[(i-1) % grid_size, (j-1) % grid_size],  # Top-left
            grid[(i-1) % grid_size, j],                 # Top
            grid[(i-1) % grid_size, (j+1) % grid_size],  # Top-right
            grid[i, (j-1) % grid_size],                 # Left
            grid[i, (j+1) % grid_size],                 # Right
            grid[(i+1) % grid_size, (j-1) % grid_size],  # Bottom-left
            grid[(i+1) % grid_size, j],                 # Bottom
            grid[(i+1) % grid_size, (j+1) % grid_size]   # Bottom-right
        ]
        return sum(neighbours)

    def grid_to_vector(self, grid):
        return int(''.join(str(cell) for cell in grid.flatten()), 2)

    def vector_to_grid(self, vector):
        binary_string = f'{vector:0256b}'
        grid = np.array([int(b) for b in binary_string]).reshape((16, 16))
        return grid
