import numpy as np

class GoldenDUT:
    def __init__(self):
        # Set the initial state of the grid to all zeros
        self.q_reg = np.zeros((16, 16), dtype=int)

    def load(self, signal_vector):
        # Load the data if the load signal is high
        if signal_vector['load'] == 1:
            # Convert the 256-bit data to a 16x16 grid
            data_vector = format(signal_vector['data'], '0256b')
            self.q_reg = self.bitvector_to_grid(data_vector)

    def check(self, signal_vector):
        # Calculate the expected next state
        expected_grid = self.game_of_life_rules(self.q_reg)

        # Convert expected grid to bit vector
        expected_bitvector = self.grid_to_bitvector(expected_grid)

        # Compare with the observed q if check_en is True
        if signal_vector['check_en']:
            observed_bitvector = format(signal_vector['q'], '0256b')
            if expected_bitvector == observed_bitvector:
                return True
            else:
                print(f"Scenario: {signal_vector['scenario']}, expected: q={expected_bitvector}, observed: q={observed_bitvector}")
                return False
        return True

    def count_alive_neighbours(self, grid, row, col):
        n = grid.shape[0]
        wrapped_indices = [
            ((row - 1) % n, (col - 1) % n), ((row - 1) % n, col % n), ((row - 1) % n, (col + 1) % n),
            (row % n, (col - 1) % n),                             (row % n, (col + 1) % n),
            ((row + 1) % n, (col - 1) % n), ((row + 1) % n, col % n), ((row + 1) % n, (col + 1) % n),
        ]
        return sum(grid[r][c] for r, c in wrapped_indices)

    def game_of_life_rules(self, grid):
        next_grid = np.zeros_like(grid)
        for row in range(grid.shape[0]):
            for col in range(grid.shape[1]):
                alive_neighbours = self.count_alive_neighbours(grid, row, col)
                # Apply Game of Life's rules: make sure logic matches spec
                if alive_neighbours < 2 or alive_neighbours > 3:
                    next_grid[row][col] = 0
                elif alive_neighbours == 3:
                    next_grid[row][col] = 1
                else:
                    next_grid[row][col] = grid[row][col]
        return next_grid

    def bitvector_to_grid(self, bitvector):
        return np.array([[int(bitvector[16*row + col]) for col in range(16)] for row in range(16)], dtype=int)

    def grid_to_bitvector(self, grid):
        return ''.join(str(grid[row][col]) for row in range(16) for col in range(16))

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

