import numpy as np

def bcd_to_int(bcd_value):
    tens = (bcd_value >> 4) & 0b1111
    ones = bcd_value & 0b1111
    return tens * 10 + ones

def int_to_bcd(number):
    tens = (number // 10) & 0b1111
    ones = number % 10
    return (tens << 4) | ones

def clock_increment(hh, mm, ss, pm):
    hours = bcd_to_int(hh)
    minutes = bcd_to_int(mm)
    seconds = bcd_to_int(ss)

    # Increment seconds
    seconds += 1
    if seconds == 60:
        seconds = 0
        minutes += 1
        if minutes == 60:
            minutes = 0
            hours += 1
            if hours == 12:
                # Toggle PM when reaching 12
                pm = not pm
            elif hours > 12:
                # Adjust hours back to 1, since 12-hour cycle is used
                hours = 1

    hh_new = int_to_bcd(hours)
    mm_new = int_to_bcd(minutes)
    ss_new = int_to_bcd(seconds)

    return hh_new, mm_new, ss_new, pm

