class GoldenDUT:
    def __init__(self):
        self.q_reg = 0x0000        # BCD Counter initial value
        self.ena_reg = [0, 0, 0]   # Enable signals for BCD digits

    def load(self, signal_vector):
        if signal_vector['reset']:
            self.q_reg = 0x0000
            self.ena_reg = [0, 0, 0]
        else:
            self.increment_counter()

    def increment_counter(self):
        # Reset enable signals initially
        self.ena_reg = [0, 0, 0]

        # Break down q_reg into individual BCD digits
        ones = self.q_reg & 0x000F
        tens = (self.q_reg & 0x00F0) >> 4
        hundreds = (self.q_reg & 0x0F00) >> 8
        thousands = (self.q_reg & 0xF000) >> 12

        # Handle BCD increment for ones
        ones += 1
        if ones > 9:
            ones = 0
            tens += 1
            self.ena_reg[0] = 1

        # Handle BCD increment for tens
        if tens > 9:
            tens = 0
            hundreds += 1
            self.ena_reg[1] = 1

        # Handle BCD increment for hundreds
        if hundreds > 9:
            hundreds = 0
            thousands += 1
            self.ena_reg[2] = 1

        # Handle BCD increment for thousands
        if thousands > 9:
            thousands = 0

        # Correctly update q_reg based on incremented BCD digits
        self.q_reg = (thousands << 12) | (hundreds << 8) | (tens << 4) | ones

    def check(self, signal_vector):
        q_observed = signal_vector['q']
        ena_observed = signal_vector['ena']

        # Check at 'check_en' flag
        if signal_vector['check_en']:
            # Convert ena_reg list to a bit vector and shift left to match observed format
            expected_ena = int("".join(str(bit) for bit in reversed(self.ena_reg)), 2) << 1

            # Comparisons
            if self.q_reg != q_observed or expected_ena != ena_observed:
                print(f"Scenario: {signal_vector['scenario']}, expected: q={self.q_reg:x}, ena={expected_ena:x}, "
                      f"observed: q={q_observed:x}, ena={ena_observed:x}")
                return False
        return True
