    def __init__(self):
        self.q_reg = 0x0000  # 16-bit BCD counter initialized to 0
        self.ena_reg = 0b000  # 3-bit enable signals initialized to 0

    def load(self, signal_vector):
        if signal_vector['reset'] == 1:
            self.q_reg = 0x0000  # Reset the counter to 0
            self.ena_reg = 0b000  # Reset enables
        else:
            # Break down current counter value into BCD digits
            thousands = (self.q_reg >> 12) & 0xF
            hundreds = (self.q_reg >> 8) & 0xF
            tens = (self.q_reg >> 4) & 0xF
            ones = self.q_reg & 0xF

            # Reset enable register before calculations
            self.ena_reg = 0b000

            # Increment the BCD counter considering rollover logic
            if ones == 9:
                ones = 0
                tens += 1
                self.ena_reg |= 0b001  # Enable tens increment
            else:
                ones += 1

            if tens == 10:
                tens = 0
                hundreds += 1
                self.ena_reg |= 0b010  # Enable hundreds increment

            if hundreds == 10:
                hundreds = 0
                thousands += 1
                self.ena_reg |= 0b100  # Enable thousands increment

            if thousands == 10:
                thousands = 0  # Rollover to 0 when thousands digit completes

            # Update q_reg to new BCD value
            self.q_reg = (thousands << 12) | (hundreds << 8) | (tens << 4) | ones

    def check(self, signal_vector):
        if signal_vector['check_en']:
            expected_q = self.q_reg
            expected_ena = self.ena_reg
            observed_q = signal_vector['q']
            observed_ena = (signal_vector['ena'] & 0b111)

            if expected_q != observed_q or expected_ena != observed_ena:
                print(f"Scenario: {signal_vector['scenario']}, "
