        # Masks for each BCD digit
        ONES_MASK = 0x000F
        TENS_MASK = 0x00F0
        HUNDREDS_MASK = 0x0F00
        THOUSANDS_MASK = 0xF000

        # Extract BCD digits
        ones = q & ONES_MASK
        tens = (q & TENS_MASK) >> 4
        hundreds = (q & HUNDREDS_MASK) >> 8
        thousands = (q & THOUSANDS_MASK) >> 12

        # Initialize enable signals
        ena = [0, 0, 0]

        # Increment BCD counter
