class GoldenDUT:
    def __init__(self):
        # Internal states/values of the Golden DUT
        self.a_reg = 'x'
        self.q_reg = 'x'
        self.prev_a_reg = 'x'
        self.q_reg = 0  # Initialize q as '0'

    def load(self, signal_vector):
        """
        Load the input signal values and update internal states.

        :param signal_vector: A dictionary containing the signal values.
        """
        self.prev_a_reg = self.a_reg  # Store the previous 'a' value
        self.a_reg = signal_vector['a']  # Load current 'a' value

    def toggle_q(self):
        """
        Toggle the q value.
        """
        self.q_reg = 0 if self.q_reg == 1 else 1

    def should_toggle_q(self):
        """
        Determine if q should be toggled based on analysis.
        """
        # Toggle q every time on the rising edge if a is 0
        if self.a_reg == 0:
            return True
        # If a is 1 and q's last state was toggled due to a=0, it should hold q
        elif self.a_reg == 1 and self.prev_a_reg == 0:
            return False
        # Maintain current q_reg state if a was continuously 1
        elif self.a_reg == 1:
            return False

        return False

    def check(self, signal_vector):
        """
        Check the expected output against the DUT output.

        :param signal_vector: A dictionary containing the signal values.
        :return: True if the output matches the expected value, else False.
        """
        # Determine expected q value on rising edge of clock
        if signal_vector['check_en']:
            if self.should_toggle_q():  # Check if q should toggle
                self.toggle_q()  # Toggle q

        q_observed = signal_vector['q']

        if q_observed != self.q_reg:
            print(
                f"Scenario: {signal_vector['scenario']}, "
                f"expected: q={self.q_reg}, observed q={q_observed}"
            )
            return False

        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

