import numpy as np

class GoldenDUT:
    def __init__(self):
        # Initialize the internal state of the golden DUT
        self.input_sequence = []
        self.z_reg = 0

    def load(self, signal_vector):
        # Load the input signals and update internal values
        if signal_vector['areset'] == 1:
            # Reset the DUT
            self.input_sequence = []
            self.z_reg = 0  # Reset the two's complement register as well
        else:
            # Append the input x to the input sequence
            self.input_sequence.append(signal_vector['x'])
            # Calculate 2's complement for the current sequence
            self.z_reg = self.calculate_2s_complement()

    def calculate_2s_complement(self):
        # Convert input sequence to numpy array for easier manipulation
        if not self.input_sequence:
            return 0

        input_array = np.array(self.input_sequence, dtype=int)

        # Step 1: Find the 1's complement by flipping the bits
        ones_complement = np.bitwise_not(input_array) & 1  # Flip bits and mask with 1 to ensure a bit

        # Step 2: Add 1 to get 2's complement and account for the sequential nature
        # Create an array to store the 2's complement result
        twos_complement = np.zeros_like(input_array)

        # Carry starts as 1 for the addition of 1 in 2's complement
        carry = 1
        for i in range(len(input_array)):
            sum_bit = ones_complement[i] + carry
            twos_complement[i] = sum_bit % 2  # Result bit
            carry = sum_bit // 2  # Carry over to the next bit

        # Step 3: Iterate from least significant bit (LSB) to most significant bit (MSB)
        # Ensuring all bits are sequentially updated
        last_valid_bit = None
        for i in range(len(twos_complement)):
            if carry == 1:
                # Update with carry propagation
                sum_bit = ones_complement[i] + carry
                twos_complement[i] = sum_bit % 2
                carry = sum_bit // 2
            else:
                twos_complement[i] = ones_complement[i]

            # Store the last valid bit for output
            last_valid_bit = twos_complement[i]

        # The last valid bit is the current output as this is sequential
        return last_valid_bit

