class GoldenDUT:
    def __init__(self):
        self.x_reg = None    # This should be initialized with None to handle the first reset scenario correctly
        self.z_reg = []      # List to hold output z bits
        self.a_reg = 0       # Placeholder for reset flag
        self.complement_mode = False  # Flag to determine if we are in the complement mode

    def load(self, signal_vector):
        # Load the input and handle asynchronous reset
        if signal_vector['areset']:
            self.z_reg = []  # Clear z output on reset
            self.a_reg = 1
            self.complement_mode = False  # Reset the complement mode
            self.x_reg = None  # Reset x_reg value
        else:
            self.a_reg = 0
            # Process input bit
            self.x_reg = signal_vector['x']

            # Determine the mode based on the input and previous output
            if self.x_reg == 1 and not self.complement_mode:
                # Transition to complement mode when first '1' is encountered after reset
                current_z = 1 - self.x_reg
                self.complement_mode = True
            elif self.complement_mode:
                # Continue complementing once in complement mode
                current_z = 1 - self.x_reg
            else:
                # If still in non-complement mode and x is 0, append 0
                current_z = self.x_reg

            # Append calculated output to z_reg
            self.z_reg.append(current_z)

    def check(self, signal_vector):
        if signal_vector['check_en']:
            # Compare the expected vs DUT's z output
            z_observed = signal_vector.get('z', None)
            z_expected = self.z_reg[-1] if self.z_reg else None

            if z_observed is not None and z_observed == z_expected:
                return True
            else:
                print(f"Scenario: {signal_vector['scenario']}, expected: z={z_expected}, observed z={z_observed}")
                return False

    def two_complement_bit(self, x):
        # Compute 2's complement for a single bit input
        return 1 - x  # Inversion for generating 2's complement bit

# Example usage
# signal_vectors = [{'check_en': False, 'scenario': 1, 'areset': 1, 'x': 1, 'z': 1}, ...]
# golden_dut = GoldenDUT()

# for signal_vector in signal_vectors:
