class GoldenDUT:
    def __init__(self):
        # Initialize internal registers
        self.state_reg = 0  # 0: IDLE, 1: COMPUTE_2S_COMPLEMENT
        self.carry_reg = 0  # Correct initialization for carry for 2's complement operation
        self.x_reg = 0      # Stores the current input bit
        self.z_reg = 0      # Stores the current output bit

    def load(self, signal_vector):
        # Load input signals and update internal states
        self.x_reg = signal_vector['x']
        areset = signal_vector['areset']

        # Asynchronous reset handling
        if areset:
            # Ensure immediate reset of state and carry
            self.state_reg = 0  # Set state to IDLE
            self.carry_reg = 0  # Correct reset carry
            self.z_reg = 0      # Ensure output is reset on areset
        else:
            # Transition to compute state when reset is released
            if self.state_reg == 0:
                self.state_reg = 1  # Transition to compute state if areset is low

            if self.state_reg == 1:
                self.z_reg = self.compute_twos_complement(self.x_reg)

    def check(self, signal_vector):
        if signal_vector['check_en']:
            z_observed = signal_vector['z']
            if self.z_reg != z_observed:
                print(f"Scenario: {signal_vector['scenario']}, expected: z={self.z_reg}, observed: z={z_observed}")
                return False
        return True

    def compute_twos_complement(self, x):
        # Calculate 2's complement bit: ~x + carry
        complemented_bit = (1 - x) + self.carry_reg

        # Properly handle carry for 2's complement
        if complemented_bit == 2:
            complemented_bit = 0
            self.carry_reg = 1
        else:
            self.carry_reg = 0

        return complemented_bit
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

