class GoldenDUT:
    def __init__(self):
        self.x_reg = 0  # Initial value of x register
        self.z_reg = 0  # Initial value of z register
        self.input_bits = []  # List to track serial input bits
        self.machine_state = 0  # State to keep track of Moore state

    def load(self, signal_vector):
        # Load the x signal into the register
        self.x_reg = signal_vector['x']

        # Handle asynchronous reset (areset)
        if signal_vector['areset'] == 1:
            self.input_bits.clear()  # Clear input bits on reset
            self.z_reg = 0  # Reset z_reg
            self.machine_state = 0  # Reset machine state
        else:
            # Append the current input bit to the list for processing
            self.input_bits.append(self.x_reg)

            # Update the state machine and compute expected output
            self.update_state_machine()

    def check(self, signal_vector):
        z_observed = signal_vector['z']
        z_expected = self.z_reg

        if z_expected != z_observed:
            print(f"Scenario: {signal_vector['scenario']}, expected: z={z_expected}, observed z={z_observed}")
            return False
        return True

    def update_state_machine(self):
        # Calculate the two's complement based on the current state
        # Compute the 2's complement only if there are input bits collected
        if self.input_bits:
            input_bits_reversed = self.input_bits[::-1]  # Moore machine expects state-driven output
            integer_value = sum([bit << i for i, bit in enumerate(input_bits_reversed)])
            bit_count = len(self.input_bits)
            result = self.twos_complement(integer_value, bit_count)

