class GoldenDUT:
    def __init__(self):
        # Initialize the state to S0 and output z to 0
        self.state_reg = 'S0'
        self.z_reg = 0

    def load(self, signal_vector):
        # Check if reset is active
        if signal_vector['areset']:
            # Reset the state to initial state
            self.state_reg = 'S0'
            self.z_reg = 0
        else:
            # Load input x and update state and output
            x = signal_vector['x']
            self.state_reg, self.z_reg = self.state_transition(self.state_reg, x)

    def state_transition(self, state, x):
        # Implement the 2's complement operation logic
        if state == 'S0':
            # Start state, look for the first 1
            z = 0 if x == 0 else 1
            next_state = 'S1' if x == 1 else 'S0'
        elif state == 'S1':
            # In S1, the output should be inverted: complement x
            z = 1 if x == 0 else 0
            # Continue inverting while maintaining in S1, go back to S0 if necessary
            next_state = 'S1'

        return next_state, z

    def check(self, signal_vector):
        # Check if the observed output matches the expected
        z_observed = signal_vector['z']
        if self.z_reg == z_observed:
            return True
        else:
            print(f"Scenario: {signal_vector['scenario']}, expected: z={self.z_reg}, observed z={z_observed}")
            return False
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
