class GoldenDUT:
    def __init__(self):
        # Initialize internal states
        self.x_reg = ''
        self.z_reg = 0
        self.output_sequence = []
        self.reset_n = True

    def twos_complement(self, bit_sequence):
        # Convert the bit sequence to binary
        if not bit_sequence:  # Handle empty sequence case
            return []

        binary_array = [int(bit) for bit in bit_sequence]

        # Determine the number of bits
        n_bits = len(binary_array)

        # Calculate the 1's complement
        ones_complement = [~bit & 1 for bit in binary_array]  # Bitwise NOT and mask with 1 to keep it a single bit

        # Initialize the 2's complement calculation by adding one to the least significant bit
        twos_complement = [0] * n_bits
        carry = 1
        for i in range(n_bits - 1, -1, -1):
            temp_sum = ones_complement[i] + carry
            twos_complement[i] = temp_sum % 2
            carry = temp_sum // 2

        return twos_complement

    def load(self, signal_vector):
        if signal_vector['areset'] == 1:
            # If reset is asserted, clear the output sequence and internal registers
            self.output_sequence = []
            self.x_reg = ''
            self.z_reg = 0
            self.reset_n = False
        else:
            # Load new input x
            self.reset_n = True
            # Append the new input bit to the sequence if reset is not active
            self.x_reg += str(signal_vector['x'])

    def check(self, signal_vector):
        # Only check when check_en is True
        if signal_vector['check_en']:
            if self.reset_n:
                # Calculate expected output
                expected_output = self.twos_complement(self.x_reg)

                # Compare expected output with observed output
                observed_output = list(map(int, format(signal_vector['z'], '0{}b'.format(len(expected_output)))))

                if expected_output == observed_output:
                    return True
                else:
                    print(f"Scenario: {signal_vector['scenario']}, expected: z={expected_output}, observed z={observed_output}")
                    return False
            else:
                # If reset is active, ignore the check
                return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

