class GoldenDUT:
    def __init__(self):
        # Initialize the state registers
        self.x_reg = 0
        self.z_reg = 0
        self.current_input = []
        self.areset_reg = 1

    def load(self, signal_vector):
        # Update the input and internal state based on the signal vector
        self.x_reg = signal_vector['x']
        self.areset_reg = signal_vector['areset']

        # Reset logic: If areset is high, clear the state
        if self.areset_reg == 1:
            self.current_input = []
            self.z_reg = 0
        else:
            # Only accumulate input and calculate 2's complement when not reset
            self.current_input.append(self.x_reg)
            self.z_reg = self.calculate_twos_complement(self.current_input)

    def check(self, signal_vector):
        # Check if 'check_en' is True to validate output
        if signal_vector.get('check_en'):
            z_observed = signal_vector['z']
            if self.z_reg != z_observed:
                print(f"Scenario: {signal_vector['scenario']}, expected: z={self.z_reg}, observed z={z_observed}")
                return False
        return True

    def calculate_twos_complement(self, input_bits):
        # Calculate the 2's complement of the input bits
        if not input_bits:  # Handle empty input to avoid errors
            return 0

        # Invert the bits
        inverted_bits = [1 - bit for bit in input_bits]

        # Add 1 to the inverted bits
        carry = 1
        result = []
        for bit in inverted_bits:
            sum_bit = bit + carry
            if sum_bit == 2:
                result.append(0)
                carry = 1
            else:
                result.append(sum_bit)
                carry = 0

        # If there's still a carry, append it as an additional bit (necessary for certain lengths)
        if carry == 1:
            result.append(1)

        # Convert the binary list result back to an integer
        binary_as_int = int("".join(map(str, result)), 2)
        return binary_as_int
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

