class GoldenDUT:
    def __init__(self):
        self.state_reg = 'IDLE'
        self.message_reg = []
        self.done_reg = False
        self.out_bytes_reg = 0x000000

    def load(self, signal_vector):
        in_value = signal_vector['in']
        reset_value = signal_vector['reset']

        if reset_value == 1:
            self._reset()
            return

        if self.state_reg == 'IDLE':
            if in_value & 0x08:  # If in[3] is 1
                self.state_reg = 'MESSAGE_RECEIVE'
                self.message_reg = [in_value]
                self.done_reg = False
        elif self.state_reg == 'MESSAGE_RECEIVE':
            if len(self.message_reg) < 3:
                self.message_reg.append(in_value)
                if len(self.message_reg) == 3:
                    self._finalize_message()
            else:
                # If sequence is disturbed or a non-message byte is received
                self._reset()

    def check(self, signal_vector):
        if signal_vector['check_en']:
            expected_done = self.done_reg
            expected_out_bytes = self.out_bytes_reg
            observed_done = signal_vector['done']
            observed_out_bytes = signal_vector['out_bytes']

            if expected_done != observed_done or expected_out_bytes != observed_out_bytes:
                print(f"Scenario: {signal_vector['scenario']}, expected: done={expected_done}, out_bytes=0x{expected_out_bytes:06x}, "
                      f"observed: done={observed_done}, out_bytes=0x{observed_out_bytes:06x}")
                return False
        return True

    def _reset(self):
        self.state_reg = 'IDLE'
        self.message_reg = []
        self.done_reg = False
        self.out_bytes_reg = 0x000000

    def _finalize_message(self):
        # Correctly finalizes the message on third byte
        self.done_reg = True
        self.out_bytes_reg = (self.message_reg[0] << 16) | (self.message_reg[1] << 8) | self.message_reg[2]
        self.state_reg = 'IDLE'
        self.message_reg = []
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
