class GoldenDUT:
    SEARCH = 0
    BYTE1 = 1
    BYTE2 = 2
    DONE = 3

    def __init__(self):
        self.state_reg = GoldenDUT.SEARCH
        self.out_bytes_reg = 0
        self.done_reg = 0
        self.message_reg = []

    def load(self, signal_vector):
        reset = signal_vector['reset']
        input_byte = signal_vector['in']

        if reset == 1:
            self.state_reg = GoldenDUT.SEARCH
            self.out_bytes_reg = 0
            self.done_reg = 0
            self.message_reg = []
        else:
            if self.state_reg == GoldenDUT.SEARCH:
                if input_byte & 0x08:  # Check if in[3] is 1
                    self.message_reg = [input_byte]
                    self.state_reg = GoldenDUT.BYTE1
            elif self.state_reg == GoldenDUT.BYTE1:
                self.message_reg.append(input_byte)
                self.state_reg = GoldenDUT.BYTE2
            elif self.state_reg == GoldenDUT.BYTE2:
                self.message_reg.append(input_byte)
                self.out_bytes_reg = (self.message_reg[0] << 16) | (self.message_reg[1] << 8) | self.message_reg[2]
                self.done_reg = 1
                self.state_reg = GoldenDUT.DONE
            elif self.state_reg == GoldenDUT.DONE:
                self.done_reg = 0
                self.state_reg = GoldenDUT.SEARCH

    def check(self, signal_vector):
        expected_done = self.done_reg
        expected_out_bytes = self.out_bytes_reg if self.done_reg else 'x'

        observed_done = signal_vector['done']
        observed_out_bytes = signal_vector['out_bytes'] if signal_vector['done'] else 'x'

        if (expected_done, expected_out_bytes) == (observed_done, observed_out_bytes):
            return True
        else:
            print(f"Scenario: {signal_vector['scenario']}, expected: done={expected_done}, out_bytes={expected_out_bytes}, "
                  f"observed: done={observed_done}, out_bytes={observed_out_bytes}")
            return False

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

