class GoldenDUT:
    def __init__(self):
        self.state_reg = 'idle'
        self.byte_count_reg = 0
        self.message_reg = [0, 0, 0]
        self.done_reg = 0
        self.out_bytes_reg = 0
        self.done_cycle = False  # New flag to ensure done is held for exactly one cycle

    def load(self, signal_vector):
        if signal_vector['reset']:
            self.state_reg = 'idle'
            self.byte_count_reg = 0
            self.message_reg = [0, 0, 0]
            self.done_reg = 0
            self.out_bytes_reg = 0
            self.done_cycle = False
        else:
            current_in = signal_vector['in'] & 0xFF  # Ensure 8-bit input

            if not self.done_cycle:  # Added condition to manage done signal cycle
                if self.state_reg == 'idle':
                    if current_in & 0b00001000:  # Check if in[3] = 1
                        self.state_reg = 'collecting'
                        self.byte_count_reg = 1
                        self.message_reg[0] = current_in
                elif self.state_reg == 'collecting':
                    self.message_reg[self.byte_count_reg] = current_in
                    self.byte_count_reg += 1

                    if self.byte_count_reg == 3:
                        self.done_reg = 1
                        self.out_bytes_reg = (self.message_reg[0] << 16) | (self.message_reg[1] << 8) | self.message_reg[2]
                        self.state_reg = 'done_signal'
                        self.done_cycle = True
                    else:
                        self.done_reg = 0

            else:  # Handle the cycle immediately after done is asserted
                if self.state_reg == 'done_signal':
                    # Keep 'done' asserted for one full cycle
                    self.done_reg = 1
                    self.done_cycle = False
                    self.state_reg = 'idle'
                else:
                    self.done_reg = 0

    def check(self, signal_vector):
        expected_done = self.done_reg
        expected_out_bytes = self.out_bytes_reg

        observed_done = signal_vector['done']
        observed_out_bytes = signal_vector['out_bytes']

        if expected_done != observed_done or expected_out_bytes != observed_out_bytes:
            print(f"Scenario: {signal_vector['scenario']}, expected: done={expected_done}, out_bytes={hex(expected_out_bytes)}, "
                  f"observed: done={observed_done}, out_bytes={hex(observed_out_bytes)}")
            return False
        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

