    def __init__(self):
        self.state_reg = 0  # IDLE state
        self.message_reg = [0, 0, 0]
        self.out_bytes_reg = 0
        self.done_reg = 0
        self.just_done = False  # New flag to ensure done is only high for one cycle

    def load(self, signal_vector):
        if signal_vector['reset']:
            self.state_reg = 0  # Reset to IDLE state
            self.message_reg = [0, 0, 0]  # Clear message registers
            self.out_bytes_reg = 0  # Clear output bytes register
            self.done_reg = 0  # Clear done signal
            self.just_done = False
        else:
            self.update_state(signal_vector['in'])

    def update_state(self, in_byte):
        in_bit3 = (in_byte & 0b00001000) != 0  # Extract the 4th bit

        if self.state_reg == 0:  # IDLE state
            if in_bit3:
                self.state_reg = 1  # Move to BYTE_1 state
                self.message_reg[0] = in_byte  # Store first byte
            self.done_reg = 0

        elif self.state_reg == 1:  # BYTE_1 state
            self.message_reg[1] = in_byte  # Store second byte
            self.state_reg = 2  # Move to BYTE_2 state

        elif self.state_reg == 2:  # BYTE_2 state
            self.message_reg[2] = in_byte  # Store third byte
            # Compute output bytes
            self.out_bytes_reg = (self.message_reg[0] << 16) | (self.message_reg[1] << 8) | self.message_reg[2]
            self.state_reg = 3  # Transition to BYTE_3 state
            self.just_done = True  # Indicate that done should be high

        elif self.state_reg == 3:  # BYTE_3 state
            if self.just_done:
                self.done_reg = 1  # Set done signal for one cycle
                self.just_done = False
            else:
                self.done_reg = 0  # Reset done signal on subsequent cycles
                if in_bit3:
                    self.state_reg = 1  # Start new message if in[3] is high
                    self.message_reg[0] = in_byte  # Store as new first byte
                else:
                    self.state_reg = 0  # Return to IDLE state

    def check(self, signal_vector):
        expected_done = self.done_reg
        expected_out_bytes = self.out_bytes_reg

        actual_done = signal_vector['done']
        actual_out_bytes = signal_vector['out_bytes']

        if expected_done != actual_done or expected_out_bytes != actual_out_bytes:
            print(f"Scenario: {signal_vector['scenario']}, expected: done={expected_done}, out_bytes={expected_out_bytes:06x}, "
                  f"observed: done={actual_done}, out_bytes={actual_out_bytes:06x}")
            return False
        return True
