class GoldenDUT:

    def __init__(self):
        # Initialize the registers to zero
        self.D1_reg = 0
        self.D2_reg = 0
        self.D3_reg = 0

    def load(self, signal_vector):
        # Load the input signal 'x'
        x = signal_vector['x']

        # Ensure correct logic for the AND and OR operations using complements properly by masking to single bit
        next_D1 = x ^ self.D1_reg
        next_D2 = x & (~self.D2_reg & 0b1)  # Masking complement to single bit
        next_D3 = x | (~self.D3_reg & 0b1)  # Masking complement to single bit

        # Update the registers to the next state
        self.D1_reg = next_D1
        self.D2_reg = next_D2
        self.D3_reg = next_D3

    def check(self, signal_vector):
        # Read the expected output from the signal vector
        z_observed = signal_vector['z']

        # Calculate the expected output 'z' using a masked XNOR operation
        z_expected = ~(self.D1_reg ^ self.D2_reg ^ self.D3_reg) & 0b1

        # Compare the observed output with the expected output
        if z_observed == z_expected:
            return True
        else:
            # Print error message if outputs do not match
            print(f"Scenario: {signal_vector['scenario']}, expected: z={z_expected}, observed z={z_observed}")
            return False
def check_dut(vectors_in):
