import numpy as np

class GoldenDUT:
    def __init__(self):
        # Initialize flip-flop states to zero
        self.q0_reg = 0
        self.q1_reg = 0
        self.q2_reg = 0

    def load(self, signal_vector):
        # Extract the input signal 'x'
        x = signal_vector.get('x', 0)

        # Calculate the next state for each flip-flop based on input 'x' and current states
        d0 = self.xor_gate(x, self.q0_reg)
        d1 = self.and_gate(x, ~self.q1_reg & 0b1)
        d2 = self.or_gate(x, ~self.q2_reg & 0b1)

        # Update register states with calculated values
        self.q0_reg = d0
        self.q1_reg = d1
        self.q2_reg = d2

    def check(self, signal_vector):
        # Determine the expected output Z
        expected_z = self.expected_z_state()

        # Get the observed output Z from the signal vector
        observed_z = signal_vector.get('z', 0)

        if expected_z == observed_z:
            return True
        else:
            print(f"Scenario: {signal_vector['scenario']}, expected: z={expected_z}, observed z={observed_z}")
            return False

    def xor_gate(self, x, q):
        # Implementing XOR logic
        return x ^ q

    def and_gate(self, x, q_not):
        # Implementing AND logic
        return x & q_not

    def or_gate(self, x, q_not):
        # Implementing OR logic
        return x | q_not

    def expected_z_state(self):
        # Compute and return the expected output Z using the XNOR logic
        # XNOR is the NOT of XOR
        return ~(self.q0_reg ^ self.q1_reg ^ self.q2_reg) & 0b1

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

