import numpy as np

class GoldenDUT:
    def __init__(self):
        # Initialize internal states
        self.previous_in_reg = np.uint32(0)
        self.out_reg = np.uint32(0)

    def load(self, signal_vector):
        # Load input signals
        reset = signal_vector['reset']
        current_in = np.uint32(signal_vector['in'])

        # Active high synchronous reset
        if reset == 1:
            self.out_reg = np.uint32(0)
        else:
            # Apply transition detection
            transition_detected = self.previous_in_reg & ~current_in
            self.out_reg |= transition_detected

        # Update previous input state
        self.previous_in_reg = current_in

    def check(self, signal_vector):
        # Extract observed output from signal vector
        out_observed = np.uint32(signal_vector['out'])

        # Compare expected and observed output
        if self.out_reg != out_observed:
            print(f"Scenario: {signal_vector['scenario']}, expected: out={self.out_reg:#034b}, observed out={out_observed:#034b}")
            return False
        return True

    def run_test(self, signal_vectors):
        for vector in signal_vectors:
            if vector['check_en']:
                if not self.check(vector):
                    return False
            else:
                self.load(vector)
        return True

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
