class GoldenDUT:
    def __init__(self):
        self.in_reg = 0      # Store the current input value
        self.prev_in_reg = 0 # Store the previous input value
        self.out_reg = 0     # Store the current output value

    def load(self, signal_vector):
        # Load the current signals into the registers
        self.prev_in_reg = self.in_reg
        self.in_reg = signal_vector['in']

        # Update the out_reg based on input changes if not reset
        if signal_vector['reset']:
            self.out_reg = 0
        else:
