class GoldenDUT:
    def __init__(self):
        # Initialize internal state register to 'x', implicitly 0
        self.state_reg = None
        self.reset()  # Ensure state is initialized

    def reset(self):
        # Set the state to weakly not-taken (0b01)
        self.state_reg = 0b01

    def load(self, signal_vector):
        # Handle the asynchronous reset
        if signal_vector['areset']:
            self.reset()
        else:
            train_valid = signal_vector['train_valid']
            train_taken = signal_vector['train_taken']
            if train_valid:
                if train_taken:
                    # Increment and saturate at 0b11
                    next_state = min(self.state_reg + 1, 0b11) & 0b11
                else:
                    # Decrement and saturate at 0b00
                    next_state = max(self.state_reg - 1, 0b00) & 0b11
                self.state_reg = next_state

    def check(self, signal_vector):
        expected_state = self.state_reg
        observed_state = signal_vector['state']

        if expected_state != observed_state:
            print(f"Scenario: {signal_vector['scenario']}, expected: state={expected_state}, observed state={observed_state}")
            return False

        return True

