class GoldenDUT:
    def __init__(self):
        # Define logic-1 and logic-0 generating numbers based on given specifications
        self.logic_1_numbers = {2, 7, 15}
        self.logic_0_numbers = {0, 1, 4, 5, 6, 9, 10, 13, 14}
        self.never_occur_numbers = {3, 8, 11, 12}

    def load(self, signal_vector):
        # Extract input signals from the signal vector
        a = signal_vector['a']
        b = signal_vector['b']
        c = signal_vector['c']
        d = signal_vector['d']

        # Compute a single integer value from the binary inputs a, b, c, d
        input_value = (a << 3) | (b << 2) | (c << 1) | d

        # Determine the expected output signals by checking input value categories
        expected_out_sop, expected_out_pos = self.calculate_expected_outputs(input_value)

        return expected_out_sop, expected_out_pos

    def check(self, signal_vector):
        # Load expected output values based on input signals
        expected_out_sop, expected_out_pos = self.load(signal_vector)

        # Compare with actual DUT output values in signal_vector
        dut_out_sop = signal_vector['out_sop']
        dut_out_pos = signal_vector['out_pos']

        # Return True if both expected and actual outputs match, else False
        return expected_out_sop == dut_out_sop and expected_out_pos == dut_out_pos

    def calculate_expected_outputs(self, input_value):
        # Assign expected outputs based on presence in logic_1_numbers or logic_0_numbers
        if input_value in self.logic_1_numbers:
            # Logic-1 for sum-of-products, Logic-0 for product-of-sums form
            return 1, 0
        elif input_value in self.logic_0_numbers:
            # Logic-0 for sum-of-products, Logic-1 for product-of-sums form
            return 0, 1
        elif input_value in self.never_occur_numbers:
            # For numbers that never occur, return the same output as a safe default
            return 0, 0
        else:
            # Default case for safety - should not reach here if inputs are handled properly
            return 0, 0
