class GoldenDUT:
    def __init__(self):
        # Internal state can store necessary configuration if needed
        self.logic_one_conditions_sop = [2, 7, 15]  # SOP conditions
        self.logic_zero_conditions_pos = [0, 1, 4, 5, 6, 9, 10, 13, 14]  # POS conditions

    def load(self, signal_vector):
        # Extract input signals
        a, b, c, d = signal_vector['a'], signal_vector['b'], signal_vector['c'], signal_vector['d']

        # Convert inputs to a decimal value
        decimal_value = (a << 3) | (b << 2) | (c << 1) | d

        # Determine expected outputs
        expected_out_sop = self.evaluate_sop_output(decimal_value)
        expected_out_pos = self.evaluate_pos_output(decimal_value)

        return expected_out_sop, expected_out_pos

    def check(self, signal_vector):
        # Get expected output from 'load' method
        expected_out_sop, expected_out_pos = self.load(signal_vector)

        # Compare with actual output signals from signal_vector
        actual_out_sop = signal_vector['out_sop']
        actual_out_pos = signal_vector['out_pos']

        return (expected_out_sop == actual_out_sop) and (expected_out_pos == actual_out_pos)

    def evaluate_sop_output(self, decimal_value):
        if decimal_value in self.logic_one_conditions_sop:
            return 1  # Logic-1 for SOP outputs
        else:
            return 0  # Logic-0 otherwise

    def evaluate_pos_output(self, decimal_value):
        if decimal_value in self.logic_zero_conditions_pos:
            return 0  # Logic-0 for POS outputs
        else:
            return 1  # Logic-1 otherwise

# Example usage
# golden_dut = GoldenDUT()
# signal_vector = {'scenario': 1, 'a': 0, 'b': 0, 'c': 1, 'd': 0, 'out_sop': 1, 'out_pos': 1}
# print(golden_dut.check(signal_vector))
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        check_pass = golden_dut.check(vector)
        if check_pass:
            print(f"Passed; vector: {vector}")
        else:
            print(f"Failed; vector: {vector}")
            failed_scenarios.append(vector["scenario"])
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    lines = txt.strip().split("\n")
    signals = []
    for line in lines:
        signal = {}
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
