class GoldenDUT:
    def __init__(self):
        # Define sets for logic-1 and logic-0 producing numbers
        self.logic_1_numbers = {2, 7, 15}
        self.logic_0_numbers = {0, 1, 4, 5, 6, 9, 10, 13, 14}

    def load(self, signal_vector):
        a = signal_vector['a']
        b = signal_vector['b']
        c = signal_vector['c']
        d = signal_vector['d']

        # Convert the binary input to a decimal equivalent
        input_value = a * 8 + b * 4 + c * 2 + d

        # Calculate expected outputs independently for SOP and POS
        expected_out_sop = 1 if input_value in self.logic_1_numbers else 0
        expected_out_pos = 1 if input_value not in self.logic_0_numbers else 0

        # For numbers that are not explicitly defined for logic-0 or logic-1, raise an exception
        if input_value not in self.logic_1_numbers and input_value not in self.logic_0_numbers:
            raise ValueError("Unexpected input value encountered.")

        return (expected_out_sop, expected_out_pos)

    def check(self, signal_vector):
        expected_out_sop, expected_out_pos = self.load(signal_vector)

        # Get the actual outputs from DUT
        actual_out_sop = signal_vector['out_sop']
        actual_out_pos = signal_vector['out_pos']

        # Compare expected outputs with DUT outputs
        return (expected_out_sop == actual_out_sop) and (expected_out_pos == actual_out_pos)

    # You can add any additional helper methods here if needed
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        check_pass = golden_dut.check(vector)
        if check_pass:
            print(f"Passed; vector: {vector}")
        else:
            print(f"Failed; vector: {vector}")
            failed_scenarios.append(vector["scenario"])
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    lines = txt.strip().split("\n")
    signals = []
    for line in lines:
        signal = {}
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1]
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if "x" not in value and "z" not in value:
                    signal[key] = int(value)
                else:
                    signal[key] = value 
        signals.append(signal)
    return signals
