class GoldenDUT:
    def __init__(self):
        # Initialize the internal state of the DUT
        self.y_reg = 0b000  # 3-bit internal state, initialized to 000
        self.x_reg = 0  # Input x register
        self.Y0_reg = 0  # Output Y0 register
        self.z_reg = 0  # Output z register

    def load(self, signal_vector):
        # Load input signals into the internal state of the DUT
        self.x_reg = signal_vector['x']
        self.y_reg = signal_vector['y'] & 0b111  # Ensure y is 3-bit

        # Update outputs based on the current state and inputs
        self.update_outputs()

    def check(self, signal_vector):
        # Compare expected outputs with those from the signal vector
        Y0_observed = signal_vector['Y0']
        z_observed = signal_vector['z']

        # When check_en is True, perform the check
        if signal_vector['check_en']:
            if self.Y0_reg != Y0_observed or self.z_reg != z_observed:
                print(f"Scenario: {signal_vector['scenario']}, expected: Y0={self.Y0_reg}, z={self.z_reg}, observed Y0={Y0_observed}, z={z_observed}")
                return False

        return True

    def update_outputs(self):
        # Calculate expected next state and output z
        self.y_reg, self.z_reg = self.expected_state_and_output(self.y_reg, self.x_reg)
        # Update Y0 according to the logic
        self.Y0_reg = self.Y0_logic(self.y_reg)

    def expected_state_and_output(self, y, x):
        if y == 0b000:
            next_state = 0b000 if x == 0 else 0b001
            z = 0
        elif y == 0b001:
            next_state = 0b001 if x == 0 else 0b100
            z = 0
        elif y == 0b010:
            next_state = 0b010 if x == 0 else 0b001
            z = 0
        elif y == 0b011:
            next_state = 0b001 if x == 0 else 0b010
            z = 1
        elif y == 0b100:
            next_state = 0b011 if x == 0 else 0b100
            z = 1
        else:
            raise ValueError("Invalid state: y must be a 3-bit value.")

        return next_state, z

    def Y0_logic(self, y):
        # Implement logic for output Y0; can be customized based on actual requirements
        return y & 0b001

