class GoldenDUT:
    def __init__(self):
        self.state_reg = 'A'
        self.g1_reg = 0
        self.g2_reg = 0
        self.g3_reg = 0

    def load(self, signal_vector):
        # Handle reset
        if not signal_vector['resetn']:
            self.state_reg = 'A'
            self.g1_reg = 0
            self.g2_reg = 0
            self.g3_reg = 0
            return

        r = [signal_vector['r'] >> 2 & 1, signal_vector['r'] >> 1 & 1, signal_vector['r'] & 1]
        self.state_reg, grants = self.fsm_next_state(self.state_reg, r)
        self.g1_reg, self.g2_reg, self.g3_reg = grants

    def check(self, signal_vector):
        if signal_vector['check_en']:
            g_expected = [self.g1_reg, self.g2_reg, self.g3_reg]
            g_observed = [signal_vector['g'] >> 2 & 1, signal_vector['g'] >> 1 & 1, signal_vector['g'] & 1]

            if g_expected != g_observed:
                print(f"Scenario: {signal_vector['scenario']}, expected: g={g_expected}, observed g={g_observed}")
                return False

        return True

    def fsm_next_state(self, current_state, r):
        r1, r2, r3 = r
        g1, g2, g3 = 0, 0, 0  # Initialize grants

        if current_state == 'A':
            if r1 == 1:
                next_state = 'B'
                g1 = 1
            elif r2 == 1:
                next_state = 'C'
                g2 = 1
            elif r3 == 1:
                next_state = 'D'
                g3 = 1
            else:
                next_state = 'A'

        elif current_state == 'B':
            if r1 == 1:
                next_state = 'B'
                g1 = 1
            else:
                next_state = 'A'

        elif current_state == 'C':
            if r2 == 1:
                next_state = 'C'
                g2 = 1
            else:
                next_state = 'A'

        elif current_state == 'D':
            if r3 == 1:
                next_state = 'D'
                g3 = 1
            else:
                next_state = 'A'

        return (next_state, [g1, g2, g3])
