class GoldenDUT:
    def __init__(self):
        # State initialization
        self.A = 0b0001
        self.B = 0b0010
        self.C = 0b0100
        self.D = 0b1000
        # Initial state
        self.state_reg = self.A
        # Register for the outputs
        self.g_reg = 0b000

    def load(self, signal_vector):
        # Capture input signals
        self.r_reg = signal_vector['r']
        self.resetn_reg = signal_vector['resetn']

        # FSM reset logic
        if self.resetn_reg == 0:
            self.state_reg = self.A
        else:
            # Corrected FSM transition logic to respect priority
            if self.state_reg == self.A:
                if self.r_reg & 0b100:  # r1 takes the highest priority
                    self.state_reg = self.B
                elif self.r_reg & 0b010:  # r2 should only be considered if r1 is not active
                    self.state_reg = self.C
                elif self.r_reg & 0b001:  # r3 should only be considered if r1 and r2 are not active
                    self.state_reg = self.D
            elif self.state_reg == self.B and not (self.r_reg & 0b100):  # r1 not present
                self.state_reg = self.A
            elif self.state_reg == self.C and not (self.r_reg & 0b010):  # r2 not present
                self.state_reg = self.A

        # Output logic
        if self.state_reg == self.B:
            self.g_reg = 0b001
        elif self.state_reg == self.C:
            self.g_reg = 0b010
        elif self.state_reg == self.D:
            self.g_reg = 0b100
        else:
            self.g_reg = 0b000

    def check(self, signal_vector):
        # Determine expected grant signal
        g_expected = signal_vector['g']

        # Compare expected output with observed output
        if self.g_reg != g_expected:
            print(f"Scenario: {signal_vector['scenario']}, expected: g={bin(self.g_reg)}, observed g={bin(g_expected)}")
            return False
        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

