    def __init__(self):
        self.state_reg = 'A'  # Initial state
        self.f_reg = 0        # Initial output f
        self.g_reg = 0        # Initial output g
        self.x_sequence_reg = []  # Track the x sequence
        self.y_monitor_count_reg = 0
        self.g_perm_reg = 0   # Permanent g state

    def load(self, signal_vector):
        if signal_vector['resetn'] == 0:
            self.reset()
        else:
            self.advance_state(signal_vector)

    def check(self, signal_vector):
        f_observed = signal_vector['f']
        g_observed = signal_vector['g']
        expected_f = self.f_reg
        expected_g = self.g_reg

        if signal_vector['check_en']:
            if expected_f != f_observed or expected_g != g_observed:
                print(f"Scenario: {signal_vector['scenario']}, expected: f={expected_f}, g={expected_g}, "
                      f"observed: f={f_observed}, g={g_observed}")
                return False
        return True

    def advance_state(self, signal_vector):
        x = signal_vector['x']
        y = signal_vector['y']

        if self.state_reg == 'A':
            self.f_reg = 1
            self.state_reg = 'X_MONITOR'
        elif self.state_reg == 'X_MONITOR':
            self.f_reg = 0
            if len(self.x_sequence_reg) < 3:
                self.x_sequence_reg.append(x)
            if self.x_sequence_reg == [1, 0, 1]:
                self.g_reg = 1
                self.state_reg = 'Y_MONITOR'
                self.x_sequence_reg.clear()
        elif self.state_reg == 'Y_MONITOR':
            if self.y_monitor_count_reg < 2:
                self.y_monitor_count_reg += 1
                if y == 1:
                    self.g_perm_reg = 1
                    self.state_reg = 'PERMANENT_G'
            else:
                if self.g_perm_reg == 0:
                    self.g_reg = 0
                self.y_monitor_count_reg = 0
        elif self.state_reg == 'PERMANENT_G':
            self.g_reg = 1

    def reset(self):
        self.state_reg = 'A'
        self.f_reg = 0
        self.g_reg = 0
        self.x_sequence_reg.clear()
        self.y_monitor_count_reg = 0
        self.g_perm_reg = 0

