class GoldenDUT:
    def __init__(self):
        self.state_reg = 0  # Corresponds to STATE_A
        self.f_reg = 0
        self.g_reg = 0
        self.x_history_reg = []
        self.y_monitor_active_reg = False
        self.y_cycle_count_reg = 0

    def load(self, signal_vector):
        # Process the reset logic
        if signal_vector['resetn'] == 0:
            self.state_reg = 0
            self.f_reg = 0
            self.g_reg = 0
            self.x_history_reg = []
            self.y_monitor_active_reg = False
            self.y_cycle_count_reg = 0
        else:
            # FSM operational logic
            if self.state_reg == 0:  # STATE_A
                self.f_reg = 1
                self.state_reg = 1  # STATE_B
            elif self.state_reg == 1:  # STATE_B
                self.f_reg = 0
                self.x_history_reg.append(signal_vector['x'])

                if len(self.x_history_reg) > 3:
                    self.x_history_reg.pop(0)

                if self.x_history_reg == [1, 0, 1]:
                    self.g_reg = 1
                    self.state_reg = 2  # STATE_C
                    self.y_monitor_active_reg = True
                else:
                    self.g_reg = 0
            elif self.state_reg == 2:  # STATE_C
                if self.y_monitor_active_reg:
                    if signal_vector['y'] == 1:
                        self.g_reg = 1
                        self.state_reg = 3  # STATE_D
                    else:
                        self.y_cycle_count_reg += 1
                        if self.y_cycle_count_reg >= 2:
                            self.g_reg = 0
                            self.state_reg = 4  # STATE_E
                else:
                    self.state_reg = 1  # back to STATE_B
            elif self.state_reg == 3:  # STATE_D
                self.g_reg = 1
            elif self.state_reg == 4:  # STATE_E
                self.g_reg = 0

    def check(self, signal_vector):
        f_observed = signal_vector['f']
        g_observed = signal_vector['g']

        if (self.f_reg != f_observed) or (self.g_reg != g_observed):
            print(f"Scenario: {signal_vector['scenario']}, expected: f={self.f_reg}, g={self.g_reg}, "
                  f"observed f={f_observed}, g={g_observed}")
            return False
        return True

def check_dut(vectors_in):
