            self.g_reg = 0
            self.x_pattern_detected_reg = False
            self.y_monitoring_reg = False
            self.g_set_permanent_reg = False
        else:
            # Update FSM states based on internal logic and inputs
            self.update_fsm_logic(signal_vector)

    def update_fsm_logic(self, signal_vector):
        if self.state_reg == 'A':
            self.f_reg = 1
            self.state_reg = 'B'

