class GoldenDUT:
    def __init__(self):
        # State Definitions
        self.state_A = 0
        self.state_B = 1
        self.state_C = 2
        self.state_D = 3
        self.state_E = 4

        # Internal State Initializations
        self.current_state_reg = self.state_A
        self.prev_x_reg = 0  # Previous value of x to track transitions
        self.x_pattern_count_reg = 0  # Count the correct pattern of x
        self.f_reg = 0  # Output f
        self.g_reg = 0  # Output g
        self.y_counter_reg = 0  # Counter for monitoring y within two cycles

    def load(self, signal_vector):
        resetn = signal_vector['resetn']
        x = signal_vector['x']
        y = signal_vector['y']

        if resetn == 0:
            self.current_state_reg = self.state_A
            self.x_pattern_count_reg = 0
            self.y_counter_reg = 0
            self.f_reg = 0
            self.g_reg = 0
        else:
            if self.current_state_reg == self.state_A:
                self.f_reg = 1
                self.current_state_reg = self.state_B
            elif self.current_state_reg == self.state_B:
                self.f_reg = 0

                # Corrected Pattern detection logic for 1, 0, 1
                if self.prev_x_reg == 0 and x == 1:
                    if self.x_pattern_count_reg == 1:
                        self.x_pattern_count_reg += 1
                    else:
                        self.x_pattern_count_reg = 1
                elif self.prev_x_reg == 1 and x == 0:
                    if self.x_pattern_count_reg == 1:
                        self.x_pattern_count_reg += 1
                elif self.x_pattern_count_reg == 2 and x == 1:
                    self.current_state_reg = self.state_C
                    self.x_pattern_count_reg = 0

                self.g_reg = 0  # Always ensure g is 0 in state B unless pattern is matched
            elif self.current_state_reg == self.state_C:
                self.g_reg = 1
                if y == 1:
                    self.current_state_reg = self.state_D
                else:
                    self.y_counter_reg += 1
                    if self.y_counter_reg >= 2:
                        self.current_state_reg = self.state_E
                        self.y_counter_reg = 0
            elif self.current_state_reg == self.state_D:
                self.g_reg = 1
            elif self.current_state_reg == self.state_E:
                self.g_reg = 0

        self.prev_x_reg = x

    def check(self, signal_vector):
        f_observed = signal_vector['f']
        g_observed = signal_vector['g']

        # Compare expected output with observed
        if self.f_reg != f_observed or self.g_reg != g_observed:
            print(f"Scenario: {signal_vector['scenario']}, expected: f={self.f_reg}, g={self.g_reg}, observed: f={f_observed}, g={g_observed}")
            return False
        return True

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
