import numpy as np

class GoldenDUT:
    def __init__(self):
        # Initialize the Golden DUT state if needed
        pass

    def load(self, signal_vector):
        input_vector = self._get_input_vector(signal_vector)
        out_both = self._calculate_out_both(input_vector)
        out_any = self._calculate_out_any(input_vector)
        out_different = self._calculate_out_different(input_vector)
        return out_both, out_any, out_different

    def check(self, signal_vector):
        expected_out_both, expected_out_any, expected_out_different = self.load(signal_vector)

        dut_out_both = self._get_vector_from_signal(signal_vector, 'out_both', 99)
        dut_out_any = self._get_vector_from_signal(signal_vector, 'out_any', 99)
        dut_out_different = self._get_vector_from_signal(signal_vector, 'out_different', 100)

        return (np.array_equal(expected_out_both, dut_out_both) and
                np.array_equal(expected_out_any, dut_out_any) and
                np.array_equal(expected_out_different, dut_out_different))

    def _get_input_vector(self, signal_vector):
        return np.array([int(bit) for bit in f"{int(signal_vector['in']):0100b}"][::-1], dtype=int)

    def _get_vector_from_signal(self, signal_vector, key, length):
        return np.array([int(bit) for bit in f"{int(signal_vector[key]):0{length}b}"][::-1], dtype=int)

    def _calculate_out_both(self, input_vector):
        out_both = np.zeros(99, dtype=int)
        for i in range(98, -1, -1):
            out_both[i] = input_vector[i+1] & input_vector[i]
        return out_both

    def _calculate_out_any(self, input_vector):
        out_any = np.zeros(99, dtype=int)
        for i in range(98, -1, -1):  # Fixed the range to correctly cover out_any from index 98 to 0
            out_any[i] = input_vector[i] | input_vector[i+1]  # Corrected the logic to check current and right neighbor
        return out_any

    def _calculate_out_different(self, input_vector):
        out_different = np.zeros(100, dtype=int)
        for i in range(99, 0, -1):
            out_different[i] = input_vector[i] ^ input_vector[i-1]
        out_different[0] = input_vector[0] ^ input_vector[99]
        return out_different
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        check_pass = golden_dut.check(vector)
        if check_pass:
            print(f"Passed; vector: {vector}")
        else:
            print(f"Failed; vector: {vector}")
            failed_scenarios.append(vector["scenario"])
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    lines = txt.strip().split("\n")
    signals = []
    for line in lines:
        signal = {}
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1]
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if "x" not in value and "z" not in value:
                    signal[key] = int(value)
                else:
                    signal[key] = value 
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

