class GoldenDUT:
    def __init__(self):
        # Initialize internal states
        self.state_reg = 'A'
        self.w_count_reg = 0
        self.z_reg = 0
        self.w_sequence_reg = [0, 0, 0]
        self.w_index_reg = 0

    def load(self, signal_vector):
        s = signal_vector['s']
        w = signal_vector['w']
        reset = signal_vector['reset']

        # Synchronous reset
        if reset == 1:
            self.state_reg = 'A'
            self.w_count_reg = 0
            self.z_reg = 0
            self.w_sequence_reg = [0, 0, 0]
            self.w_index_reg = 0
            return

        # State transition logic
        if self.state_reg == 'A':
            if s == 1:
                self.state_reg = 'B'
                self.w_count_reg = 0
                self.w_index_reg = 0
        elif self.state_reg == 'B':
            self.w_sequence_reg[self.w_index_reg] = w
            self.w_index_reg += 1
            if self.w_index_reg == 3:
                self.w_count_reg = sum(self.w_sequence_reg)
                if self.w_count_reg == 2:
                    self.z_reg = 1
                else:
                    self.z_reg = 0
                # Reset the index and sequence for the next 3-cycle evaluation
                self.w_index_reg = 0
                self.w_sequence_reg = [0, 0, 0]

    def check(self, signal_vector):
        if signal_vector['check_en']:
            z_observed = signal_vector['z']
            expected_z = self.z_reg

            if expected_z != z_observed:
                print(f"Scenario: {signal_vector['scenario']}, expected: z={expected_z}, observed z={z_observed}")
                return False
        return True
def check_dut(vectors_in):
