class GoldenDUT:
    def __init__(self):
        self.state_reg = 'A'  # Initial state: A
        self.w_buffer = []    # Buffer to store w inputs when in state B
        self.z_reg = 0        # Initial output is 0

    def load(self, signal_vector):
        # Handle reset: Reset all state registers and buffers
        if signal_vector['reset'] == 1:
            self.state_reg = 'A'
            self.w_buffer = []
            self.z_reg = 0
            return

        # State transitions and buffer management
        if self.state_reg == 'A':
            # Transition from A to B only if s is 1
            if signal_vector['s'] == 1:
                self.state_reg = 'B'
                self.w_buffer = []  # Clear buffer when entering state B

        elif self.state_reg == 'B':
            # Buffers the w inputs for evaluation
            w_input = signal_vector['w']
            self.w_buffer.append(w_input)
            if len(self.w_buffer) == 3:
                # Check the buffered sum to set z_reg
                ones_count = sum(self.w_buffer)
                self.z_reg = 1 if ones_count == 2 else 0
                self.w_buffer = []  # Clear buffer after evaluation to start fresh for the next 3 cycles

    def check(self, signal_vector):
        # When check enabled, compare observed and expected z
        if signal_vector['check_en']:
            z_observed = signal_vector['z']
            if z_observed != self.z_reg:
                print(f"Scenario: {signal_vector['scenario']}, expected: z={self.z_reg}, observed z={z_observed}")
                return False
        return True
def check_dut(vectors_in):
