class GoldenDUT:
    def __init__(self):
        self.state_reg = 'A'  # Initialize FSM in state A
        self.w_history_reg = [0, 0, 0]  # To track w inputs over 3 clock cycles
        self.w_index_reg = 0  # Index to track the position in w_history_reg
        self.z_reg = 0  # Output z
        self.s_reg = 0  # Input s
        self.reset_reg = 0  # Input reset

    def load(self, signal_vector):
        # Load the reset and other inputs
        self.reset_reg = signal_vector['reset']
        self.s_reg = signal_vector['s']
        current_w = signal_vector['w']

        # Handle reset: reset to initial conditions
        if self.reset_reg:
            self.__init__()
            return

        # FSM transitions and logic
        if self.state_reg == 'A':
            if self.s_reg == 1:
                self.state_reg = 'B'

        if self.state_reg == 'B':
            # Record the w input
            self.w_history_reg[self.w_index_reg] = current_w
            self.w_index_reg += 1

            # Once we have collected three 'w' inputs, check conditions
            if self.w_index_reg == 3:
                count_ones = sum(self.w_history_reg)
                self.z_reg = 1 if count_ones == 2 else 0  # Correct check for exactly two '1's
                self.w_index_reg = 0  # Reset the index for the next sequence
                # Ensure that the state remains in B for continuous sequence checking

    def check(self, signal_vector):
        # At check time, verify the expected output
        if signal_vector['check_en']:
            expected_z = signal_vector['z']
            if self.z_reg != expected_z:
                print(f"Scenario: {signal_vector['scenario']}, expected: z={expected_z}, observed z={self.z_reg}")
                return False
        return True
