class GoldenDUT:
    def __init__(self):
        # Initialize the internal states/values of the golden DUT
        self.state_reg = 'A'
        self.w_counter_reg = 0
        self.cycles_in_B_reg = 0
        self.z_reg = 0

    def load(self, signal_vector):
        # Apply reset logic
        if signal_vector['reset']:
            self.state_reg = 'A'
            self.w_counter_reg = 0
            self.cycles_in_B_reg = 0
            self.z_reg = 0
            return

        # State machine transitions
        if self.state_reg == 'A':
            if signal_vector['s'] == 1:
                self.state_reg = 'B'
                self.w_counter_reg = 0
                self.cycles_in_B_reg = 0
        elif self.state_reg == 'B':
            if signal_vector['w'] == 1:
                self.w_counter_reg += 1
            self.cycles_in_B_reg += 1

            # After 3 cycles in state B
            if self.cycles_in_B_reg == 3:
                self.z_reg = 1 if self.w_counter_reg == 2 else 0
                # Reset counters and stay in state B for further next three cycles
                self.w_counter_reg = 0
                self.cycles_in_B_reg = 0
                # Remark: remaining in state B for continuous check of every batch of three cycles

    def check(self, signal_vector):
        if not signal_vector['check_en']:
            return True  # Skip checking if check_en is False

        z_observed = signal_vector['z']

        if self.z_reg != z_observed:
            print(f"Scenario: {signal_vector['scenario']}, expected: z={self.z_reg}, observed z={z_observed}")
            return False
        return True

    # Additional methods can be defined here if needed
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
