class GoldenDUT:
    def __init__(self):
        self.state_reg = 'A'  # Initial state after reset

    def expected_output_rule(self, state, x):
        if state == 'A':
            if x == 0:
                return 'A', 0b0
            elif x == 1:
                return 'B', 0b1
        elif state == 'B':
            if x == 0:
                return 'B', 0b1
            elif x == 1:
                return 'B', 0b0
        else:
            raise ValueError("Invalid state. State must be 'A' or 'B'.")

    def load(self, signal_vector):
        # Handle reset
        if signal_vector['areset'] == 1:
            self.state_reg = 'A'
        else:
            # Update state based on current input
            x = signal_vector['x']
            self.state_reg, _ = self.expected_output_rule(self.state_reg, x)

    def check(self, signal_vector):
        # Determine if we should check the output
        if signal_vector['check_en']:
            # Retrieve actual DUT output
            z_observed = signal_vector['z']

            # Compute expected output
            x = signal_vector['x']
            expected_state, expected_z = self.expected_output_rule(self.state_reg, x)

            # Compare DUT output with expected output
            if expected_z == z_observed:
                return True
            else:
                print(f"Scenario: {signal_vector['scenario']}, expected: z={expected_z}, observed z={z_observed}")
                return False

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
