class GoldenDUT:
    def __init__(self):
        # Initialize the internal state and counters
        self.state_reg = "INITIAL"
        self.consecutive_ones_reg = 0
        self.disc_reg = 0
        self.flag_reg = 0
        self.err_reg = 0

    def load(self, signal_vector):
        # Reset logic
        if signal_vector['reset'] == 1:
            self.state_reg = "INITIAL"
            self.consecutive_ones_reg = 0
            self.disc_reg = 0
            self.flag_reg = 0
            self.err_reg = 0
            return

        # Main FSM logic
        in_signal = signal_vector['in']

        if self.state_reg == "INITIAL":
            if in_signal == 0:
                self.consecutive_ones_reg = 0
            elif in_signal == 1:
                self.consecutive_ones_reg = 1
            self.state_reg = "CHECK_SEQUENCE"

        elif self.state_reg == "CHECK_SEQUENCE":
            if in_signal == 1:
                self.consecutive_ones_reg += 1
            else:
                self.consecutive_ones_reg = 0

            if self.consecutive_ones_reg == 6:
                if in_signal == 0:
                    self.disc_reg = 1
                    self.flag_reg = 1
                else:
                    self.state_reg = "ERROR_CHECK"
            elif self.consecutive_ones_reg == 5:
                self.disc_reg = 0
                self.flag_reg = 0
                self.err_reg = 0
            elif self.consecutive_ones_reg >= 7:
                self.state_reg = "ERROR_CHECK"
                self.err_reg = 1
            else:
                self.disc_reg = 0
                self.flag_reg = 0
                self.err_reg = 0

        elif self.state_reg == "ERROR_CHECK":
            self.err_reg = 1
            if in_signal == 0:
                self.state_reg = "CHECK_SEQUENCE"
                self.consecutive_ones_reg = 0

        # Reset outputs after evaluation
        self.disc_reg = 0 if self.consecutive_ones_reg != 6 else self.disc_reg
        self.flag_reg = 0 if self.consecutive_ones_reg != 6 else self.flag_reg
        self.err_reg = 0 if self.state_reg != "ERROR_CHECK" else self.err_reg

    def check(self, signal_vector):
        observed_disc = signal_vector['disc']
        observed_flag = signal_vector['flag']
        observed_err = signal_vector['err']

        if self.disc_reg != observed_disc:
            print(f"Scenario: {signal_vector['scenario']}, expected: disc={self.disc_reg}, observed disc={observed_disc}")
            return False
        if self.flag_reg != observed_flag:
            print(f"Scenario: {signal_vector['scenario']}, expected: flag={self.flag_reg}, observed flag={observed_flag}")
            return False
        if self.err_reg != observed_err:
            print(f"Scenario: {signal_vector['scenario']}, expected: err={self.err_reg}, observed err={observed_err}")
            return False

        return True

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

