class GoldenDUT:
    def __init__(self):
        self.previous_bits_reg = '000000'
        self.consecutive_ones_reg = 0
        self.disc_reg = 0
        self.flag_reg = 0
        self.err_reg = 0

    def load(self, signal_vector):
        if signal_vector['reset']:
            # Reset all internal states
            self.previous_bits_reg = '000000'
            self.consecutive_ones_reg = 0
            self.disc_reg = 0
            self.flag_reg = 0
            self.err_reg = 0
        else:
            # Update previous bits with current input
            self.previous_bits_reg = self.previous_bits_reg[1:] + str(signal_vector['in'])

            # Check if current bit is '1' and update consecutive ones counter
            if signal_vector['in'] == 1:
                self.consecutive_ones_reg += 1
            else:
                self.consecutive_ones_reg = 0

            # Determine outputs based on HDLC framing rules
            if self.previous_bits_reg == '0111110':
                self.disc_reg = 1
                self.flag_reg = 0
                self.err_reg = 0
            elif self.previous_bits_reg == '01111110':
                self.disc_reg = 0
                self.flag_reg = 1
                self.err_reg = 0
            elif '1111111' in self.previous_bits_reg or self.consecutive_ones_reg >= 7:
                self.disc_reg = 0
                self.flag_reg = 0
                self.err_reg = 1
            else:
                self.disc_reg = 0
                self.flag_reg = 0
                self.err_reg = 0

    def check(self, signal_vector):
        if signal_vector['check_en']:
            disc_observed = signal_vector['disc']
            flag_observed = signal_vector['flag']
            err_observed = signal_vector['err']
            is_correct = True

            if self.disc_reg != disc_observed:
                print(f"Scenario: {signal_vector['scenario']}, expected: disc={self.disc_reg}, observed disc={disc_observed}")
                is_correct = False

            if self.flag_reg != flag_observed:
                print(f"Scenario: {signal_vector['scenario']}, expected: flag={self.flag_reg}, observed flag={flag_observed}")
                is_correct = False

            if self.err_reg != err_observed:
                print(f"Scenario: {signal_vector['scenario']}, expected: err={self.err_reg}, observed err={err_observed}")
                is_correct = False

            return is_correct
        return True

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

