class GoldenDUT:
    def __init__(self):
        # Initialize internal states
        self.s_reg = 0
        self.prev_s_reg = None
        self.reset_reg = 0
        self.fr3_reg = 1
        self.fr2_reg = 1
        self.fr1_reg = 1
        self.dfr_reg = 1

    def load(self, signal_vector):
        # Load current signals
        self.prev_s_reg = self.s_reg  # Update previous sensor state
        self.s_reg = signal_vector['s'] & 0b111  # Ensure s_reg is 3 bits
        self.reset_reg = signal_vector['reset']

    def expected_outputs(self):
        if self.reset_reg:
            # If reset, all outputs should be 1
            return 1, 1, 1, 1

        # Determine expected outputs based on sensor input
        if self.s_reg == 0b111:
            fr3, fr2, fr1, dfr = 0, 0, 0, 0
        elif self.s_reg == 0b011:
            fr3, fr2, fr1, dfr = 0, 0, 1, 0
        elif self.s_reg == 0b001:
            fr3, fr2, fr1, dfr = 0, 1, 1, 0
        elif self.s_reg == 0b000:
            fr3, fr2, fr1, dfr = 1, 1, 1, 1  # All valves open
        else:
            fr3, fr2, fr1, dfr = 0, 0, 0, 0  # Default case

        # Check the previous level for dfr
        if self.prev_s_reg is not None:
            # Set dfr to 1 if the water level is rising between sensor levels
            if (self.prev_s_reg < 0b111 and self.prev_s_reg < self.s_reg):
                dfr = 1

        return fr3, fr2, fr1, dfr

    def check(self, signal_vector):
        # Calculate expected outputs
        expected_fr3, expected_fr2, expected_fr1, expected_dfr = self.expected_outputs()

        # Compare with observed DUT outputs
        observed_fr3 = signal_vector['fr3']
        observed_fr2 = signal_vector['fr2']
        observed_fr1 = signal_vector['fr1']
        observed_dfr = signal_vector['dfr']

        # Return correctness status
        if (expected_fr3 == observed_fr3 and
            expected_fr2 == observed_fr2 and
            expected_fr1 == expected_fr1 and
            expected_dfr == observed_dfr):
            return True
        else:
            print(f"Scenario: {signal_vector['scenario']}, "
                  f"expected: fr3={expected_fr3}, fr2={expected_fr2}, fr1={expected_fr1}, dfr={expected_dfr}, "
                  f"observed: fr3={observed_fr3}, fr2={observed_fr2}, fr1={observed_fr1}, dfr={observed_dfr}")
            return False
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

