class GoldenDUT:
    def __init__(self):
        # Initialize the FSM state and related variables
        self.state_reg = 'IDLE'
        self.data_bits_count_reg = 0
        self.done_reg = 0

    def load(self, signal_vector):
        # Load input signals
        self.in_reg = signal_vector['in']
        self.reset_reg = signal_vector['reset']
        # Update the state of the FSM based on input signals
        if self.reset_reg:
            self.reset()
        else:
            self.fsm_logic()

    def fsm_logic(self):
        START_BIT = 0
        STOP_BIT = 1
        DATA_BITS_LENGTH = 8

        if self.state_reg == 'IDLE':
            if self.in_reg == START_BIT:
                self.state_reg = 'RECEIVE_DATA'
                self.data_bits_count_reg = 0
                self.done_reg = 0

        elif self.state_reg == 'RECEIVE_DATA':
            if self.data_bits_count_reg < DATA_BITS_LENGTH:
                self.data_bits_count_reg += 1
            else:
                if self.in_reg == STOP_BIT:
                    self.done_reg = 1
                    self.state_reg = 'IDLE'
                else:
                    self.state_reg = 'WAIT_FOR_STOP'
                self.done_reg = 0

        elif self.state_reg == 'WAIT_FOR_STOP':
            if self.in_reg == STOP_BIT:
                self.state_reg = 'IDLE'
            self.done_reg = 0

    def reset(self):
        self.state_reg = 'IDLE'
        self.data_bits_count_reg = 0
        self.done_reg = 0

    def check(self, signal_vector):
        done_observed = signal_vector['done']
        if self.done_reg != done_observed:
            print(f"Scenario: {signal_vector['scenario']}, expected: done={self.done_reg}, observed done={done_observed}")
            return False
        return True

