class GoldenDUT:
    def __init__(self):
        self.state_reg = 'IDLE'
        self.bit_counter_reg = 0
        self.data_bits_reg = []
        self.done_reg = False

    def load(self, signal_vector):
        if signal_vector['reset']:
            self.state_reg = 'IDLE'
            self.bit_counter_reg = 0
            self.data_bits_reg = []
            self.done_reg = False
            return

        bit = signal_vector['in']

        if self.state_reg == 'IDLE':
            if bit == 0:
                # Detect start bit
                self.state_reg = 'START'
                self.bit_counter_reg = 0
        elif self.state_reg == 'START':
            # Start collecting data bits
            self.data_bits_reg.append(bit)
            self.bit_counter_reg += 1
            if self.bit_counter_reg == 8:
                # Collected all 8 data bits, expect a stop bit next
                self.state_reg = 'STOP'
                self.bit_counter_reg = 0
        elif self.state_reg == 'STOP':
            if bit == 1:
                # Stop bit detected, byte is successfully received
                self.done_reg = True
                # Move to IDLE state only if stop bit is correct
                self.state_reg = 'IDLE'
            else:
                # Invalid stop bit, do not reset to IDLE
                self.done_reg = False
            # Clear bit counter and data bits after stop bit check
            self.data_bits_reg = []
            self.bit_counter_reg = 0
        else:
            # Unhandled state, reset (safety fallback)
            self.state_reg = 'IDLE'
            self.data_bits_reg = []
            self.bit_counter_reg = 0

    def check(self, signal_vector):
        done_observed = signal_vector['done']
        result = self.done_reg == done_observed
        if not result:
            print(f"Scenario: {signal_vector['scenario']}, expected: done={self.done_reg}, observed: done={done_observed}")
        self.done_reg = False # Reset done status after check
        return result
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

