class GoldenDUT:
    def __init__(self):
        self.state_reg = 'idle'  # FSM initial state
        self.data_reg = 0  # Register to store incoming data bits
        self.bit_count_reg = 0  # Counter for bits received
        self.out_byte_reg = 0  # Output byte register
        self.done_reg = False  # Done flag
        self.expected_sequence = []  # List to track sequence of received bits

    def load(self, signal_vector):
        # Handle reset
        if signal_vector.get('reset'):
            self.__init__()  # Reinitialize all state variables
            return

        if self.state_reg == 'idle':
            # Wait for a start bit (0)
            if signal_vector.get('in') == 0:
                self.state_reg = 'start'
                self.expected_sequence = [0]  # Start bit added to sequence
        elif self.state_reg == 'start':
            # Collect data bits (shift LSB first)
            self.data_reg = (self.data_reg >> 1) | (signal_vector.get('in') << 7)
            self.bit_count_reg += 1
            self.expected_sequence.append(signal_vector.get('in'))

            if self.bit_count_reg == 8:
                self.state_reg = 'stop'
        elif self.state_reg == 'stop':
            # Expecting stop bit (1)
            self.expected_sequence.append(signal_vector.get('in'))
            if signal_vector.get('in') == 1:
                self.done_reg = True
                self.out_byte_reg = self.data_reg
            else:
                self.done_reg = False

            # Reset registers for the next sequence
            self.data_reg = 0
            self.bit_count_reg = 0
            self.state_reg = 'idle'  # Always return to idle after stop, regardless of stop bit correctness
            self.expected_sequence = []  # Clear expected sequence after handling stop bit

    def check(self, signal_vector):
        if signal_vector.get('check_en'):
            if self.done_reg != signal_vector.get('done'):
                print(f"Scenario: {signal_vector.get('scenario')}, expected done: {self.done_reg}, observed done: {signal_vector.get('done')}")
                return False

            if self.done_reg:
                if self.out_byte_reg != signal_vector.get('out_byte'):
                    print(f"Scenario: {signal_vector.get('scenario')}, expected out_byte: {self.out_byte_reg}, observed out_byte: {signal_vector.get('out_byte')}")
                    return False

            return True
        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

