class GoldenDUT:
    def __init__(self):
        self.state_reg = 0  # 0: idle, 1: start, 2: receive, 3: stop, 4: waiting_for_idle
        self.received_bits_reg = []
        self.done_reg = 0
        self.out_byte_reg = 0x00

    def load(self, signal_vector):
        in_bit = signal_vector['in']
        reset = signal_vector['reset']

        if reset:
            # Reset the state and all registers
            self.state_reg = 0
            self.received_bits_reg.clear()
            self.done_reg = 0
            self.out_byte_reg = 0x00
        else:
            if self.state_reg == 0:  # idle
                if in_bit == 0:
                    self.state_reg = 1  # transition to start

            elif self.state_reg == 1:  # start
                self.state_reg = 2  # transition to receive state immediately after start bit

            elif self.state_reg == 2:  # receive
                self.received_bits_reg.append(in_bit)
                if len(self.received_bits_reg) == 8:
                    self.state_reg = 3  # move to stop state after 8 bits

            elif self.state_reg == 3:  # stop
                if in_bit == 1:  # verifying the stop bit
                    self.out_byte_reg = int(''.join(map(str, self.received_bits_reg[::-1])), 2)
                    self.done_reg = 1
                    self.received_bits_reg.clear()
                    self.state_reg = 0  # transition back to idle
                else:
                    self.state_reg = 4  # enter waiting_for_idle if the stop bit is incorrect

            elif self.state_reg == 4:  # waiting_for_idle
                if in_bit == 1:
                    # Stay in this state until an idle state is detected (i.e., in_bit is 1)
                    self.done_reg = 0
                    # Remain in waiting_for_idle state until the line is idle (in_bit = 1)
                elif len(self.received_bits_reg) == 0:
                    # Reset state if received bits are consumed wrongly
                    self.state_reg = 0

    def check(self, signal_vector):
        expected_done = self.done_reg
        expected_out_byte = self.out_byte_reg & 0xFF  # Ensuring 8-bit width

        observed_done = signal_vector['done']
        observed_out_byte = signal_vector['out_byte']

        if expected_done == observed_done and expected_out_byte == observed_out_byte:
            return True
        else:
            print(f"Scenario: {signal_vector['scenario']}, expected: done={expected_done}, "
                  f"out_byte={expected_out_byte}, observed: done={observed_done}, "
                  f"out_byte={observed_out_byte}")
            return False
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

