class GoldenDUT:
    def __init__(self):
        self.byte_reg = 0  # Register to hold the received byte
        self.done_reg = False  # Flag to indicate if byte reception is done
        self.bit_count_reg = 0  # Counter for counting received bits
        self.receiving_reg = False  # Flag to indicate if currently receiving a byte
        self.sequence_reg = []  # Storage for the sequence of bits received

    def load(self, signal_vector):
        if signal_vector['reset']:
            self.__init__()  # Reset the golden model
            return

        incoming_bit = signal_vector['in']

        if not self.receiving_reg:
            # Start reception only at a valid start bit (0)
            if incoming_bit == 0:
                self.receiving_reg = True
                self.sequence_reg = [incoming_bit]
                self.bit_count_reg = 1
        else:
            # Continue reception and append bits to the sequence
            self.sequence_reg.append(incoming_bit)
            self.bit_count_reg += 1

            if self.bit_count_reg == 10:
                # Process if we have received 10 bits: 1 start, 8 data, 1 stop
                received_byte, done = self.evaluate_byte_sequence(self.sequence_reg)

                if not done:
                    self.sequence_reg = []  # Clear sequence if invalid
                    self.receiving_reg = False
                else:
                    self.byte_reg = received_byte
                    self.done_reg = done
                    self.receiving_reg = False  # Reset receiving flag

    def check(self, signal_vector):
        if signal_vector['check_en']:
            out_byte_obs = signal_vector['out_byte']
            done_obs = signal_vector['done']
            scenario = signal_vector['scenario']

            if (self.byte_reg != out_byte_obs) or (self.done_reg != done_obs):
                print(f"Scenario: {scenario}, expected: out_byte={self.byte_reg}, done={self.done_reg}; "
                      f"observed: out_byte={out_byte_obs}, done={done_obs}")
                return False
        return True

    def evaluate_byte_sequence(self, sequence):
        if len(sequence) != 10:
            return (None, False)

        start_bit = sequence[0]
        data_bits = sequence[1:9]
        stop_bit = sequence[9]

        # Ensure correct start and stop bits
        if start_bit != 0 or stop_bit != 1:
            return (None, False)

        # Convert data bits from LSB to MSB
        received_byte = 0
        for i, bit in enumerate(data_bits):
            received_byte |= (bit << i)

        return (received_byte, True)
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
