import numpy as np

class GoldenDUT:
    def __init__(self):
        # Initializing internal registers
        self.state_reg = 'IDLE'
        self.data_reg = 0
        self.bit_count_reg = 0
        self.out_byte_reg = 0
        self.done_reg = False

    def load(self, signal_vector):
        # If reset is high, reset internal states
        if signal_vector['reset']:
            self.state_reg = 'IDLE'
            self.data_reg = 0
            self.bit_count_reg = 0
            self.out_byte_reg = 0
            self.done_reg = False
            return  # Early return to prevent further processing in this cycle

        # FSM transitions based on current state
        if self.state_reg == 'IDLE':
            if signal_vector['in'] == 0:  # Detect start bit
                self.state_reg = 'RECEIVING'
                self.bit_count_reg = 0
                self.data_reg = 0
            self.done_reg = False

        elif self.state_reg == 'RECEIVING':
            self.data_reg |= (signal_vector['in'] << self.bit_count_reg)
            self.bit_count_reg += 1
            if self.bit_count_reg == 8:
                self.state_reg = 'STOP_BIT'

        elif self.state_reg == 'STOP_BIT':
            if signal_vector['in'] == 1:  # Detect stop bit
                self.out_byte_reg = self.data_reg & 0xFF  # Mask to 8 bits
                self.done_reg = True
                self.state_reg = 'IDLE'  # Transition back to IDLE for next byte handling
            else:
                self.done_reg = False  # Ensure done is false if stop bit is incorrect
                # Hold in the STOP_BIT state if stop bit is incorrect, potentially for error recovery
                # Without immediately transitioning back to IDLE

    def check(self, signal_vector):
        # Check only when check_en is True
        if signal_vector['check_en']:
            correct_out_byte = signal_vector['out_byte']
            correct_done = signal_vector['done']

            if (self.out_byte_reg == correct_out_byte) and (self.done_reg == correct_done):
                return True
            else:
                print(f"Scenario: {signal_vector['scenario']}, expected: out_byte={correct_out_byte}, done={correct_done}, observed: out_byte={self.out_byte_reg}, done={self.done_reg}")
                return False

    # Other potential utility methods
    def reset(self):
        self.state_reg = 'IDLE'
        self.data_reg = 0
        self.bit_count_reg = 0
        self.out_byte_reg = 0
        self.done_reg = False
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
