class GoldenDUT:
    def __init__(self):
        self.state_reg = 'IDLE'  # Initialize FSM state as IDLE
        self.byte_reg = 0        # Register to store the incoming byte
        self.bit_count_reg = 0   # Counter for the bits received
        self.out_byte_reg = None # Register to store the output byte
        self.done_reg = 0        # Register to indicate done status

    def load(self, signal_vector):
        in_signal = signal_vector['in']
        reset_signal = signal_vector['reset']

        if reset_signal == 1:
            # Reset all registers and return to the IDLE state
            self.state_reg = 'IDLE'
            self.byte_reg = 0
            self.bit_count_reg = 0
            self.out_byte_reg = None
            self.done_reg = 0
        else:
            if self.state_reg == 'IDLE':
                if in_signal == 0:  # Start bit detected, move to RECEIVE state
                    self.state_reg = 'RECEIVE'
                    self.byte_reg = 0
                    self.bit_count_reg = 0
                self.done_reg = 0
            elif self.state_reg == 'RECEIVE':
                # Shift in the new bit, least significant bit first, each clock cycle
                self.byte_reg = (self.byte_reg >> 1) | ((in_signal & 0b1) << 7)
                self.bit_count_reg += 1
                if self.bit_count_reg == 8:
                    # Move to STOP state after receiving 8 bits
                    self.state_reg = 'STOP'
            elif self.state_reg == 'STOP':
                if in_signal == 1:
                    # Correct stop bit detected, set done and output the byte
                    self.done_reg = 1
                    self.out_byte_reg = self.byte_reg
                else:
                    # Incorrect stop bit, invalidate output
                    self.done_reg = 0
                    self.out_byte_reg = None
                # Return to IDLE state after stop bit check
                self.state_reg = 'IDLE'

    def check(self, signal_vector):
        if signal_vector['check_en']:
            out_byte_observed = signal_vector['out_byte']
            done_observed = signal_vector['done']
            if (self.out_byte_reg == out_byte_observed) and (self.done_reg == done_observed):
                return True
            else:
                print(f"Scenario: {signal_vector['scenario']}, expected: out_byte={self.out_byte_reg}, done={self.done_reg}, observed: out_byte={out_byte_observed}, done={done_observed}")
                return False
        return True
