import numpy as np

class GoldenDUT:
    def __init__(self):
        self.PHT = np.zeros(128, dtype=int)
        self.global_history_reg = 0b0000000
        self.predict_taken_reg = 0
        self.predict_history_reg = 0b0000000

    def load(self, signal_vector):
        # Handle reset
        if signal_vector['areset']:
            self.apply_reset()
            return  # Return immediately after reset to avoid extra operations

        # Train the model if training is valid
        if signal_vector['train_valid']:
            self.train(signal_vector['train_pc'], signal_vector['train_history'],
                       signal_vector['train_taken'], signal_vector['train_mispredicted'])

        # Make a prediction if a prediction is valid
        if signal_vector['predict_valid']:
            self.predict(signal_vector['predict_pc'])

    def check(self, signal_vector):
        if signal_vector['check_en']:
            expected_taken = self.predict_taken_reg
            expected_history = self.predict_history_reg
            observed_taken = signal_vector.get('predict_taken', None)
            observed_history = signal_vector.get('predict_history', None)

            if expected_taken != observed_taken or expected_history != observed_history:
                print(f"Scenario: {signal_vector['scenario']}, expected: predict_taken={expected_taken}, "
                      f"predict_history={expected_history}, "
                      f"observed: predict_taken={observed_taken}, predict_history={observed_history}")
                return False
        return True

    def xor_hash(self, pc, history):
        return (pc ^ history) & 0b1111111

    def saturating_counter_update(self, counter, taken):
        if taken:
            if counter < 3:
                return counter + 1
        else:
            if counter > 0:
                return counter - 1
        return counter

    def predict(self, pc):
        index = self.xor_hash(pc, self.global_history_reg)
        counter_value = self.PHT[index]
        self.predict_taken_reg = int(counter_value >= 2)
        self.predict_history_reg = self.global_history_reg

    def train(self, pc, history, taken, mispredicted):
        index = self.xor_hash(pc, history)
        self.PHT[index] = self.saturating_counter_update(self.PHT[index], taken)

        if mispredicted:
            # Revert global history to state after the mispredicted branch
            self.global_history_reg = history
        else:
            # Shift history and add current outcome
            self.global_history_reg = ((self.global_history_reg << 1) & 0b1111111) | taken

    def apply_reset(self):
        self.PHT.fill(0)
        self.global_history_reg = 0b0000000
        self.predict_taken_reg = 0
        self.predict_history_reg = 0b0000000
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

