class GoldenDUT:
    def __init__(self):
        self.PHT_SIZE = 128
        self.NUM_COUNTER_BITS = 2
        self.BHR_BITS = 7
        self.counter_max = (1 << self.NUM_COUNTER_BITS) - 1
        self.counter_mid = self.counter_max >> 1

        # Pattern History Table initialized to neutral state
        self.PHT = [self.counter_mid] * self.PHT_SIZE
        self.global_history_reg = 0
        self.predict_taken_reg = False
        self.predict_history_reg = 0

    def xor_hash(self, pc, history):
        return pc ^ history

    def load(self, signal_vector):
        # Handle asynchronous reset
        if signal_vector['areset']:
            self.global_history_reg = 0
            self.PHT = [self.counter_mid] * self.PHT_SIZE
            self.predict_taken_reg = False
            self.predict_history_reg = 0
            return  # Early return on asynchronous reset

        if signal_vector['train_valid']:
            # Determine the index for training
            index = self.xor_hash(signal_vector['train_pc'], signal_vector['train_history'])
            if signal_vector['train_taken']:
                if self.PHT[index] < self.counter_max:
                    self.PHT[index] += 1  # Correct the counter up
            else:
                if self.PHT[index] > 0:
                    self.PHT[index] -= 1  # Correct the counter down

            # Handle the global history register update
            if signal_vector['train_mispredicted']:
                self.global_history_reg = signal_vector['train_history']  # Recover history
            else:
                # Update global history register only if no misprediction
                self.global_history_reg = (
                    ((self.global_history_reg << 1) | signal_vector['train_taken']) & ((1 << self.BHR_BITS) - 1)
                )

        if signal_vector['predict_valid']:
            # Determine the prediction outcome based on the latest correct global history
            index = self.xor_hash(signal_vector['predict_pc'], self.global_history_reg)
            counter_value = self.PHT[index]
            self.predict_taken_reg = counter_value > self.counter_mid
            self.predict_history_reg = self.global_history_reg

    def check(self, signal_vector):
        if not signal_vector['check_en']:
            return True  # If check not enabled, skip check

        expected_taken = self.predict_taken_reg
        expected_history = self.predict_history_reg

        observed_taken = bool(signal_vector['predict_taken'])
        observed_history = signal_vector['predict_history']

        if expected_taken != observed_taken or expected_history != observed_history:
            print(f"Scenario: {signal_vector['scenario']}, expected: predict_taken={expected_taken}, observed predict_taken={observed_taken}")
            print(f"Scenario: {signal_vector['scenario']}, expected: predict_history={expected_history}, observed predict_history={observed_history}")
            return False

        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

