import numpy as np

class GoldenDUT:
    def __init__(self):
        self.PHT_reg = np.zeros(128, dtype=int)  # 128-entry table of 2-bit saturating counters
        self.global_history_reg = 0b0000000  # 7-bit global branch history register

    def hash_index(self, pc, history):
        return pc ^ history  # 7-bit index from XOR of pc and global history

    def predict(self, predict_pc):
        index = self.hash_index(predict_pc, self.global_history_reg)
        prediction_counter = self.PHT_reg[index]
        predict_taken_reg = prediction_counter > 1  # Predict taken if counter is greater than 1
        predict_history_reg = self.global_history_reg
        return predict_taken_reg, predict_history_reg

    def train(self, train_pc, train_taken, train_mispredicted, train_history):
        index = self.hash_index(train_pc, train_history)
        prediction_counter = self.PHT_reg[index]

        # Update the counter
        if train_taken:
            if prediction_counter < 3:
                self.PHT_reg[index] = prediction_counter + 1
        else:
            if prediction_counter > 0:
                self.PHT_reg[index] = prediction_counter - 1

        # Recover global history if mispredicted
        if train_mispredicted:
            # Use post-misprediction completed state
            self.global_history_reg = ((train_history << 1) | train_taken) & 0b1111111

    def update_history(self, predicted_taken):
        # Update the global history by shifting in the new prediction
        self.global_history_reg = ((self.global_history_reg << 1) | predicted_taken) & 0b1111111

    def load(self, signal_vector):
        if signal_vector['areset']:
            self.global_history_reg = 0b0000000
            self.PHT_reg = np.zeros(128, dtype=int)

        if signal_vector['predict_valid']:
            predict_taken_reg, predict_history_reg = self.predict(signal_vector['predict_pc'])
            if not signal_vector['train_valid']:  # Avoid updating history on misprediction training cycle
                self.update_history(predict_taken_reg)

        if signal_vector['train_valid']:
            self.train(signal_vector['train_pc'], signal_vector['train_taken'], signal_vector['train_mispredicted'], signal_vector['train_history'])

    def check(self, signal_vector):
        if not signal_vector['check_en']:
            return True

        # Recalculate prediction to compare expected vs observed
        predict_taken_reg, predict_history_reg = self.predict(signal_vector['predict_pc'])

        predict_taken_observed = signal_vector['predict_taken']
        predict_history_observed = signal_vector['predict_history']

        if predict_taken_reg != predict_taken_observed or predict_history_reg != predict_history_observed:
            print(f"Scenario: {signal_vector['scenario']}, expected: predict_taken={predict_taken_reg}, predict_history={predict_history_reg}, "
                  f"observed: predict_taken={predict_taken_observed}, predict_history={predict_history_observed}")
            return False

        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

