import numpy as np

class GoldenDUT:
    def __init__(self):
        self.gshare_table = np.zeros(128, dtype=int)  # 128-entry table for 2-bit counters
        self.global_history_reg = 0  # 7-bit global branch history register
        self.predict_taken_reg = 0  # Predicted branch taken
        self.predict_history_reg = 0  # Predict history
        self.pht_index_reg = 0  # Index for PHT

    def load(self, signal_vector):
        if signal_vector['areset']:
            self.global_history_reg = 0
            self.gshare_table[:] = 0

        if signal_vector['predict_valid']:
            self.pht_index_reg = self.gshare_index(signal_vector['predict_pc'], self.global_history_reg)
            counter = self.gshare_table[self.pht_index_reg]
            self.predict_taken_reg = counter >= 0b10
            self.predict_history_reg = self.global_history_reg

        if signal_vector['train_valid']:
            self.train(signal_vector['train_pc'], signal_vector['train_history'],
                       signal_vector['train_taken'], signal_vector['train_mispredicted'])

    def check(self, signal_vector):
        if signal_vector['check_en']:
            expected_taken = self.predict_taken_reg
            observed_taken = signal_vector['predict_taken']
            expected_history = self.predict_history_reg
            observed_history = signal_vector['predict_history']
            if expected_taken != observed_taken or expected_history != observed_history:
                print(f"Scenario: {signal_vector['scenario']}, expected: taken={expected_taken}, history={expected_history}, "
                      f"observed: taken={observed_taken}, history={observed_history}")
                return False
        return True

    def gshare_index(self, pc, history):
        return pc ^ history

    def train(self, pc, history, actual_taken, mispredicted):
        index = self.gshare_index(pc, history)

        # Train PHT
        self.gshare_table[index] = self.two_bit_saturating_counter_update(self.gshare_table[index], actual_taken)

        # Correct handling of global history register
        if mispredicted:
            # Restore global history to train_history on misprediction before updating
            self.global_history_reg = self.update_global_history(history, actual_taken)
        else:
            # Accurately update global history when there isn't a misprediction
            self.global_history_reg = self.update_global_history(self.global_history_reg, actual_taken)

    def two_bit_saturating_counter_update(self, counter, taken):
        if taken:
            return min(counter + 1, 0b11)
        else:
            return max(counter - 1, 0b00)

    def update_global_history(self, history, taken):
        # Ensure correct shift and masking to update history
        return ((history << 1) | taken) & 0b1111111
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

