import numpy as np

# Constants
PHT_SIZE = 128
COUNTER_MAX = 0b11  # Saturating counter maximum value
COUNTER_MIN = 0b00  # Saturating counter minimum value

class GoldenDUT:
    def __init__(self):
        # Initialize internal state values with suffix "_reg"
        self.pht = np.zeros(PHT_SIZE, dtype=np.uint8)  # 128-entry pattern history table
        self.global_history_reg = 0b0000000  # 7-bit global history register
        self.predict_taken_reg = 0  # Register for storing predict_taken
        self.predict_history_reg = 0b0000000  # Register for storing predict_history

    def _compute_index(self, pc, history):
        # XOR pc and global history to get the index for the PHT
        return pc ^ history

    def _update_global_history_after_misprediction(self, history, outcome):
        # Recover the global history register after a misprediction using recent history
        return ((history << 1) | outcome) & 0b1111111

    def load(self, signal_vector):
        if signal_vector['areset']:
            # Reset conditions
            self.global_history_reg = 0
            self.pht.fill(0)
            self.predict_taken_reg = 0
            self.predict_history_reg = 0
        else:
            if signal_vector['predict_valid']:
                pc = signal_vector['predict_pc']
                index = self._compute_index(pc, self.global_history_reg)
                counter = self.pht[index]
                self.predict_taken_reg = (counter >= 0b10)
                self.predict_history_reg = self.global_history_reg

            if signal_vector['train_valid']:
                pc = signal_vector['train_pc']
                history = signal_vector['train_history']
                outcome = signal_vector['train_taken']
                mispredicted = signal_vector['train_mispredicted']
                index = self._compute_index(pc, history)

                # Update PHT based on actual outcome
                if outcome:
                    self.pht[index] = min(self.pht[index] + 1, COUNTER_MAX)
                else:
                    self.pht[index] = max(self.pht[index] - 1, COUNTER_MIN)

                # Update global history register
                if mispredicted:
                    # Recover to the state immediately after the mispredicted branch completes execution
                    self.global_history_reg = history
                else:
                    # Update global history with the actual outcome
                    self.global_history_reg = ((self.global_history_reg << 1) | outcome) & 0b1111111

    def check(self, signal_vector):
        expected_taken = self.predict_taken_reg
        observed_taken = signal_vector.get('predict_taken', None)

        expected_history = self.predict_history_reg
        observed_history = signal_vector.get('predict_history', None)

        if expected_taken != observed_taken:
            print(f"Scenario: {signal_vector['scenario']}, expected predict_taken={expected_taken}, observed predict_taken={observed_taken}")
            return False

        if expected_history != observed_history:
            print(f"Scenario: {signal_vector['scenario']}, expected predict_history={expected_history}, observed predict_history={observed_history}")
            return False

        return True     
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

