import numpy as np

class GoldenDUT:
    def __init__(self):
        # Initialize internal states
        self.pht = np.zeros(128, dtype=int)  # Pattern history table with 128 2-bit counters
        self.history_reg = 0  # 7-bit global history register
        self.pc_reg = 0  # 7-bit program counter
        self.predict_taken_reg = 0
        self.predict_history_reg = 0

    def load(self, signal_vector):
        # Load input signals
        if signal_vector['areset']:
            self.history_reg = 0
            self.pht.fill(0)

        if signal_vector['train_valid']:
            # Perform training before prediction as it takes precedence
            self.train(
                signal_vector['train_pc'], signal_vector['train_history'],
                signal_vector['train_taken'], signal_vector['train_mispredicted'])

        if signal_vector['predict_valid']:
            self.pc_reg = signal_vector['predict_pc']
            self.predict_taken_reg, self.predict_history_reg = self.predict(
                self.pc_reg, self.history_reg)
            self.history_reg = self.predict_history_reg & 0b1111111  # Ensure it's 7 bits

    def check(self, signal_vector):
        # Verify outputs
        if not signal_vector['check_en']:
            return True
        expected_taken = self.predict_taken_reg
        actual_taken = signal_vector.get('predict_taken', None)
        expected_history = self.history_reg
        actual_history = signal_vector.get('predict_history', None)

        if expected_taken != actual_taken or expected_history != actual_history:
            print(f"Scenario: {signal_vector['scenario']}, "
                  f"expected: taken={expected_taken}, history={expected_history}, "
                  f"observed: taken={actual_taken}, history={actual_history}")
            return False
        return True

    def gshare_index(self, pc, history):
        return pc ^ history  # XOR pc and history

    def update_saturating_counter(self, counter, take):
        if take:
            return min(counter + 1, 3)  # Max value is 3
        else:
            return max(counter - 1, 0)  # Min value is 0

    def predict(self, pc, history):
        index = self.gshare_index(pc, history) & 0b1111111  # Ensure it's 7 bits
        counter = self.pht[index]
        predict_taken = 1 if counter > 1 else 0  # Taken if counter > 1
        updated_history = ((history << 1) | predict_taken) & 0b1111111  # Keep history 7 bits
        return predict_taken, updated_history

    def train(self, pc, history, actual_outcome, mispredicted):
        index = self.gshare_index(pc, history) & 0b1111111
        self.pht[index] = self.update_saturating_counter(self.pht[index], actual_outcome)

        if mispredicted:
            self.history_reg = ((history << 1) | actual_outcome) & 0b1111111
        else:
            # Correctly handle the history update to prevent overwrite issues
            self.history_reg = ((history << 1) | actual_outcome) & 0b1111111 
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

