import numpy as np

class GoldenDUT:
    def __init__(self):
        self.global_history_reg = 0b0000000
        self.pht_reg = np.array([0b01] * 128, dtype=np.uint8)
        self.predict_taken_reg = False
        self.predict_history_reg = 0b0000000

    def _index(self, pc):
        """Calculate the index by XORing PC with the global history."""
        return pc ^ self.global_history_reg

    def load(self, signal_vector):
        """Load and update states based on the input signals."""
        if signal_vector['train_valid']:
            self._train(
                signal_vector['train_pc'],
                signal_vector['train_taken'],
                signal_vector['train_mispredicted']
            )

        if signal_vector['predict_valid']:
            self.predict_taken_reg, self.predict_history_reg = self._predict(
                signal_vector['predict_pc']
            )

        # Update the history register immediately after training if mispredicted
        if signal_vector['train_valid'] and signal_vector['train_mispredicted']:
            self.global_history_reg = (self.global_history_reg << 1) | signal_vector['train_taken']
            self.global_history_reg &= 0b1111111
        # Otherwise, for predictions only or non-mispredicted training
        elif signal_vector['predict_valid']:
            self.global_history_reg = (self.global_history_reg << 1) | self.predict_taken_reg
            self.global_history_reg &= 0b1111111

    def _predict(self, pc):
        """Predict the outcome and retrieve the current history register."""
        index = self._index(pc)
        predict_taken = self.pht_reg[index] >= 0b10
        return predict_taken, self.global_history_reg

    def _train(self, pc, actual_outcome, mispredicted):
        """Train the predictor based on actual outcome and misprediction."""
        index = self._index(pc)

        # Update the PHT based on actual outcome
        if actual_outcome:
            if self.pht_reg[index] < 0b11:  # Increment only if not saturated
                self.pht_reg[index] += 1
        else:
            if self.pht_reg[index] > 0b00:  # Decrement only if not saturated
                self.pht_reg[index] -= 1

    def check(self, signal_vector):
        """Check if the predicted values match the expected outcomes."""
        if signal_vector['check_en']:
            predict_taken_expected, predict_history_expected = self._predict(
                signal_vector['predict_pc']
            )
            predict_taken_observed = self.predict_taken_reg
            predict_history_observed = self.predict_history_reg

            if (predict_taken_expected != predict_taken_observed or 
                predict_history_expected != predict_history_observed):
                print(f"Scenario: {signal_vector['scenario']}, expected: predict_taken={predict_taken_expected}, predict_history={predict_history_expected:07b}, observed: predict_taken={predict_taken_observed}, predict_history={predict_history_observed:07b}")
                return False
        return True

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

