import numpy as np

class GoldenDUT:
    # Constants
    ENTRY_SIZE = 128
    COUNTER_BITS = 2
    MAX_COUNTER_VALUE = (1 << COUNTER_BITS) - 1

    def __init__(self):
        self.global_history_reg = 0  # 7-bit global branch history register
        self.pht = np.full(self.ENTRY_SIZE, 0b01, dtype=int)  # PHT initialized to weakly taken

    def load(self, signal_vector):
        # Update internal states based on input signals at the new clock cycle
        if signal_vector['predict_valid']:
            self.predict(signal_vector)
        if signal_vector['train_valid']:
            self.train(signal_vector)

    def check(self, signal_vector):
        if signal_vector['check_en']:
            # Get expected prediction results
            expected_predict_taken, expected_predict_history = self.predict_signal(signal_vector)

            # Compare expected with actual outputs from the DUT
            if (expected_predict_taken == signal_vector['predict_taken'] and
                    expected_predict_history == signal_vector['predict_history']):
                return True
            else:
                print(f"Scenario: {signal_vector['scenario']}, "
                      f"expected: predict_taken={expected_predict_taken}, "
                      f"predict_history={expected_predict_history}, "
                      f"observed: predict_taken={signal_vector['predict_taken']}, "
                      f"predict_history={signal_vector['predict_history']}")
                return False
        return True

    def hash_index(self, pc, history):
        # Calculate the index by XOR-ing the program counter and global history
        return (pc ^ history) & 0x7F

    def saturating_counter_update(self, counter, taken):
        # Update the saturating counter based on the branch outcome
        if taken:
            return min(counter + 1, self.MAX_COUNTER_VALUE)
        else:
            return max(counter - 1, 0)

    def predict(self, signal_vector):
        # Prediction rule for the signal vector
        index = self.hash_index(signal_vector['predict_pc'], self.global_history_reg)
        counter_value = self.pht[index]
        predict_taken = counter_value > (self.MAX_COUNTER_VALUE // 2)
        # Update global history register
        self.global_history_reg = ((self.global_history_reg << 1) | predict_taken) & 0x7F

    def predict_signal(self, signal_vector):
        # Predict outputs without modifying internal states
        index = self.hash_index(signal_vector['predict_pc'], self.global_history_reg)
        counter_value = self.pht[index]
        predict_taken = counter_value > (self.MAX_COUNTER_VALUE // 2)
        return predict_taken, self.global_history_reg

    def train(self, signal_vector):
        # Training rule: Update PHT and global history based on the actual outcome
        index = self.hash_index(signal_vector['train_pc'], signal_vector['train_history'])
        self.pht[index] = self.saturating_counter_update(self.pht[index], signal_vector['train_taken'])

        # Recover or update global history when misprediction occurs
        if not signal_vector['train_mispredicted']:
            self.global_history_reg = ((signal_vector['train_history'] << 1) | signal_vector['train_taken']) & 0x7F
        else:
            self.global_history_reg = (signal_vector['train_history'] << 1) & 0x7F
            # Correct history state based on corrected prediction taken value
            if signal_vector['train_taken']:
                self.global_history_reg |= 1

# This version corrects the handling of the global history register and
# ensures the correct update of the global history and PHT during
# training, especially under conditions of misprediction.
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

