import numpy as np

class GoldenDUT:
    def __init__(self):
        # Initialize a 128-entry table of 2-bit saturating counters
        self.PHT_reg = np.zeros(128, dtype=int)
        # Initialize a 7-bit global branch history register
        self.global_history_reg = 0b0000000  # Start with 0s

    def load(self, signal_vector):
        # Handle asynchronous active-high reset
        if signal_vector['areset']:
            self.reset()
        else:
            # Check training interface first to give it precedence
            if signal_vector['train_valid']:
                self.train(
                    signal_vector['train_pc'],
                    signal_vector['train_taken'],
                    signal_vector['train_mispredicted'],
                    signal_vector['train_history']
                )

            # Then check prediction interface
            if signal_vector['predict_valid']:
                self.predict(signal_vector)

    def check(self, signal_vector):
        if not signal_vector['check_en']:
            return True  # Nothing to check if check_en is not asserted

        expected_predict_taken, expected_predict_history = self.predict_output(signal_vector['predict_pc'])

        observed_predict_taken = signal_vector['predict_taken']
        observed_predict_history = signal_vector['predict_history']

        if expected_predict_taken != observed_predict_taken or expected_predict_history != observed_predict_history:
            print(
                f"Scenario: {signal_vector['scenario']}, "
                f"expected: predict_taken={expected_predict_taken}, predict_history={expected_predict_history}, "
                f"observed: predict_taken={observed_predict_taken}, predict_history={observed_predict_history}"
            )
            return False

        return True

    def predict(self, signal_vector):
        pc = signal_vector['predict_pc']
        index = self.hash_index(pc)
        self.prediction_reg = self.PHT_reg[index]

        # Determine predicted branch direction (taken or not taken)
        self.predict_taken_reg = (self.prediction_reg >= 2)  # 2 or 3 means taken
        # Save current global history
        self.predict_history_reg = self.global_history_reg

        # Update the global history register for the predicted branch
        self.global_history_reg = ((self.global_history_reg << 1) | self.predict_taken_reg) & 0b01111111

    def train(self, pc, train_taken, train_mispredicted, train_history):
        index = self.hash_index(pc)

        # Update the saturating counter in the PHT
        if train_taken:
            if self.PHT_reg[index] < 3:
                self.PHT_reg[index] += 1
        else:
            if self.PHT_reg[index] > 0:
                self.PHT_reg[index] -= 1

        # Handle misprediction recovery for branch history register
        if train_mispredicted:
            self.global_history_reg = train_history  # Recover the original history prior to misprediction
        else:
            # Update the branch history register if not mispredicted
            self.global_history_reg = ((self.global_history_reg << 1) | train_taken) & 0b01111111

    def recover_history_after_misprediction(self, train_history):
        # Recover branch history as needed post-misprediction
        return train_history  # Return the exact train history to recover original state

    def hash_index(self, pc):
        return (pc ^ self.global_history_reg) & 0b01111111

    def predict_output(self, pc):
        index = self.hash_index(pc)
        prediction = self.PHT_reg[index]
        predict_taken = (prediction >= 2)
        return predict_taken, self.global_history_reg

    def reset(self):
        self.PHT_reg[:] = 0
        self.global_history_reg = 0b0000000
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

