import numpy as np

class GoldenDUT:
    def __init__(self):
        self.global_history_reg = 0b0000000  # 7-bit global history initialized to 0
        self.PHT_reg = np.ones(128, dtype=int) * 0b10  # Initialize PHT to weakly taken

    def load(self, signal_vector):
        if signal_vector['areset']:
            self.global_history_reg = 0
            self.PHT_reg.fill(0b10)
        else:
            if signal_vector['predict_valid']:
                self.process_prediction(signal_vector)

            if signal_vector['train_valid']:
                self.process_training(signal_vector)

    def process_prediction(self, signal_vector):
        predict_pc = signal_vector['predict_pc']
        idx = self.xor_index(predict_pc)
        counter_value = self.PHT_reg[idx]
        predict_taken = counter_value >= 0b10  # Predict taken if the counter is 2 or 3
        # Only update history on correct prediction timing, consider specification
        self.global_history_reg = ((self.global_history_reg << 1) | (1 if predict_taken else 0)) & 0b1111111

    def process_training(self, signal_vector):
        train_pc = signal_vector['train_pc']
        train_taken = signal_vector['train_taken']
        train_mispredicted = signal_vector['train_mispredicted']
        train_history = signal_vector['train_history']
        idx = self.xor_index(train_pc)

        # Update PHT counter based on actual train_taken signal
        self.PHT_reg[idx] = self.saturating_counter(self.PHT_reg[idx], increment=train_taken)

        # Handle global history register updates, especially on mispredictions
        if train_mispredicted:
            # Recover the history register post the mispredict as specified
            self.global_history_reg = ((train_history << 1) | train_taken) & 0b1111111
        else:
            self.global_history_reg = ((self.global_history_reg << 1) | train_taken) & 0b1111111

    def check(self, signal_vector):
        if signal_vector['check_en']:
            predict_pc = signal_vector['predict_pc']
            idx = self.xor_index(predict_pc)
            expected_taken = self.PHT_reg[idx] >= 0b10  # Matches prediction logic for taken
            expected_history = self.global_history_reg

            if expected_taken != signal_vector['predict_taken'] or expected_history != signal_vector['predict_history']:
                print(f"Scenario: {signal_vector['scenario']}, expected: predict_taken={expected_taken},"
                      f" predict_history={expected_history}, observed: predict_taken={signal_vector['predict_taken']},"
                      f" predict_history={signal_vector['predict_history']}")
                return False
        return True

    def xor_index(self, pc):
        return pc ^ self.global_history_reg

    def saturating_counter(self, current_value, increment=True):
        if increment:
            return min(current_value + 1, 0b11)
        else:
            return max(current_value - 1, 0b00)
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

