import numpy as np

class GoldenDUT:
    def __init__(self):
        # Initialize the internal 16x16 grid with zeroes.
        self.q_reg = np.zeros((16, 16), dtype=int)

    def load(self, signal_vector):
        # If load is 1, update the internal state with the provided data.
        if signal_vector['load']:
            data = signal_vector['data']
            flattened_data = [(data >> i) & 1 for i in range(256)]  # Extract bits
            self.q_reg = np.array(flattened_data).reshape((16, 16))

    def check(self, signal_vector):
        # Calculate the next expected grid state based on the current state
        expected_q = self.ideal_rules(self.q_reg)

        # Compare with the output from the DUT
        observed_q = signal_vector['q']
        observed_grid = np.array([(observed_q >> i) & 1 for i in range(256)]).reshape((16, 16))

        # Update the internal state to the expected new state
        self.q_reg = expected_q

        if np.array_equal(expected_q, observed_grid):
            return True
        else:
            # If not equal, print error message.
            print(f"Scenario: {signal_vector['scenario']}, expected: {expected_q}, observed: {observed_grid}")
            return False

    def ideal_rules(self, grid):
        """
        Given a 16x16 binary grid, calculates the next state of the grid 
        according to the rules described in the problem.
        """
        next_grid = np.zeros((16, 16), dtype=int)

        for x in range(16):
            for y in range(16):
                alive_neighbors = self.get_neighbors(x, y, grid)

                if alive_neighbors == 2:
                    # Rule (2): Cell state does not change.
                    next_grid[x, y] = grid[x, y]
                elif alive_neighbors == 3:
                    # Rule (3): Cell becomes alive.
                    next_grid[x, y] = 1
                else:
                    # Rule (1) and (4): Cell becomes dead.
                    next_grid[x, y] = 0

        return next_grid

    def get_neighbors(self, x, y, grid):
        """
        Function to compute the number of alive neighbors for a cell at position (x, y) in the grid.
        Handles the toroidal wraparound by using modulo operations.
        """
        size = grid.shape[0]
        neighbor_coords = [
            ((x-1) % size, (y-1) % size),
            ((x-1) % size, y),
            ((x-1) % size, (y+1) % size),
            (x, (y-1) % size),
            (x, (y+1) % size),
            ((x+1) % size, (y-1) % size),
            ((x+1) % size, y),
            ((x+1) % size, (y+1) % size),
        ]
        return sum(grid[nx, ny] for nx, ny in neighbor_coords)

