import numpy as np

class GoldenDUT:
    def __init__(self):
        self.q_reg = np.zeros((16, 16), dtype=int)

    def load(self, signal_vector):
        if signal_vector['load']:
            self.q_reg = self.vector_to_grid(signal_vector['data'])

    def check(self, signal_vector):
        q_expected = self.grid_to_vector(self.game_of_life_rule(self.q_reg))
        q_observed = signal_vector['q']

        if not np.array_equal(q_expected, q_observed):
            print(f"Scenario: {signal_vector['scenario']}, expected: q={q_expected}, observed: q={q_observed}")
            return False
        return True

    def count_neighbors(self, grid, x, y):
        # List of relative neighbor positions accounting for toroidal wrapping
        neighbor_coords = [((x-1) % 16, (y-1) % 16), ((x-1) % 16, y), ((x-1) % 16, (y+1) % 16),
                           (x, (y-1) % 16),                       (x, (y+1) % 16),
                           ((x+1) % 16, (y-1) % 16), ((x+1) % 16, y), ((x+1) % 16, (y+1) % 16)]
        return sum(grid[nx][ny] for nx, ny in neighbor_coords)

    def game_of_life_rule(self, current_state):
        next_state = np.zeros((16, 16), dtype=int)
        for x in range(16):
            for y in range(16):
                alive_neighbors = self.count_neighbors(current_state, x, y)
                # Applying the Game of Life rules
                if alive_neighbors < 2 or alive_neighbors > 3:
                    next_state[x][y] = 0
                elif alive_neighbors == 3:
                    next_state[x][y] = 1
                else:
                    next_state[x][y] = current_state[x][y]
        return next_state

    def vector_to_grid(self, vector):
        # Convert a 256-bit integer to a 16x16 grid
        grid = np.zeros((16, 16), dtype=int)
        for i in range(16):
            for j in range(16):
                grid[i][j] = (vector >> ((15 - i) * 16 + (15 - j))) & 1
        return grid

    def grid_to_vector(self, grid):
        # Convert a 16x16 grid to a 256-bit integer
        vector = 0
        for i in range(16):
            for j in range(16):
                vector |= (grid[i][j] << ((15 - i) * 16 + (15 - j)))
        return vector
