class GoldenDUT:
    def __init__(self):
        # Initialize the internal registers with default reset values.
        self.pm_reg = False
        self.hh_reg = 0x12  # BCD for 12
        self.mm_reg = 0x00  # BCD for 00
        self.ss_reg = 0x00  # BCD for 00

    def load(self, signal_vector):
        reset = signal_vector['reset']
        ena = signal_vector['ena']

        if reset:
            # Reset the clock to 12:00 AM as per the DUT description.
            self.pm_reg = False
            self.hh_reg = 0x12
            self.mm_reg = 0x00
            self.ss_reg = 0x00
        elif ena:
            # Increment the clock by one second since ena is asserted.
            self.ss_reg = self.increment_bcd(self.ss_reg)
            if self.ss_reg > 0x59:
                self.ss_reg = 0x00
                self.mm_reg = self.increment_bcd(self.mm_reg)
                if self.mm_reg > 0x59:
                    self.mm_reg = 0x00
                    previous_hour = self.hh_reg
                    self.hh_reg = self.increment_bcd(self.hh_reg)
                    if self.hh_reg > 0x12:
                        self.hh_reg = 0x01
                    # Toggle PM if the hour rolls over from 11 to 12:
                    # Check for specific transitions from 11:59 AM to 12:00 PM
                    # or from 11:59 PM to 12:00 AM
                    if previous_hour == 0x11 and self.hh_reg == 0x12: 
                        self.pm_reg = not self.pm_reg

    def check(self, signal_vector):
        if signal_vector['check_en']:
            hh_observed = signal_vector['hh']
            mm_observed = signal_vector['mm']
            ss_observed = signal_vector['ss']
            pm_observed = signal_vector['pm']

            if (self.hh_reg == hh_observed and 
                self.mm_reg == mm_observed and 
                self.ss_reg == ss_observed and 
                self.pm_reg == pm_observed):
                return True
            else:
                print(
                    f"Scenario: {signal_vector['scenario']}, expected: "
                    f"hh={self.hh_reg}, mm={self.mm_reg}, ss={self.ss_reg}, pm={self.pm_reg}; "
                    f"observed: hh={hh_observed}, mm={mm_observed}, ss={ss_observed}, pm={pm_observed}"
                )
                return False
        return True

    def increment_bcd(self, bcd_value):
        """Increment a BCD-encoded value by one."""
        units = bcd_value & 0xF
        tens = (bcd_value >> 4) & 0xF

        units += 1
        if units >= 10:
            units = 0
            tens += 1

        # Return the incremented BCD value limited to BCD range
        return ((tens & 0xF) << 4) | (units & 0xF)
