class GoldenDUT:
    def __init__(self):
        # Initialize registers with default values
        self.hh_reg = 0x12  # 12 in BCD format for 12-hour clock
        self.mm_reg = 0x00  # 00 in BCD format
        self.ss_reg = 0x00  # 00 in BCD format
        self.pm_reg = False  # AM/PM indicator

    def load(self, signal_vector):
        reset = signal_vector.get('reset', 0)
        ena = signal_vector.get('ena', 0)

        if reset:
            self.reset_time()
        elif ena:
            self.increment_time()

    def reset_time(self):
        """ Resets the clock to 12:00 AM """
        self.hh_reg = 0x12
        self.mm_reg = 0x00
        self.ss_reg = 0x00
        self.pm_reg = False

    def increment_bcd(self, value, limit):
        """ Increment a BCD value and roll over upon reaching a limit """
        low_digit = value & 0x0F
        high_digit = value & 0xF0

        low_digit += 1
        if low_digit > 0x09:
            low_digit = 0x00
            high_digit += 0x10

        if high_digit > limit:
            high_digit = 0x00
            return (high_digit | low_digit), True  # Roll over

        return (high_digit | low_digit), False

    def increment_time(self):
        BCD_MAX_HH = 0x12  # Corrected to 12 for BCD 12-hour format
        BCD_MAX_MM_SS = 0x59  # 59 for minutes and seconds

        # Increment seconds and handle rollover
        self.ss_reg, sec_rollover = self.increment_bcd(self.ss_reg, BCD_MAX_MM_SS)
        if sec_rollover:
            # Increment minutes and handle rollover
            self.mm_reg, min_rollover = self.increment_bcd(self.mm_reg, BCD_MAX_MM_SS)
            if min_rollover:
                # Increment hours and handle AM/PM toggle
                if self.hh_reg == BCD_MAX_HH:
                    self.hh_reg = 0x01  # Roll over and reset to 1 after 12
                    self.pm_reg = not self.pm_reg  # Toggle AM/PM
                else:
                    self.hh_reg, _ = self.increment_bcd(self.hh_reg, BCD_MAX_HH)

    def check(self, signal_vector):
        if signal_vector['check_en']:
            hh_observed = signal_vector.get('hh', 0)
            mm_observed = signal_vector.get('mm', 0)
            ss_observed = signal_vector.get('ss', 0)
            pm_observed = signal_vector.get('pm', False)

            if (self.hh_reg, self.mm_reg, self.ss_reg, self.pm_reg) != (hh_observed, mm_observed, ss_observed, pm_observed):
                print(f"Scenario: {signal_vector['scenario']}, expected: hh={self.hh_reg}, mm={self.mm_reg}, ss={self.ss_reg}, pm={self.pm_reg}, "
                      f"observed: hh={hh_observed}, mm={mm_observed}, ss={ss_observed}, pm={pm_observed}")
                return False
        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

