class GoldenDUT:
    def __init__(self):
        self.hh_reg = 0x12  # 12 in BCD
        self.mm_reg = 0x00  # 00 in BCD
        self.ss_reg = 0x00  # 00 in BCD
        self.pm_reg = 0     # AM=0 (not asserted), PM=1 (asserted)

    def load(self, signal_vector):
        reset = signal_vector.get("reset", 0)
        ena = signal_vector.get("ena", 0)

        if reset:
            # Reset condition
            self.hh_reg = 0x12
            self.mm_reg = 0x00
            self.ss_reg = 0x00
            self.pm_reg = 0
        elif ena:
            # Clock enabled; increment time
            self.increment_time()

    def increment_time(self):
        # Increment seconds with BCD handling
        if self.ss_reg == 0x59:
            self.ss_reg = 0x00  # Reset seconds
            # Increment minutes
            if self.mm_reg == 0x59:
                self.mm_reg = 0x00  # Reset minutes
                # Increment hours
                if self.hh_reg == 0x12:
                    self.hh_reg = 0x01
                    self.pm_reg = 1 - self.pm_reg  # Toggle PM
                else:
                    self.hh_reg = self.bcd_increment(self.hh_reg)
            else:
                self.mm_reg = self.bcd_increment(self.mm_reg)
        else:
            self.ss_reg = self.bcd_increment(self.ss_reg)

    def bcd_increment(self, bcd_value):
        # BCD increment logic
        if (bcd_value & 0x0F) == 0x09:
            return (bcd_value & 0xF0) + 0x10
        else:
            return bcd_value + 0x01

    def check(self, signal_vector):
        expected_pm = self.pm_reg
        expected_hh = self.hh_reg
        expected_mm = self.mm_reg
        expected_ss = self.ss_reg

        observed_pm = signal_vector.get("pm")
        observed_hh = signal_vector.get("hh")
        observed_mm = signal_vector.get("mm")
        observed_ss = signal_vector.get("ss")

        if (expected_pm != observed_pm or
                expected_hh != observed_hh or
                expected_mm != observed_mm or
                expected_ss != observed_ss):
            print(f"Scenario: {signal_vector['scenario']}, "
                  f"expected: pm={expected_pm}, hh={expected_hh:02X}, " 
                  f"mm={expected_mm:02X}, ss={expected_ss:02X}, "
                  f"observed: pm={observed_pm}, hh={observed_hh:02X}, "
                  f"mm={observed_mm:02X}, ss={observed_ss:02X}")
            return False

        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

