class GoldenDUT:
    def __init__(self):
        # Initialize registers to represent BCD digits and enable signals
        self.q_reg = 0x0000
        self.ena_reg = [0, 0, 0]  # Enable signals for tens, hundreds, thousands

    def load(self, signal_vector):
        # Load the signal vector and modify state according to the reset signal
        reset = signal_vector['reset']
        if reset:
            self.q_reg = 0x0000
            self.ena_reg = [0, 0, 0]
        else:
            self._increment_bcd()

    def check(self, signal_vector):
        # Check DUT's output values against the expected model values
        if signal_vector['check_en']:
            q_observed = signal_vector['q']
            ena_observed = [signal_vector.get(f'ena{i}', 0) for i in range(3, 0, -1)]
            if self.q_reg != q_observed or self.ena_reg != ena_observed:
                print(f"Scenario: {signal_vector['scenario']}, expected: q={self.q_reg}, ena={self.ena_reg}, "
                      f"observed q={q_observed}, ena={ena_observed}")
                return False
        return True

    def _increment_bcd(self):
        # Unpack BCD digits
        ones = (self.q_reg & 0x000F)
        tens = (self.q_reg & 0x00F0) >> 4
        hundreds = (self.q_reg & 0x0F00) >> 8
        thousands = (self.q_reg & 0xF000) >> 12

        # Increment ones digit and determine carry
        ones += 1
        carry_out_ones = False
        if ones >= 10:
            ones = 0
            carry_out_ones = True

        # Increment tens digit if there's a carry from ones
        carry_out_tens = False
        if carry_out_ones:
            tens += 1
            if tens >= 10:
                tens = 0
                carry_out_tens = True

        # Increment hundreds digit if there's a carry from tens
        carry_out_hundreds = False
        if carry_out_tens:
            hundreds += 1
            if hundreds >= 10:
                hundreds = 0
                carry_out_hundreds = True

        # Increment thousands digit if there's a carry from hundreds
        carry_out_thousands = False
        if carry_out_hundreds:
            thousands += 1
            if thousands >= 10:
                thousands = 0
                carry_out_thousands = True

        # Update q register and enable signals
        self.q_reg = (thousands << 12) | (hundreds << 8) | (tens << 4) | ones
        self.ena_reg = [carry_out_thousands, carry_out_hundreds, carry_out_tens]
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

