        reset = signal_vector.get('reset', 0)

        if reset == 1:
            self.q_reg, self.ena_reg = self.synchronous_reset()
        else:
            self.q_reg, self.ena_reg = self.bcd_increment(self.q_reg)

    def check(self, signal_vector):
        expected_q = self.q_reg
        expected_ena = self.ena_reg[1:]  # Ignore ena[0] as it's unused

        observed_q = signal_vector.get('q', 0)
        observed_ena = [signal_vector.get(f'ena_{i}', 0) for i in range(1, 4)]

        if (expected_q == observed_q) and (expected_ena == observed_ena):
