        else:
            print(f"Scenario: {signal_vector['scenario']}, expected: q={expected_q:#06x}, ena={expected_ena}, observed q={observed_q:#06x}, ena={observed_ena}")
            return False

    def bcd_increment(self, value):
        thousands = (value >> 12) & 0b1111
        hundreds = (value >> 8) & 0b1111
        tens = (value >> 4) & 0b1111
        ones = value & 0b1111

        ena = [0, 0, 0, 0]

        ones += 1

        # Check for carry from ones to tens
        if ones > 9:
            ones = 0
            tens += 1
            ena[1] = 1

        # Check for carry from tens to hundreds
