            hundreds = 0
            thousands += 1
            ena[3] = 1

        # Wrap-around logic for thousands
        if thousands > 9:
            thousands = 0

        new_value = (thousands << 12) | (hundreds << 8) | (tens << 4) | ones

        return new_value, ena

