class GoldenDUT:
    def __init__(self):
        # Initialize internal states
        self.q_reg = [0] * 16  # 16-bit register for BCD counter
        self.ena_reg = [0] * 3  # enable signals for each BCD digit

    def load(self, signal_vector):
        # Load the input signals and update internal states
        if signal_vector['reset'] == 1:
            self.q_reg = [0] * 16
            self.ena_reg = [0] * 3
        else:
            self.increment_bcd_counter()

    def increment_bcd_counter(self):
        # Increment the BCD counter and manage enable signals
        carry = 1  # Initial carry into the ones place
        self.ena_reg = [0] * 3  # Reset enable signals each cycle

        for i in range(0, 16, 4):
            digit = int("".join(map(str, self.q_reg[i:i + 4])), 2)
            digit += carry
            if digit > 9:
                digit = 0
                carry = 1
                if i < 12:  # Ensure range for ena_reg
                    self.ena_reg[i // 4] = 1
            else:
                carry = 0

            # Update q_reg based on the new digit
            new_digit_bits = list(map(int, list(f"{digit:04b}")))
            self.q_reg[i:i + 4] = new_digit_bits

            # Carry should only propagate if a digit was rolled over
            if carry == 0:
                break

    def check(self, signal_vector):
        # Determine expected outputs and compare
        expected_q = int("".join(map(str, self.q_reg)), 2)
        curr_q = signal_vector['q']

        if signal_vector['check_en']:
            ena_observed = [int(b) for b in format(signal_vector.get('ena', 0), '03b')]
            if curr_q != expected_q or not all(x == y for x, y in zip(ena_observed, self.ena_reg)):
                print(f"Scenario: {signal_vector['scenario']}, expected: q={hex(expected_q)}, "
                      f"observed q={hex(curr_q)}, expected ena={self.ena_reg}, observed ena={ena_observed}")
                return False
        return True

