            self.q_reg, self.ena_reg = self.reset_counter()
        else:
            # Update internal counter state based on the simulation state
            self.update_counter()

    def check(self, signal_vector):
        # Determine expected outputs
        expected_q, expected_ena = self.q_reg, self.ena_reg
        # Compare expected values with observed ones
