class GoldenDUT:
    def __init__(self):
        # Initialize internal state values
        self.x_reg = 0
        self.z_reg = 0
        self.x_inverted_reg = 0
        self.carry_reg = 0
        self.reset_active = False

    def load(self, signal_vector):
        # Load input signals and update internal states
        self.x_reg = signal_vector['x']
        self.areset = signal_vector['areset']

        # Handle asynchronous reset
        if self.areset == 1:
            self.reset_state()  # Call reset function for clearing state
        else:
            if self.reset_active:
                # Ensure starting state after reset
                self.reset_active = False
                self.carry_reg = 1  # Start 2's complement with a carry of 1

            # Invert the input x for 1's complement
            self.x_inverted_reg = ~self.x_reg & 1  # Mask to 1 bit

            # Calculate 2's complement considering the carry
            total = self.x_inverted_reg + self.carry_reg
            self.z_reg = total & 1  # Result is one bit
            self.carry_reg = total >> 1  # Update carry

    def check(self, signal_vector):
        z_observed = signal_vector['z']
        if signal_vector['check_en']:
            if z_observed != self.z_reg:
                print(f"Scenario: {signal_vector['scenario']}, expected: z={self.z_reg}, observed z={z_observed}")
                return False
        return True

    def reset_state(self):
        # Reset inner states when areset is asserted
        self.reset_active = True
        self.x_inverted_reg = 0
        self.carry_reg = 0  # Properly reset the carry
        self.z_reg = 0  # Reset output to avoid unintended results
