class GoldenDUT:
    def __init__(self):
        # Initialize internal registers
        self.x_reg = '0'
        self.z_reg = '0'
        self.state_reg = 'IDLE'
        self.first_bit_received = False  # Track whether the first bit after reset has been processed

    def load(self, signal_vector):
        # Update internal state and input register based on input signal vector
        if signal_vector['areset'] == 1:
            self.state_reg = 'IDLE'
            self.x_reg = '0'
            self.z_reg = '0'
            self.first_bit_received = False
        else:
            self.x_reg = str(signal_vector['x'])
            if not self.first_bit_received:
                self.first_bit_received = True
                self.z_reg = self.compute_twos_complement(self.x_reg)
                self.state_reg = 'FIRST_COMPL'
            else:
                # Ensure state is complementary as expected when processing further bits
                if self.state_reg == 'IDLE':
