class GoldenDUT:
    def __init__(self):
        self.x_reg = 0
        self.z_reg = 0
        self.state_reg = 'RESET'

    def load(self, signal_vector):
        x = signal_vector['x']
        areset = signal_vector['areset']

        if areset:
            self.state_reg = 'RESET'
            self.z_reg = 0
        else:
            if self.state_reg == 'RESET':
                self.state_reg = 'RUN'
                self.x_reg = x
                self.z_reg = 1 - x
            else:  # RUN state
                self.x_reg = x
                self.z_reg = 1 - x

    def check(self, signal_vector):
        z_observed = signal_vector['z']
        if self.z_reg != z_observed:
            print(f"Scenario: {signal_vector['scenario']}, expected: z={self.z_reg}, observed z={z_observed}")
            return False
        return True

