class GoldenDUT:
    def __init__(self):
        self.state_reg = 0
        self.message_buffer = []
        self.done_reg = False
        self.out_bytes_reg = 0

    def load(self, signal_vector):
        byte_in = signal_vector['in']
        reset = signal_vector['reset']

        if reset:
            # Reset the internal state
            self.message_buffer = []
            self.state_reg = 0
            self.done_reg = False
            self.out_bytes_reg = 0
            return

        # Check the state for handling input bytes of the message
        if self.state_reg == 0:
            # Check start condition (in[3] = 1)
            if byte_in & 0b00001000:
                self.state_reg = 1
                self.message_buffer = [byte_in]  # Initialize buffer with the start byte
                self.done_reg = False  # Ensure done is reset
        elif self.state_reg == 1:
            self.message_buffer.append(byte_in)
            if len(self.message_buffer) == 3:
                # Form the complete message, set done_reg, and reset the state
                self.out_bytes_reg = (self.message_buffer[0] << 16) | (self.message_buffer[1] << 8) | self.message_buffer[2]
                self.done_reg = True
            else:
                self.done_reg = False  # Ensure done is only set when message is complete

        # If the message is complete, allow detection of new starts on next cycles
        if self.done_reg:
            self.state_reg = 0
            self.message_buffer = []  # Reset the message buffer

    def check(self, signal_vector):
        if signal_vector['check_en']:
            done_observed = signal_vector['done']
            out_bytes_observed = signal_vector['out_bytes']

            if done_observed != self.done_reg or out_bytes_observed != self.out_bytes_reg:
                print(f"Scenario: {signal_vector['scenario']}, expected: done={self.done_reg}, out_bytes={self.out_bytes_reg:06x}, observed done={done_observed}, out_bytes={out_bytes_observed:06x}")
                return False
        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

