class GoldenDUT:
    def __init__(self):
        # Initialize state machine registers
        self.state_reg = 'IDLE'
        self.byte_counter_reg = 0
        self.message_reg = [0, 0, 0]
        self.done_reg = 0
        self.out_bytes_reg = 0

    def load(self, signal_vector):
        # Handle the reset signal
        if signal_vector['reset']:
            self.reset_state()
        else:
            in_byte = signal_vector['in']
            if self.state_reg == 'IDLE':
                if (in_byte & 0b00001000) != 0:  # Check if in[3] is 1
                    self.state_reg = 'RECEIVING'
                    self.byte_counter_reg = 1
                    self.message_reg[0] = in_byte
            elif self.state_reg == 'RECEIVING':
                self.message_reg[self.byte_counter_reg] = in_byte
                self.byte_counter_reg += 1
                if self.byte_counter_reg == 3:
                    self.state_reg = 'DONE'
            elif self.state_reg == 'DONE':
                self.done_reg = 1
                self.out_bytes_reg = (self.message_reg[0] << 16) | (self.message_reg[1] << 8) | self.message_reg[2]
                if (in_byte & 0b00001000) != 0:  # New message starts
                    self.state_reg = 'RECEIVING'
                    self.byte_counter_reg = 1
                    self.message_reg[0] = in_byte
                else:
                    self.reset_state()

    def check(self, signal_vector):
        # Determine output values and check against the DUT output
        expected_done = self.done_reg
        observed_done = signal_vector['done']
        expected_out_bytes = self.out_bytes_reg
        observed_out_bytes = signal_vector['out_bytes']

        # Compare expected outputs with the signal vector outputs
        if expected_done != observed_done or expected_out_bytes != observed_out_bytes:
            print(f"Scenario: {signal_vector['scenario']}, expected: done={expected_done}, out_bytes={expected_out_bytes:06x}, "
                  f"observed: done={observed_done}, out_bytes={observed_out_bytes:06x}")
            return False
        return True

    def reset_state(self):
        # Reset the state machine to its initial state
        self.state_reg = 'IDLE'
        self.byte_counter_reg = 0
        self.message_reg = [0, 0, 0]
        self.done_reg = 0
        self.out_bytes_reg = 0
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

