class GoldenDUT:
    def __init__(self):
        self.BYTES_PER_MESSAGE = 3
        self.message_reg = [0] * self.BYTES_PER_MESSAGE
        self.byte_index_reg = 0
        self.in_message_reg = False
        self.out_bytes_reg = 0
        self.done_reg = 0

    def load(self, signal_vector):
        # Reset all registers when reset is high
        if signal_vector['reset']:
            self.message_reg = [0] * self.BYTES_PER_MESSAGE
            self.byte_index_reg = 0
            self.in_message_reg = False
            self.out_bytes_reg = 0
            self.done_reg = 0
        else:
            if (signal_vector['in'] & 0b00001000) != 0:
                if not self.in_message_reg:
                    # Start of a new message
                    self.in_message_reg = True
                    self.byte_index_reg = 0  # Ensure index starts at 0 for new message
                self.message_reg[self.byte_index_reg] = signal_vector['in']
                self.byte_index_reg += 1

                # Message has completed
                if self.byte_index_reg == self.BYTES_PER_MESSAGE:
                    self.in_message_reg = False
                    self.done_reg = 1
                    self.out_bytes_reg = (
                        (self.message_reg[0] << 16) | 
                        (self.message_reg[1] << 8) | 
                        self.message_reg[2]
                    )
                    self.byte_index_reg = 0  # Prepare for possible new message
                else:
                    self.done_reg = 0
            elif self.in_message_reg:
                # Continuation of message
                self.message_reg[self.byte_index_reg] = signal_vector['in']
                self.byte_index_reg += 1

                # Message has completed
                if self.byte_index_reg == self.BYTES_PER_MESSAGE:
                    self.in_message_reg = False
                    self.done_reg = 1
                    self.out_bytes_reg = (
                        (self.message_reg[0] << 16) | 
                        (self.message_reg[1] << 8) | 
                        self.message_reg[2]
                    )
                    self.byte_index_reg = 0  # Prepare for possible new message
                else:
                    self.done_reg = 0
            else:
                self.done_reg = 0

    def check(self, signal_vector):
        expected_out_bytes = self.out_bytes_reg
        expected_done = self.done_reg

        if (expected_out_bytes == signal_vector['out_bytes'] and 
            expected_done == signal_vector['done']):
            return True
        else:
            print(f"Scenario: {signal_vector['scenario']}, "
                  f"expected: out_bytes={hex(expected_out_bytes)}, done={expected_done}, "
                  f"observed: out_bytes={hex(signal_vector['out_bytes'])}, done={signal_vector['done']}")
            return False
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
