class GoldenDUT:
    def __init__(self):
        self.message_bytes_reg = [0, 0, 0]
        self.byte_count_reg = 0
        self.message_started_reg = False
        self.done_reg = 0

    def load(self, signal_vector):
        input_byte = signal_vector['in']
        reset = signal_vector['reset']

        if reset:
            self.message_bytes_reg = [0, 0, 0]
            self.byte_count_reg = 0
            self.message_started_reg = False
            self.done_reg = 0
            return

        if self.message_started_reg:
            self.message_bytes_reg[self.byte_count_reg] = input_byte
            self.byte_count_reg += 1

            if self.byte_count_reg == 3:
                self.done_reg = 1
                self.message_started_reg = False
            else:
                self.done_reg = 0

        else:
            if input_byte & 0b00001000:  # Check if in[3] is 1
                self.message_bytes_reg[0] = input_byte
                self.byte_count_reg = 1
                self.message_started_reg = True
                self.done_reg = 0

    def check(self, signal_vector):
        if signal_vector.get('check_en'):
            out_bytes_observed = signal_vector['out_bytes']
            done_observed = signal_vector['done']
            expected_out = (self.message_bytes_reg[0] << 16) | (self.message_bytes_reg[1] << 8) | self.message_bytes_reg[2] if self.done_reg else 0
            expected_done = self.done_reg

            if (done_observed == expected_done) and (out_bytes_observed == expected_out):
                return True
            else:
                print(f"Scenario: {signal_vector['scenario']}, expected: done={expected_done}, observed done={done_observed}")
                print(f"Scenario: {signal_vector['scenario']}, expected: out_bytes={hex(expected_out)}, observed out_bytes={hex(out_bytes_observed)}")
                return False
        return True

    # Additional utility or debug methods can be added if needed in the future.
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

