class GoldenDUT:
    def __init__(self):
        self.message_reg = 0  # This will hold the fully constructed 24-bit message
        self.byte_count_reg = 0  # This will track the number of bytes collected
        self.collecting_message_reg = False  # This indicates if we are currently collecting a message

    def load(self, signal_vector):
        if signal_vector['reset']:
            # Reset the internal state when reset is active
            self.message_reg = 0
            self.byte_count_reg = 0
            self.collecting_message_reg = False
        else:
            input_byte = signal_vector['in']
            if self.collecting_message_reg:
                # If we are currently collecting bytes for a message
                self.message_reg = (self.message_reg << 8) | input_byte  # Append the new byte
                self.byte_count_reg += 1  # Increment the byte count

                if self.byte_count_reg == 3:
                    # After 3 bytes, the message is complete
                    self.collecting_message_reg = False  # Stop collecting
                    self.byte_count_reg = 0  # Reset byte count for the next message
            elif input_byte & 0b00001000:
                # Start a new message on detecting in[3] = 1
                self.collecting_message_reg = True
                self.message_reg = input_byte  # Initialize message with the first byte
                self.byte_count_reg = 1  # Set byte count to 1

    def check(self, signal_vector):
        # Done is true when all 3 bytes have been successfully received
        done = (not self.collecting_message_reg and self.byte_count_reg == 0)

        # Out bytes should be valid when 'done' is asserted
        out_bytes = self.message_reg if done else 0

        expected_done = signal_vector['done']
        expected_out_bytes = signal_vector['out_bytes']

        if done == expected_done and out_bytes == expected_out_bytes:
            return True
        else:
            print(f"Scenario: {signal_vector['scenario']}, expected: done={expected_done}, "
                  f"out_bytes={hex(expected_out_bytes)}, observed: done={done}, "
                  f"out_bytes={hex(out_bytes)}")
            return False
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

