class GoldenDUT:
    def __init__(self):
        self.state_reg = 'SEARCH'
        self.byte_count_reg = 0
        self.message_reg = [0, 0, 0]
        self.start_idx_reg = -1

    def load(self, signal_vector):
        if signal_vector['reset']:
            # Ensure all registers are reset
            self.state_reg = 'SEARCH'
            self.byte_count_reg = 0
            self.message_reg = [0, 0, 0]
            self.start_idx_reg = -1
            return

        if self.state_reg == 'SEARCH':
            # Check if the in[3] is set to 1 indicating start byte
            if (signal_vector['in'] & 0b00001000) >> 3 == 1:  # Check in[3]
                self.state_reg = 'RECEIVE'
                self.byte_count_reg = 1
                self.message_reg[0] = signal_vector['in']
        elif self.state_reg == 'RECEIVE':
            if self.byte_count_reg < 3:
                self.message_reg[self.byte_count_reg] = signal_vector['in']
                self.byte_count_reg += 1
            if self.byte_count_reg == 3:
                self.state_reg = 'SEARCH'
                self.byte_count_reg = 0

    def check(self, signal_vector):
        # Once byte_count_reg reaches 3, the 'done' must be asserted
        done_expected = (self.byte_count_reg == 0 and self.state_reg == 'SEARCH')

        # Construct expected out_bytes only when done_expected is True
        out_bytes_expected = (self.message_reg[0] << 16) | (self.message_reg[1] << 8) | self.message_reg[2] if done_expected else 0

        done_observed = signal_vector['done']
        out_bytes_observed = signal_vector['out_bytes'] & 0xFFFFFF  # Masking to ensure 24-bit

        if done_observed != done_expected or out_bytes_observed != out_bytes_expected:
            print(f"Scenario: {signal_vector['scenario']}, expected done={done_expected}, observed done={done_observed}, expected out_bytes={out_bytes_expected:06x}, observed out_bytes={out_bytes_observed:06x}")
            return False
        return True
