class GoldenDUT:
    def __init__(self):
        # Initialize the internal state registers of the DUT
        self.ff1_out_reg = 0
        self.ff2_out_reg = 0
        self.ff3_out_reg = 0

    def load(self, signal_vector):
        # Load the input signals from the signal vector
        x = signal_vector['x']

        # Compute inputs to flip-flops with corrected logic
        # Note: Ensure the use of state from previous clock cycle
        xor_input = x ^ self.ff1_out_reg
        and_input = x & (~self.ff2_out_reg & 0b1)
        or_input = x | (~self.ff3_out_reg & 0b1)

        # Update flip-flop outputs (state registers with corrected logic)
        self.ff1_out_reg = xor_input
        self.ff2_out_reg = and_input
        self.ff3_out_reg = or_input

    def check(self, signal_vector):
        # Calculate the expected output based on current state
        expected_z = ~(self.ff1_out_reg ^ self.ff2_out_reg ^ self.ff3_out_reg) & 0b1

        # Compare expected output with actual DUT output
        z_observed = signal_vector['z']
        if expected_z != z_observed:
            print(f"Scenario: {signal_vector['scenario']}, expected: z={expected_z}, observed z={z_observed}")
            return False

        return True

    # Additional helper methods or functions can be defined here if necessary.
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

