import numpy as np

class GoldenDUT:
    def __init__(self):
        self.in_reg = 0
        self.out_reg = 0

    def load(self, signal_vector):
        if signal_vector['reset']:
            self.out_reg = 0
        else:
            prev_input = self.in_reg
            curr_input = signal_vector['in']
            self.out_reg |= self.capture_transitions(prev_input, curr_input)
            self.out_reg &= 0xFFFFFFFF  # Ensure 32-bit limit
        self.in_reg = signal_vector['in']

    def check(self, signal_vector):
        if signal_vector['check_en']:
            expected_out = self.out_reg
            observed_out = signal_vector['out']
            if expected_out != observed_out:
                print(f"Scenario: {signal_vector['scenario']}, expected: out={expected_out:032b}, observed: out={observed_out:032b}")
                return False
        return True

    def capture_transitions(self, prev_input, curr_input):
        # Convert inputs to binary representation (32-bit)
        prev_input_bin = np.array([int(x) for x in f"{prev_input:032b}"], dtype=np.int8)
        curr_input_bin = np.array([int(x) for x in f"{curr_input:032b}"], dtype=np.int8)

        # Detect 1 to 0 transitions
        transitions = (prev_input_bin == 1) & (curr_input_bin == 0)

        # Convert transitions to output integer
        output_vector = int("".join(transitions.astype(int).astype(str)), 2)

        return output_vector

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

