class GoldenDUT:
    def __init__(self):
        # Initialize internal state to the reset condition
        self.state_reg = 0b01  # weakly not-taken

    def load(self, signal_vector):
        # Apply reset if necessary, otherwise update state based on inputs
        if signal_vector['areset']:
            self.state_reg = self.apply_reset()
        else:
            self.state_reg = self.saturating_counter_next_state(
                self.state_reg,
                signal_vector['train_valid'],
                signal_vector['train_taken']
            )

    def check(self, signal_vector):
        # Compare expected state with observed state
        expected_state = self.state_reg
        observed_state = signal_vector['state']
        if expected_state != observed_state:
            print(f"Scenario: {signal_vector['scenario']}, expected: state={expected_state}, observed state={observed_state}")
            return False
        return True

    def saturating_counter_next_state(self, current_state, train_valid, train_taken):
        # Logic to update the state according to counter rules
        if train_valid:
            if train_taken:
                # Increment the counter, saturate at 3
                return min(current_state + 1, 0b11)
            else:
                # Decrement the counter, saturate at 0
                return max(current_state - 1, 0b00)
        else:
            # Retain current state
            return current_state

    def apply_reset(self):
        # Reset to weakly not-taken state
        return 0b01

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

