class GoldenDUT:
    def __init__(self):
        # Initialize any internal states or configurations for the golden DUT
        self.valid_inputs = [2, 7, 15]
        self.invalid_inputs = [0, 1, 4, 5, 6, 9, 10, 13, 14]
        self.ignore_inputs = [3, 8, 11, 12]

    def load(self, signal_vector):
        # Load input signals to determine expected output
        a = signal_vector['a']
        b = signal_vector['b']
        c = signal_vector['c']
        d = signal_vector['d']

        input_value = (a << 3) | (b << 2) | (c << 1) | d

        return self.calculate_expected_outputs(input_value)

    def calculate_expected_outputs(self, input_value):
        # Calculate expected outputs based on the input value

        # Check for valid input values that output logic-1
        if input_value in self.valid_inputs:
            expected_out_sop = 1
            expected_out_pos = 1

        # Check for invalid input values that output logic-0
        elif input_value in self.invalid_inputs:
            expected_out_sop = 0
            expected_out_pos = 0

        else:
            # For inputs that should never occur, we assume a 'don't-care' output
            expected_out_sop = 0  # Consider a default logic-0 for safety
            expected_out_pos = 0  # Consider a default logic-0 for safety

        return expected_out_sop, expected_out_pos

    def check(self, signal_vector):
        # Get expected outputs by calling the load function
        expected_out_sop, expected_out_pos = self.load(signal_vector)

        # Compare expected outputs with DUT outputs
        dut_out_sop = signal_vector['out_sop']
        dut_out_pos = signal_vector['out_pos']

        # We use the default case in unexplained inputs so we can always perform a comparison
        return (dut_out_sop == expected_out_sop) and (dut_out_pos == expected_out_pos)
