class GoldenDUT:
    def __init__(self):
        # Define the logic for output signals
        self.logic_1_values = {2, 7, 15}
        self.logic_0_values = {0, 1, 4, 5, 6, 9, 10, 13, 14}

    def load(self, signal_vector):
        # Extract input signals from the signal vector
        a = signal_vector['a']
        b = signal_vector['b']
        c = signal_vector['c']
        d = signal_vector['d']

        # Compute the decimal input value based on binary representation
        decimal_input = a * 8 + b * 4 + c * 2 + d

        # Determine expected output values
        if decimal_input in self.logic_1_values:
            out_sop = 1
            out_pos = 1
        elif decimal_input in self.logic_0_values:
            out_sop = 0
            out_pos = 0
        else:
            # For undefined input values (3, 8, 11, 12), determine a suitable output
            out_sop = None
            out_pos = None

        return out_sop, out_pos

    def check(self, signal_vector):
        # Get expected output using load function
        expected_out_sop, expected_out_pos = self.load(signal_vector)

        # Get actual output from the signal vector
        actual_out_sop = signal_vector['out_sop']
        actual_out_pos = signal_vector['out_pos']

        # Check if actual outputs match the expected values, accounting for 'dont care' case
        if expected_out_sop is None or expected_out_pos is None:
            return False
        return (expected_out_sop == actual_out_sop) and (expected_out_pos == actual_out_pos)

# Example usage:
# gdut = GoldenDUT()
# signal_vector = {'scenario': 1, 'a': 0, 'b': 1, 'c': 1, 'd': 1, 'out_sop': 1, 'out_pos': 1}
# result = gdut.check(signal_vector)
# print("Check result:", result)  # Returns True or False
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        check_pass = golden_dut.check(vector)
        if check_pass:
            print(f"Passed; vector: {vector}")
        else:
            print(f"Failed; vector: {vector}")
            failed_scenarios.append(vector["scenario"])
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    lines = txt.strip().split("\n")
    signals = []
    for line in lines:
        signal = {}
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1]
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if "x" not in value and "z" not in value:
                    signal[key] = int(value)
                else:
                    signal[key] = value 
