class GoldenDUT:
    def __init__(self):
        # Initialize any inner states or values if required
        pass

    def load(self, signal_vector):
        # Extract input signals from signal_vector
        a = signal_vector.get('a', 0)
        b = signal_vector.get('b', 0)
        c = signal_vector.get('c', 0)
        d = signal_vector.get('d', 0)

        # Compute the expected output q
        expected_q = self.expected_q(a, b, c, d)

        return expected_q

    def check(self, signal_vector):
        # Calculate the expected output using the load method
        expected_output = self.load(signal_vector)

        # Compare with the actual output in signal_vector
        actual_output = signal_vector.get('q', None)

        # Return True if the outputs match, otherwise False
        return expected_output == actual_output

    def expected_q(self, a, b, c, d):
        # Determine the expected output q based on specified logic rules
        # q = (b AND d) OR (a AND d) OR (b AND c)
        return (b and d) or (a and d) or (b and c)

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        check_pass = golden_dut.check(vector)
        if check_pass:
            print(f"Passed; vector: {vector}")
        else:
            print(f"Failed; vector: {vector}")
            failed_scenarios.append(vector["scenario"])
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    lines = txt.strip().split("\n")
    signals = []
    for line in lines:
        signal = {}
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1]
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if "x" not in value and "z" not in value:
                    signal[key] = int(value)
                else:
                    signal[key] = value 
        signals.append(signal)
    return signals
