class GoldenDUT:
    def __init__(self):
        # Initialize the state encoding
        self.states = {
            'S0': 0b0000000001,
            'S1': 0b0000000010,
            'S2': 0b0000000100,
            'S3': 0b0000001000,
            'S4': 0b0000010000,
            'S5': 0b0000100000,
            'S6': 0b0001000000,
            'S7': 0b0010000000,
            'S8': 0b0100000000,
            'S9': 0b1000000000
        }
        self.current_state = self.states['S0']

    def load(self, signal_vector):
        state = signal_vector['state']
        in_signal = signal_vector['in']
        next_state, out1, out2 = self.state_transition(state, in_signal)
        return next_state, out1, out2

    def state_transition(self, state, in_signal):
        if state == self.states['S0']:
            return (self.states['S0'], 0, 0) if in_signal == 0 else (self.states['S1'], 0, 0)
        elif state == self.states['S1']:
            return (self.states['S0'], 0, 0) if in_signal == 0 else (self.states['S2'], 0, 0)
        elif state == self.states['S2']:
            return (self.states['S0'], 0, 0) if in_signal == 0 else (self.states['S3'], 0, 0)
        elif state == self.states['S3']:
            return (self.states['S0'], 0, 0) if in_signal == 0 else (self.states['S4'], 0, 0)
        elif state == self.states['S4']:
            return (self.states['S0'], 0, 0) if in_signal == 0 else (self.states['S5'], 0, 0)
        elif state == self.states['S5']:
            return (self.states['S8'], 0, 0) if in_signal == 0 else (self.states['S6'], 0, 0)
        elif state == self.states['S6']:
            return (self.states['S9'], 0, 0) if in_signal == 0 else (self.states['S7'], 0, 0)
        elif state == self.states['S7']:
            return (self.states['S0'], 0, 1) if in_signal == 0 else (self.states['S7'], 0, 1)
        elif state == self.states['S8']:
            return (self.states['S0'], 1, 0) if in_signal == 0 else (self.states['S1'], 1, 0)
        elif state == self.states['S9']:
            return (self.states['S0'], 1, 1) if in_signal == 0 else (self.states['S1'], 1, 1)
        return 0b0, 0, 0

    def check(self, signal_vector):
        expected_next_state, expected_out1, expected_out2 = self.load(signal_vector)
        actual_next_state = signal_vector.get('next_state', 0)
        actual_out1 = signal_vector.get('out1', 0)
        actual_out2 = signal_vector.get('out2', 0)

        return (expected_next_state == actual_next_state) and (expected_out1 == actual_out1) and (expected_out2 == actual_out2)

