class GoldenDUT:
    def __init__(self):
        self.x_reg = 0
        self.y_reg = 0b000
        self.Y0_reg = 0
        self.z_reg = 0

    def load(self, signal_vector):
        self.x_reg = signal_vector['x']
        self.y_reg = signal_vector['y']

    def check(self, signal_vector):
        expected_Y0, expected_z = self.fsm_expected_outputs(self.y_reg, self.x_reg)

        Y0_observed = signal_vector['Y0']
        z_observed = signal_vector['z']

        result = True

        if expected_Y0 != Y0_observed:
            print(f"Scenario: {signal_vector['scenario']}, expected: Y0={expected_Y0}, observed: Y0={Y0_observed}")
            result = False

        if expected_z != z_observed:
            print(f"Scenario: {signal_vector['scenario']}, expected: z={expected_z}, observed: z={z_observed}")
            result = False

        return result

    def fsm_expected_outputs(self, y, x):
        # Define state transition table and output as a dictionary
        state_table = {
            0b000: (0b000, 0b001, 0),
            0b001: (0b001, 0b100, 0),
            0b010: (0b010, 0b001, 0),
            0b011: (0b001, 0b010, 1),
            0b100: (0b011, 0b100, 1)
        }

        if y not in state_table:
            raise ValueError("Invalid state provided")

        # Determine the next state and output based on input x
        if x == 0:
            next_state = state_table[y][0]
            output_z = state_table[y][2]
        elif x == 1:
            next_state = state_table[y][1]
            output_z = state_table[y][2]
        else:
            raise ValueError("Invalid input x provided")

        # Return next state Y0 (Y[0]) and output z
        return next_state & 0b001, output_z

