class GoldenDUT:
    # Define constants for each state
    STATE_A = 0b00
    STATE_B = 0b01
    STATE_C = 0b10
    STATE_D = 0b11

    def __init__(self):
        # Initialize the registers with initial values
        self.state_reg = self.STATE_A
        self.g_reg = 0b000

    def load(self, signal_vector):
        # Load input signals and advance the FSM state
        resetn = signal_vector['resetn']
        r = [(signal_vector['r'] & 0b100) >> 2, 
             (signal_vector['r'] & 0b010) >> 1, 
             signal_vector['r'] & 0b001]

        if not resetn:  # Active low reset
            self.state_reg = self.STATE_A
            self.g_reg = 0b000
        else:
            self.g_reg, self.state_reg = self.fsm_state_transition(self.state_reg, r)

    def check(self, signal_vector):
        if signal_vector['check_en']:  # Only check when check_en is True
            g_observed = signal_vector['g']

            if self.g_reg != g_observed:
                print(f"Scenario: {signal_vector['scenario']}, expected: g={bin(self.g_reg)}, observed g={bin(g_observed)}")
                return False
            return True

    def fsm_state_transition(self, current_state, r):
        # Determine the next state and grant based on the current state and request
        r1, r2, r3 = r

        if current_state == self.STATE_A:
            if r1:
                return 0b001, self.STATE_B  # g1 asserted (Device 1)
            elif r2:
                return 0b010, self.STATE_C  # g2 asserted (Device 2)
            elif r3:
                return 0b100, self.STATE_D  # g3 asserted (Device 3)
            else:
                return 0b000, self.STATE_A  # No grant, stay in A
        elif current_state == self.STATE_B:
            if r1:
                return 0b001, self.STATE_B  # g1 remains asserted as long as r1 is set
            else:
                return 0b000, self.STATE_A  # No requests for r1, return to A
        elif current_state == self.STATE_C:
            if r2:
                return 0b010, self.STATE_C  # g2 remains asserted as long as r2 is set
            else:
                return 0b000, self.STATE_A  # No requests for r2, return to A
        elif current_state == self.STATE_D:
            if r3:
                return 0b100, self.STATE_D  # g3 remains asserted as long as r3 is set
            else:
                return 0b000, self.STATE_A  # No requests for r3, return to A
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
