class GoldenDUT:
    def __init__(self):
        self.state_reg = 'A'  # Initial state
        self.g1_reg = 0
        self.g2_reg = 0
        self.g3_reg = 0

    def load(self, signal_vector):
        # Parse the input request signals
        r = ((signal_vector['r'] >> 2) & 1, (signal_vector['r'] >> 1) & 1, signal_vector['r'] & 1)

        # Handle reset signal
        if signal_vector['resetn'] == 0:
            self.reset_to_initial_state()
        else:
            # Transition to the next state and set grants accordingly
            self.state_reg, grants = self.fsm_expected_state_transition(self.state_reg, r)
            self.g1_reg, self.g2_reg, self.g3_reg = grants

    def reset_to_initial_state(self):
        # Reset to state A with no grants
        self.state_reg = 'A'
        self.g1_reg = 0
        self.g2_reg = 0
        self.g3_reg = 0

    def check(self, signal_vector):
        if signal_vector['check_en']:
            # Parse observed grants
            g_observed = ((signal_vector['g'] >> 2) & 1, (signal_vector['g'] >> 1) & 1, signal_vector['g'] & 1)
            # Determine expected grants from current registers
            g_expected = (self.g1_reg, self.g2_reg, self.g3_reg)
            # Compare observed and expected grants
            if g_observed != g_expected:
                print(f"Scenario: {signal_vector['scenario']}, expected: g={g_expected}, observed: g={g_observed}")
                return False
        return True

    def fsm_expected_state_transition(self, current_state, r):
        r1, r2, r3 = r

        if current_state == 'A':
            # Check priority for transitioning from state A
            if r1 == 1:
                return ('B', (1, 0, 0))  # Grant to request 1
            elif r2 == 1:
                return ('C', (0, 1, 0))  # Grant to request 2
            elif r3 == 1:
                return ('D', (0, 0, 1))  # Grant to request 3
            else:
                return ('A', (0, 0, 0))  # No requests

        elif current_state == 'B':
            # Stay in B as long as r1 is active
            if r1 == 1:
                return ('B', (1, 0, 0))
            else:
                return ('A', (0, 0, 0))

        elif current_state == 'C':
            # Stay in C as long as r2 is active
            if r2 == 1:
                return ('C', (0, 1, 0))
            else:
                return ('A', (0, 0, 0))

        elif current_state == 'D':
            # Always return to A from D
            return ('A', (0, 0, 0))

        # Default fallback if no valid transition was made
        return ('A', (0, 0, 0))
def check_dut(vectors_in):
