class GoldenDUT:
    def __init__(self):
        self.state_reg = 'A'
        self.g_reg = [0, 0, 0]  # [g3, g2, g1]

    def load(self, signal_vector):
        if signal_vector['resetn'] == 0:
            self.state_reg = 'A'
            self.g_reg = [0, 0, 0]
        else:
            # Get the current requests
            r = [(signal_vector['r'] >> 2) & 0x1, 
                 (signal_vector['r'] >> 1) & 0x1, 
                 signal_vector['r'] & 0x1]

            # Update state and grants based on FSM rules
            self.state_reg, self.g_reg = self.fsm_core_rules(self.state_reg, r)

    def check(self, signal_vector):
        observed_g = [(signal_vector['g'] >> 2) & 0x1, 
                      (signal_vector['g'] >> 1) & 0x1, 
                      signal_vector['g'] & 0x1]

        if signal_vector['check_en']:
            if self.g_reg != observed_g:
                print(f"Scenario: {signal_vector['scenario']}, "
                      f"expected: g={self.g_reg}, observed g={observed_g}")
                return False
            return True

    def fsm_core_rules(self, current_state, r):
        r1, r2, r3 = r  # r1 represents the highest priority request
        g = [0, 0, 0]

        if current_state == 'A':
            if r1 == 1:
                next_state = 'B'
                g = [0, 0, 1]  # g1 = 1
            elif r2 == 1:
                next_state = 'C'
                g = [0, 1, 0]  # g2 = 1
            elif r3 == 1:
                next_state = 'D'
                g = [1, 0, 0]  # g3 = 1
            else:
                next_state = 'A'
        elif current_state == 'B':
            if r1 == 1:
                next_state = 'B'
                g = [0, 0, 1]  # g1 = 1
            else:
                next_state = 'A'
        elif current_state == 'C':
            if r2 == 1:
                next_state = 'C'
                g = [0, 1, 0]  # g2 = 1
            else:
                next_state = 'A'
        elif current_state == 'D':
            next_state = 'A'  # No grants since all g are 0

        return next_state, g
