class GoldenDUT:
    def __init__(self):
        # States of the FSM
        self.state_reg = 'WAIT_FOR_FIRST_BYTE'
        self.done_reg = 0

    def load(self, signal_vector):
        if signal_vector['reset']:
            self.state_reg = 'WAIT_FOR_FIRST_BYTE'
            self.done_reg = 0
        else:
            input_byte = signal_vector['in']

            if self.state_reg == 'WAIT_FOR_FIRST_BYTE':
                if (input_byte & 0b00001000) != 0:  # Check if in[3] is 1
                    self.state_reg = 'BYTE_2'
                self.done_reg = 0  # Ensure done is 0 in this state

            elif self.state_reg == 'BYTE_2':
                self.state_reg = 'BYTE_3'
                self.done_reg = 0  # Ensure done is 0 in this state

            elif self.state_reg == 'BYTE_3':
                self.state_reg = 'WAIT_FOR_FIRST_BYTE'
                self.done_reg = 1  # Done should be asserted

    def check(self, signal_vector):
        if signal_vector['check_en']:
            done_observed = signal_vector['done']
            if done_observed != self.done_reg:
                print(f"Scenario: {signal_vector['scenario']}, expected: done={self.done_reg}, observed done={done_observed}")
                return False
        return True

    # Other utility methods if needed can be added

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

