class GoldenDUT:
    def __init__(self):
        # Initialize internal state registers
        self.state_reg = 'A'
        self.x_sequence_reg = []  # To track x input sequence
        self.y_monitor_reg = 0  # To track number of cycles y is monitored
        self.f_reg = 0
        self.g_reg = 0

    def load(self, signal_vector):
        # Handle reset state
        if signal_vector['resetn'] == 0:
            self.state_reg = 'A'
            self.x_sequence_reg = []
            self.y_monitor_reg = 0
            self.f_reg = 0
            self.g_reg = 0
        else:
            if self.state_reg == 'A':
                # Switch to the active state on de-assertion of reset
                self.f_reg = 1
                self.state_reg = 'ACTIVE'
            elif self.state_reg == 'ACTIVE':
                # Set f back to 0 after one cycle
                self.f_reg = 0
                self._monitor_x(signal_vector['x'])
                if self.g_reg == 1:
                    self._monitor_y(signal_vector['y'])

    def _monitor_x(self, x):
        # Track x input sequence for '1, 0, 1'
        self.x_sequence_reg.append(x)
        if len(self.x_sequence_reg) > 3:
            self.x_sequence_reg.pop(0)
        if self.x_sequence_reg == [1, 0, 1]:
            self.g_reg = 1

    def _monitor_y(self, y):
        # Monitor y input for up to two cycles once g is 1
        self.y_monitor_reg += 1
        if y == 1:
            self.state_reg = 'LATCHED'
        elif self.y_monitor_reg >= 2:
            self.g_reg = 0

    def check(self, signal_vector):
        f_expected = self.f_reg
        g_expected = self.g_reg
        f_observed = signal_vector['f']
        g_observed = signal_vector['g']

        if (f_expected != f_observed) or (g_expected != g_observed):
            print(f"Scenario: {signal_vector['scenario']}, expected: f={f_expected}, g={g_expected}, observed f={f_observed}, g={g_observed}")
            return False
        return True

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
