class GoldenDUT:
    def __init__(self):
        self.p_reg = 0  # Initial value of p
        self.q_reg = 0  # Initial value of q
        self.a_reg = 0  # Initial value of a
        self.prev_p = 0  # To store the previous cycle state of p

    def load(self, signal_vector):
        # Load the input signal 'a'
        self.a_reg = signal_vector['a']

        # Store current p_reg to prev_p for delayed effect on q_reg
        self.prev_p = self.p_reg

        # Update p on a rising edge of clock, which is implicated by sequential call
        if self.a_reg == 1:
            self.p_reg = 1
        else:
            self.p_reg = 0

        # q follows the previous state of p one clock cycle later
        self.q_reg = self.prev_p

    def check(self, signal_vector):
        # Check the expected output signals 'p' and 'q' with those from DUT
        expected_p = self.p_reg
        expected_q = self.q_reg

        observed_p = signal_vector['p']
        observed_q = signal_vector['q']

        if observed_p != expected_p or observed_q != expected_q:
            print(f"Scenario: {signal_vector['scenario']}, expected: p={expected_p}, q={expected_q}, observed: p={observed_p}, q={observed_q}")
            return False

        return True

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

