        q_observed = signal_vector['q']

        # Determine if the output is expected
        passed = (self.p_reg == p_observed) and (self.q_reg == q_observed)
        if not passed:
            print(f"Scenario: {signal_vector['scenario']}, expected: p={self.p_reg}, q={self.q_reg}, observed: p={p_observed}, q={q_observed}")

        return passed

    def update_internal_state(self):
        # Additional method if needed for complex state machine logic
        pass

