import numpy as np

class GoldenDUT:
    def __init__(self):
        # Initialize any needed internal states or attributes
        pass

    def load(self, signal_vector):
        # Load inputs and calculate expected outputs
        input_vector = self._get_input_vector(signal_vector['in'])

        out_both = self._calculate_out_both(input_vector)
        out_any = self._calculate_out_any(input_vector)
        out_different = self._calculate_out_different(input_vector)

        return out_both, out_any, out_different

    def check(self, signal_vector):
        # Get expected output values and compare with DUT's actual outputs
        expected_out_both, expected_out_any, expected_out_different = self.load(signal_vector)

        actual_out_both = self._get_output_vector(signal_vector['out_both'], 99)
        actual_out_any = self._get_output_vector(signal_vector['out_any'], 99)
        actual_out_different = self._get_output_vector(signal_vector['out_different'], 100)

        return (np.array_equal(expected_out_both, actual_out_both) and
                np.array_equal(expected_out_any, actual_out_any) and
                np.array_equal(expected_out_different, actual_out_different))

    def _get_input_vector(self, input_value):
        # Convert the input value to a binary vector of 100 bits
        return [int(x) for x in format(input_value, '0100b')]

    def _get_output_vector(self, output_value, length):
        # Convert the output value to a binary vector of specified length bits
        return [int(x) for x in format(int(output_value), f'0{length}b')]

    def _calculate_out_both(self, input_vector):
        # Calculate out_both[98:0]
        out_both = np.zeros(99, dtype=int)
        for i in range(98, -1, -1):
            if input_vector[i] == 1 and input_vector[i + 1] == 1:
                out_both[i] = 1
        return out_both

    def _calculate_out_any(self, input_vector):
        # Calculate out_any[99:1]
        out_any = np.zeros(99, dtype=int)
        for i in range(99, 0, -1):
            if input_vector[i] == 1 or input_vector[i - 1] == 1:
                out_any[i - 1] = 1
        return out_any

    def _calculate_out_different(self, input_vector):
        # Calculate out_different[99:0], wraps around
        out_different = np.zeros(100, dtype=int)
        for i in range(99, 0, -1):
            if input_vector[i] != input_vector[i - 1]:
                out_different[i] = 1
        # wrap-around condition for index 0
        if input_vector[0] != input_vector[99]:
            out_different[0] = 1
        return out_different

