class GoldenDUT:
    def __init__(self):
        # Initialize registers and state
        self.state_reg = 'A'  # FSM starts at state A
        self.w_seq_reg = [0, 0, 0]
        self.z_reg = 0
        self.w_count_reg = 0
        self.cycle_count_reg = 0

    def load(self, signal_vector):
        # Load input signals and process state transitions
        if signal_vector['reset'] == 1:
            self.state_reg = 'A'
            self.w_seq_reg = [0, 0, 0]
            self.z_reg = 0
            self.w_count_reg = 0
            self.cycle_count_reg = 0
        elif self.state_reg == 'A':
            if signal_vector['s'] == 1:
                self.state_reg = 'B'
                self.cycle_count_reg = 0
        elif self.state_reg == 'B':
            self.w_seq_reg[self.cycle_count_reg] = signal_vector['w']
            self.cycle_count_reg += 1
            if self.cycle_count_reg == 3:
                self.z_reg = self.fsm_expected_behavior(self.w_seq_reg)
                self.w_seq_reg = [0, 0, 0]
                self.state_reg = 'A'
                self.cycle_count_reg = 0

    def check(self, signal_vector):
        # Check if the DUT output matches the expected output
        if signal_vector['check_en']:
            z_observed = signal_vector['z']
            if self.z_reg != z_observed:
                print(f"Scenario: {signal_vector['scenario']}, expected: z={self.z_reg}, observed z={z_observed}")
                return False
        return True

    def fsm_expected_behavior(self, w_sequence):
        # Determine the expected z output for a given sequence of w in state B
        w_count = sum(w_sequence)
        return 1 if w_count == 2 else 0

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
