class GoldenDUT:
    def __init__(self):
        self.state_reg = 'A'  # Initial state
        self.w_count_reg = 0  # Count of w=1 in state B
        self.cycle_counter_reg = 0  # Counter for three cycles in state B
        self.z_reg = 0  # Output register

    def load(self, signal_vector):
        # Reset logic - synchronous reset
        if signal_vector['reset'] == 1:
            self.__init__()  # Reset to initial state
        else:
            if self.state_reg == 'A':
                if signal_vector['s'] == 1:
                    # Transition to state B
                    self.state_reg = 'B'
                    self.w_count_reg = 0
                    self.cycle_counter_reg = 0
            elif self.state_reg == 'B':
                if signal_vector['w'] == 1:
                    self.w_count_reg += 1
                self.cycle_counter_reg += 1

                if self.cycle_counter_reg == 3:
                    # Check if count of w=1 is exactly 2
                    if self.w_count_reg == 2:
                        self.z_reg = 1
                    else:
                        self.z_reg = 0

                    # Reset state to A after evaluation
                    self.state_reg = 'A'
                    self.cycle_counter_reg = 0  # Reset counter for state B
                    self.w_count_reg = 0  # Reset w count for next evaluation

                # Ensure z_reg is reset at the start of new evaluation block
                if self.cycle_counter_reg == 0:
                    self.z_reg = 0

    def check(self, signal_vector):
        z_observed = signal_vector['z']
        if signal_vector['check_en']:
            expected_z = self.z_reg
            if expected_z != z_observed:
                print(f"Scenario: {signal_vector['scenario']}, expected: z={expected_z}, observed: z={z_observed}")
                return False
        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

