    def __init__(self):
        # Initialize the internal state and counters
        self.state_reg = 'A'
        self.w_sequence_reg = []
        self.z_reg = 0

    def load(self, signal_vector):
        # Handle reset
        if signal_vector['reset'] == 1:
            self.state_reg = 'A'
            self.w_sequence_reg = []
            self.z_reg = 0
            return

        # State transition and register updates
        if self.state_reg == 'A':
            # Check for transition condition
            if signal_vector['s'] == 1:
                self.state_reg = 'B'
                self.w_sequence_reg = []
        elif self.state_reg == 'B':
            # Collect current 'w' value
            self.w_sequence_reg.append(signal_vector['w'])

            # Check if 3-cycle collection is complete
            if len(self.w_sequence_reg) == 3:
                # Determine the expected 'z' value
                self.z_reg = self.evaluate_w_sequence(self.w_sequence_reg)
                # Reset w_sequence for next round of checking
                self.w_sequence_reg.pop(0)  # Keep the last plus the next two for overlap

    def evaluate_w_sequence(self, w_sequence):
        # Count the number of 1s in the three cycle window
        ones_count = sum(w_sequence)
        # Return 1 if there are exactly two 1s, else return 0
        return 1 if ones_count == 2 else 0

    def check(self, signal_vector):
        if signal_vector['check_en']:
            # Compare expected 'z' with observed 'z'
            z_observed = signal_vector['z']
            if self.z_reg != z_observed:
                print(f"Scenario: {signal_vector['scenario']}, expected: z={self.z_reg}, observed z={z_observed}")
