class GoldenDUT:
    STATE_A = 0b01
    STATE_B = 0b10

    def __init__(self):
        self.state_reg = self.STATE_A
        self.z_reg = 0

    def load(self, signal_vector):
        areset = signal_vector['areset']
        x = signal_vector['x']

        if areset:  # When asynchronous reset is high
            self.state_reg = self.STATE_A
            self.z_reg = 0  # The output should be 0 when reset
        else:
            if self.state_reg == self.STATE_A:
                if x == 0:
                    self.z_reg = 0  # In state A, x=0 -> z=0
                elif x == 1:
                    self.z_reg = 1  # In state A, x=1 -> z=1
                    self.state_reg = self.STATE_B  # Transition to state B
            elif self.state_reg == self.STATE_B:
                if x == 0:
                    self.z_reg = 1  # In state B, x=0 -> z=1
                    # Remain in state B
                elif x == 1:
                    self.z_reg = 0  # In state B, x=1 -> z=0
                    # Remain in state B

    def check(self, signal_vector):
        z_observed = signal_vector['z']
        if self.z_reg == z_observed:
            return True
        else:
            print(f"Scenario: {signal_vector['scenario']}, expected: z={self.z_reg}, observed z={z_observed}")
            return False
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

