class GoldenDUT:
    def __init__(self):
        # The initial state is A
        self.state_reg = 'A'
        # Internal register for output
        self.z_reg = 0  # Initialize to known state, not 'x'

    def load(self, signal_vector):
        # Load input signals
        areset = signal_vector['areset']
        x = signal_vector['x']

        # Handle asynchronous reset
        if areset == 1:
            self.state_reg = 'A'
            self.z_reg = 0  # Set output to default when reset
        else:
            # State transition based on current state and input 'x'
            if self.state_reg == 'A':
                if x == 0:
                    self.state_reg = 'A'
                    self.z_reg = 0
                elif x == 1:
                    self.state_reg = 'B'
                    self.z_reg = 1
            elif self.state_reg == 'B':
                if x == 0:
                    self.state_reg = 'B'
                    self.z_reg = 1
                elif x == 1:
                    self.state_reg = 'B'
                    self.z_reg = 0

    def check(self, signal_vector):
        # Extract observed output and scenario number from signal vector
        z_observed = signal_vector['z']
        scenario = signal_vector['scenario']

        # Compare expected and observed outputs
        if z_observed != self.z_reg:
            print(f"Scenario: {scenario}, expected: z={self.z_reg}, observed z={z_observed}")
            return False
        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

