class GoldenDUT:
    def __init__(self):
        # Initialize internal states
        self.state_reg = 0
        self.disc_reg = 0
        self.flag_reg = 0
        self.err_reg = 0

    def load(self, signal_vector):
        # Input signals
        reset = signal_vector['reset']
        in_signal = signal_vector['in']

        # Reset behavior
        if reset:
            self.state_reg = 0
            self.disc_reg = 0
            self.flag_reg = 0
            self.err_reg = 0
            return

        # FSM state transitions and output logic
        if self.state_reg == 0:
            if in_signal == 1:
                self.state_reg = 1
        elif self.state_reg == 1:
            if in_signal == 1:
                self.state_reg = 2
            else:
                self.state_reg = 0
        elif self.state_reg == 2:
            if in_signal == 1:
                self.state_reg = 3
            else:
                self.state_reg = 0
        elif self.state_reg == 3:
            if in_signal == 1:
                self.state_reg = 4
            else:
                self.state_reg = 0
        elif self.state_reg == 4:
            if in_signal == 1:
                self.state_reg = 5
            else:
                self.state_reg = 0
        elif self.state_reg == 5:
            if in_signal == 1:
                self.state_reg = 6
            else:
                self.state_reg = 0
        elif self.state_reg == 6:
            if in_signal == 0:
                self.disc_reg = 1
                self.state_reg = 0
            elif in_signal == 1:
                self.state_reg = 7
        elif self.state_reg == 7:  # More than six consecutive 1s
            if in_signal == 1:
                self.err_reg = 1
                self.state_reg = 7  # Stay in error state
            else:
                self.flag_reg = 1
                self.state_reg = 0

    def check(self, signal_vector):
        # Output signals from DUT to be compared
        disc_observed = signal_vector['disc']
        flag_observed = signal_vector['flag']
        err_observed = signal_vector['err']

        # Compare expected vs observed
        correct = True
        if self.disc_reg != disc_observed:
            print(f"Scenario: {signal_vector['scenario']}, expected: disc={self.disc_reg}, observed disc={disc_observed}")
            correct = False
        if self.flag_reg != flag_observed:
            print(f"Scenario: {signal_vector['scenario']}, expected: flag={self.flag_reg}, observed flag={flag_observed}")
            correct = False
        if self.err_reg != err_observed:
            print(f"Scenario: {signal_vector['scenario']}, expected: err={self.err_reg}, observed err={err_observed}")
            correct = False

        # Reset reg flags after checking
        self.disc_reg = 0
        self.flag_reg = 0
        self.err_reg = 0

        return correct
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

