class GoldenDUT:
    def __init__(self):
        self.state_reg = 'IDLE'
        self.consecutive_ones_reg = 0
        self.disc_reg = 0
        self.flag_reg = 0
        self.err_reg = 0

    def load(self, signal_vector):
        if signal_vector['reset'] == 1:
            self.state_reg = 'IDLE'
            self.consecutive_ones_reg = 0
            self.disc_reg = 0
            self.flag_reg = 0
            self.err_reg = 0
        else:
            self._update_state(signal_vector['in'])

    def _update_state(self, input_bit):
        if self.state_reg == 'IDLE':
            if input_bit == 1:
                self.consecutive_ones_reg = 1
                self.state_reg = 'ONE'
            else:
                self.consecutive_ones_reg = 0
        elif self.state_reg == 'ONE':
            if input_bit == 1:
                self.consecutive_ones_reg += 1
                if self.consecutive_ones_reg == 6:
                    self.state_reg = 'SIX_ONES'
                elif self.consecutive_ones_reg > 6:
                    self.err_reg = 1
                    self.state_reg = 'ERROR'
            else:
                self.consecutive_ones_reg = 0
                self.state_reg = 'IDLE'
        elif self.state_reg == 'SIX_ONES':
            if input_bit == 0:
                self.disc_reg = 1
                self.flag_reg = 0
                self.state_reg = 'IDLE'
            elif input_bit == 1:
                self.disc_reg = 0
                self.flag_reg = 1
                self.state_reg = 'FLAG'
        elif self.state_reg == 'FLAG':
            self.disc_reg = 0
            if input_bit == 1:
                self.flag_reg = 0
                self.err_reg = 1
                self.state_reg = 'ERROR'
            else:
                self.flag_reg = 0
                self.state_reg = 'IDLE'
                self.consecutive_ones_reg = 0
        elif self.state_reg == 'ERROR':
            self.err_reg = 1  # Continuously assert error while in ERROR state
            if input_bit == 0:
                self.consecutive_ones_reg = 0
                self.state_reg = 'IDLE'
                self.err_reg = 0  # Clear error on resetting to IDLE state

    def check(self, signal_vector):
        if not signal_vector['check_en']:
            return True

        disc_observed = signal_vector['disc']
        flag_observed = signal_vector['flag']
        err_observed = signal_vector['err']

        if (self.disc_reg == disc_observed and 
            self.flag_reg == flag_observed and 
            self.err_reg == err_observed):
            return True
        else:
            print(f"Scenario: {signal_vector['scenario']}, "
                  f"expected: disc={self.disc_reg}, flag={self.flag_reg}, err={self.err_reg}; "
                  f"observed: disc={disc_observed}, flag={flag_observed}, err={err_observed}")
            return False
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

