class GoldenDUT:
    def __init__(self):
        self.one_count_reg = 0
        self.disc_reg = 0
        self.flag_reg = 0
        self.err_reg = 0

    def load(self, signal_vector):
        if signal_vector['reset']:
            self.one_count_reg = 0
            self.disc_reg = 0
            self.flag_reg = 0
            self.err_reg = 0
        else:
            in_signal = signal_vector['in']
            if in_signal == 1:
                self.one_count_reg += 1
                # Check for error condition (7 or more consecutive 1s)
                if self.one_count_reg >= 7:
                    self.err_reg = 1
                    # Reset disc and flag if error is triggered
                    self.disc_reg = 0
                    self.flag_reg = 0
            else:
                if self.one_count_reg == 5:
                    self.disc_reg = 1
                if self.one_count_reg == 6:
                    self.flag_reg = 1
                self.one_count_reg = 0

    def check(self, signal_vector):
        if not signal_vector['check_en']:
            return True

        disc_observed = signal_vector['disc']
        flag_observed = signal_vector['flag']
