class GoldenDUT:
    def __init__(self):
        # Initialize the internal state and output registers
        self.state_reg = 'S0'
        self.count_ones_reg = 0
        self.disc_reg = 0
        self.flag_reg = 0
        self.err_reg = 0

    def load(self, signal_vector):
        # Reset the FSM if the reset signal is high
        if signal_vector['reset']:
            self.reset_fsm()
        else:
            # Process the input bit on each clock cycle
            self.process_input(signal_vector['in'])

    def check(self, signal_vector):
        # Check the outputs against the expected values
        if signal_vector['check_en']:
            expected_disc = signal_vector['disc']
            expected_flag = signal_vector['flag']
            expected_err = signal_vector['err']
            if (self.disc_reg, self.flag_reg, self.err_reg) == (expected_disc, expected_flag, expected_err):
                return True
            else:
                print(f"Scenario: {signal_vector['scenario']}, expected: disc={expected_disc}, flag={expected_flag}, err={expected_err}, "
                      f"observed: disc={self.disc_reg}, flag={self.flag_reg}, err={self.err_reg}")
                return False
        return True

    def reset_fsm(self):
        # Clear the internal state and output registers
        self.state_reg = 'S0'
        self.count_ones_reg = 0
        self.disc_reg = 0
        self.flag_reg = 0
        self.err_reg = 0

    def process_input(self, bit):
        # Clear outputs before state transitions
        self.disc_reg, self.flag_reg, self.err_reg = 0, 0, 0

        if self.state_reg == 'S0':
            if bit == 0:
                self.count_ones_reg = 0
            elif bit == 1:
                self.count_ones_reg = 1
                self.state_reg = 'S1'

        elif self.state_reg == 'S1':
            if bit == 0:
                self.count_ones_reg = 0
                self.state_reg = 'S0'
            elif bit == 1:
                self.count_ones_reg = 2
                self.state_reg = 'S2'

        elif self.state_reg == 'S2':
            if bit == 0:
                self.count_ones_reg = 0
                self.state_reg = 'S0'
            elif bit == 1:
                self.count_ones_reg = 3
                self.state_reg = 'S3'

        elif self.state_reg == 'S3':
            if bit == 0:
                self.count_ones_reg = 0
                self.state_reg = 'S0'
            elif bit == 1:
                self.count_ones_reg = 4
                self.state_reg = 'S4'

        elif self.state_reg == 'S4':
            if bit == 0:
                self.count_ones_reg = 0
                self.state_reg = 'S0'
            elif bit == 1:
                self.count_ones_reg = 5
                self.state_reg = 'S5'

        elif self.state_reg == 'S5':
            if bit == 0:
                self.count_ones_reg = 0
                self.state_reg = 'S0'
                self.disc_reg = 1
            elif bit == 1:
                self.count_ones_reg = 6
                self.state_reg = 'S6'

        elif self.state_reg == 'S6':
            if bit == 0:
                self.count_ones_reg = 0
                self.state_reg = 'S0'
                self.flag_reg = 1
            elif bit == 1:
                self.count_ones_reg = 7
                self.state_reg = 'S7'

        elif self.state_reg == 'S7':
            if bit == 0:
                self.count_ones_reg = 0
                self.state_reg = 'S0'
            elif bit == 1:
                self.count_ones_reg += 1
                self.err_reg = 1

        # Ensure the FSM transitions back to the initial state after detecting an error
        if self.count_ones_reg >= 7:
            self.state_reg = 'S0'
            self.count_ones_reg = 0
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

