class GoldenDUT:
    def __init__(self):
        # Initialize internal state
        self.consecutive_ones_reg = 0
        self.disc_reg = 0
        self.flag_reg = 0
        self.err_reg = 0

    def load(self, signal_vector):
        # Capture and process the input signal
        input_bit = signal_vector['in']
        reset = signal_vector['reset']

        # Handle reset condition
        if reset == 1:
            self.consecutive_ones_reg = 0
            self.disc_reg = 0
            self.flag_reg = 0
            self.err_reg = 0
            return

        # FSM behavior
        if self.consecutive_ones_reg >= 5:
            if input_bit == 0:
                if self.consecutive_ones_reg == 5:
                    # Sequence: 0111110, discard the zero
                    self.disc_reg = 1
                elif self.consecutive_ones_reg == 6:
                    # Sequence: 01111110, flag the frame
                    self.flag_reg = 1
                self.err_reg = 0
                self.consecutive_ones_reg = 0
            else:
                # Sequence: 0111111..., check for 7+ ones (error)
                if self.consecutive_ones_reg >= 6:
                    self.err_reg = 1
                else:
                    self.err_reg = 0
                self.consecutive_ones_reg += 1
                self.disc_reg = 0
                self.flag_reg = 0
        else:
            if input_bit == 1:
                self.consecutive_ones_reg += 1
            else:
                self.consecutive_ones_reg = 0
                self.disc_reg = 0
                self.flag_reg = 0
                self.err_reg = 0

    def check(self, signal_vector):
        # Compare expected and observed outputs
        disc_observed = signal_vector['disc']
        flag_observed = signal_vector['flag']
        err_observed = signal_vector['err']

        disc_match = (disc_observed == self.disc_reg)
        flag_match = (flag_observed == self.flag_reg)
        err_match = (err_observed == self.err_reg)

        if not (disc_match and flag_match and err_match):
            print(f"Scenario: {signal_vector['scenario']}, expected: disc={self.disc_reg}, flag={self.flag_reg}, err={self.err_reg}, "
                  f"observed: disc={disc_observed}, flag={flag_observed}, err={err_observed}")
            return False
        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

