class GoldenDUT:
    def __init__(self):
        self.state_reg = 0
        self.in_reg = 0
        self.disc_reg = 0
        self.flag_reg = 0
        self.err_reg = 0
        self.one_count_reg = 0

    def load(self, signal_vector):
        # Update inputs and internal state for each clock cycle
        self.in_reg = signal_vector['in']

        if signal_vector['reset'] == 1:
            self.reset()

        self.update_state()

    def update_state(self):
        if self.in_reg == 0:
            # Reset count and clear outputs on zero input
            if self.one_count_reg == 5:
                self.disc_reg = 1
            elif self.one_count_reg == 6:
                self.flag_reg = 1
            elif self.one_count_reg > 6:
                self.err_reg = 1

            self.one_count_reg = 0

        else:
            # Increment counter for consecutive ones
            self.one_count_reg += 1
            # Adjust outputs based on count of consecutive ones
            if self.one_count_reg == 5:
                self.disc_reg = 1
            elif self.one_count_reg == 6:
                self.flag_reg = 1
            elif self.one_count_reg > 6:
                self.err_reg = 1
                self.flag_reg = 0  # Ensure flag can't occur on errors
                self.disc_reg = 0  # Ensure disc isn't mistakenly signaled on errors

    def reset(self):
        # Reset all internal states
        self.state_reg = 0
        self.one_count_reg = 0
        self.disc_reg = 0
        self.flag_reg = 0
        self.err_reg = 0

    def check(self, signal_vector):
        disc_observed = signal_vector['disc']
        flag_observed = signal_vector['flag']
        err_observed = signal_vector['err']

        disc_expected = self.disc_reg
        flag_expected = self.flag_reg
        err_expected = self.err_reg

        if (disc_expected == disc_observed and
            flag_expected == flag_observed and
            err_expected == err_observed):
            return True
        else:
            print(f"Scenario: {signal_vector['scenario']}, "
                  f"expected: disc={disc_expected}, flag={flag_expected}, err={err_expected}, "
                  f"observed: disc={disc_observed}, flag={flag_observed}, err={err_observed}")
            return False
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

