class GoldenDUT:
    def __init__(self):
        self.state_reg = 'start'
        self.disc_reg = 0
        self.flag_reg = 0
        self.err_reg = 0

    def load(self, signal_vector):
        # Handle the reset logic
        if signal_vector['reset'] == 1:
            self.state_reg = 'start'
            self.disc_reg = 0
            self.flag_reg = 0
            self.err_reg = 0
        else:
            self.fsm_logic(signal_vector['in'])

    def fsm_logic(self, bit):
        # Implementing the FSM transition logic
        if self.state_reg == 'start':
            if bit == 0:
                self.state_reg = 'start'
            elif bit == 1:
                self.state_reg = 's1'
            self.disc_reg = 0
            self.flag_reg = 0
            self.err_reg = 0

        elif self.state_reg == 's1':
            if bit == 0:
                self.state_reg = 'start'
            elif bit == 1:
                self.state_reg = 's11'
            self.disc_reg = 0
            self.flag_reg = 0
            self.err_reg = 0

        elif self.state_reg == 's11':
            if bit == 0:
                self.state_reg = 'start'
            elif bit == 1:
                self.state_reg = 's111'
            self.disc_reg = 0
            self.flag_reg = 0
            self.err_reg = 0

        elif self.state_reg == 's111':
