class GoldenDUT:
    def __init__(self):
        self.state_reg = 0  # Initial state is S0
        self.disc_reg = 0
        self.flag_reg = 0
        self.err_reg = 0

    def load(self, signal_vector):
        # Load inputs
        reset = signal_vector['reset']
        in_signal = signal_vector['in']

        # Reset logic
        if reset:
            self.state_reg = 0
            self.disc_reg = 0
            self.flag_reg = 0
            self.err_reg = 0
        else:
            # FSM transitions and output logic
            self._process_input(in_signal)

    def _process_input(self, in_signal):
        # Define state encoding
        S0, S1, S2, S3, S4, S5, S6, S7, ERR = range(9)

        # Reset outputs before processing
        self.disc_reg = 0
        self.flag_reg = 0
        self.err_reg = 0

        # Moore FSM transitions and output logic
        if self.state_reg == S0:
            self.state_reg = S1 if in_signal == 0 else S0
        elif self.state_reg == S1:
            self.state_reg = S2 if in_signal == 1 else S1
        elif self.state_reg == S2:
            self.state_reg = S3 if in_signal == 1 else S1
        elif self.state_reg == S3:
            self.state_reg = S4 if in_signal == 1 else S1
        elif self.state_reg == S4:
            self.state_reg = S5 if in_signal == 1 else S1
        elif self.state_reg == S5:
            self.state_reg = S6 if in_signal == 1 else S1
        elif self.state_reg == S6:
            if in_signal == 1:
                self.state_reg = S7
            else:
                self.state_reg = S1
                self.disc_reg = 1  # Detected 0111110
        elif self.state_reg == S7:
            if in_signal == 1:
                self.state_reg = ERR
                self.err_reg = 1  # Detected 01111111...
            else:
                self.state_reg = S1
                self.flag_reg = 1  # Detected 01111110
        elif self.state_reg == ERR:
            if in_signal == 0:
                self.state_reg = S1

    def check(self, signal_vector):
        if signal_vector['check_en']:
            # Check expected outputs against observable outputs
            disc_observed = signal_vector['disc']
            flag_observed = signal_vector['flag']
            err_observed = signal_vector['err']

            if (self.disc_reg == disc_observed and
                    self.flag_reg == flag_observed and
                    self.err_reg == err_observed):
                return True
            else:
                print(f"Scenario: {signal_vector['scenario']}, expected: disc={self.disc_reg}, flag={self.flag_reg}, err={self.err_reg}, "
                      f"observed: disc={disc_observed}, flag={flag_observed}, err={err_observed}")
                return False
        else:
            return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

