class GoldenDUT:
    def __init__(self):
        self.state_reg = 0
        self.count_ones_reg = 0
        self.disc_reg = 0
        self.flag_reg = 0
        self.err_reg = 0

    def load(self, signal_vector):
        in_signal = signal_vector['in']
        reset_signal = signal_vector['reset']

        if reset_signal:
            self.state_reg = 0
            self.count_ones_reg = 0
            self.disc_reg = 0
            self.flag_reg = 0
            self.err_reg = 0
        else:
            # Reset outputs from the previous clock cycle
            self.reset_flags()

            if in_signal == 0:
                # Handle zero input
                if self.count_ones_reg == 5:
                    self.disc_reg = 1
                elif self.count_ones_reg == 6:
                    self.flag_reg = 1

                # Reset count and state after processing zero
                self.count_ones_reg = 0
                self.state_reg = 0
            elif in_signal == 1:
                self.count_ones_reg += 1

                if self.count_ones_reg == 5:
                    self.disc_reg = 0  # Ensure disc signal isn't wrongly set

                if self.count_ones_reg == 6:
                    # Prepare for flag in next cycle
                    self.flag_reg = 1
                elif self.count_ones_reg > 6:
                    # Error condition for more than 6 consecutive ones
                    self.err_reg = 1
                    # Reset count logic ensures a subsequent zero or reset will recover correctly
                    self.count_ones_reg = 0

    def check(self, signal_vector):
        if signal_vector['check_en']:
            disc_observed = signal_vector['disc']
            flag_observed = signal_vector['flag']
            err_observed = signal_vector['err']

            match = (self.disc_reg == disc_observed and
                     self.flag_reg == flag_observed and
                     self.err_reg == err_observed)

            if not match:
                print(f"Scenario: {signal_vector['scenario']}, "
                      f"expected: disc={self.disc_reg}, flag={self.flag_reg}, err={self.err_reg}, "
                      f"observed: disc={disc_observed}, flag={flag_observed}, err={err_observed}")

            return match

    def reset_flags(self):
        # Reset registers after state actions to ensure proper flagging next cycle
        self.disc_reg = 0
        self.flag_reg = 0
        self.err_reg = 0
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

