class GoldenDUT:
    def __init__(self):
        # Internal state registers
        self.current_state_reg = 0  # Idle
        self.consecutive_ones_reg = 0

    def load(self, signal_vector):
        # Load input signals
        reset = signal_vector['reset']
        in_signal = signal_vector['in']

        if reset:
            # Reset the internal state
            self.current_state_reg = 0
            self.consecutive_ones_reg = 0
        else:
            # State transition logic
            if self.current_state_reg == 0:  # Idle state
                if in_signal == 1:
                    self.consecutive_ones_reg += 1
                else:
                    self.consecutive_ones_reg = 0

                if self.consecutive_ones_reg == 5:
                    self.current_state_reg = 1  # Transition to possible discarding state

            elif self.current_state_reg == 1:  # Possible discard state (five 1s)
                if in_signal == 0:
                    self.current_state_reg = 0  # Transition back to idle, correctly received '0111110'
                    self.consecutive_ones_reg = 0
                else:
                    self.consecutive_ones_reg += 1
                    if self.consecutive_ones_reg == 6:
                        self.current_state_reg = 2  # Transition to flag state

            elif self.current_state_reg == 2:  # Flag state (six 1s)
                if in_signal == 0:
                    self.current_state_reg = 0  # Transition back to idle after flag
                    self.consecutive_ones_reg = 0
                else:
                    self.consecutive_ones_reg += 1
                    if self.consecutive_ones_reg > 6:
                        self.current_state_reg = 3  # Transition to error state

            elif self.current_state_reg == 3:  # Error state
                # Stay in error state until reset
                if in_signal == 0:
                    self.consecutive_ones_reg = 0  # Clear consecutive ones on a reset command or back to initial

            # Ensure correct state transitions for error detection
            if self.consecutive_ones_reg > 6:
                self.current_state_reg = 3  # Consistently move to Error State on 7+ ones

    def check(self, signal_vector):
        # Determine expected outputs
        disc_expected = False
        flag_expected = False
        err_expected = False

        if self.current_state_reg == 1:  # Six ones state (ready to discard zero)
            disc_expected = True
        elif self.current_state_reg == 2:  # Flag state
            flag_expected = True
        elif self.current_state_reg == 3:  # Error state
            err_expected = True

        # Compare with observed outputs
        disc_observed = signal_vector['disc']
        flag_observed = signal_vector['flag']
        err_observed = signal_vector['err']

        result = (disc_expected == disc_observed) and (flag_expected == flag_observed) and (err_expected == err_observed)

        if not result:
            print(f"Scenario: {signal_vector['scenario']}, disc - expected: {disc_expected}, observed: {disc_observed}, "
                  f"flag - expected: {flag_expected}, observed: {flag_observed}, "
                  f"err - expected: {err_expected}, observed: {err_observed}")

        return result
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

