class GoldenDUT:
    def __init__(self):
        # Initialize registers and states
        self.state_reg = 'IDLE'
        self.data_bits_reg = []
        self.done_reg = 0

    def load(self, signal_vector):
        # Load the signal vector and update internal registers
        bit = signal_vector['in']
        reset = signal_vector['reset']

        if reset:
            self.state_reg = 'IDLE'
            self.data_bits_reg = []
            self.done_reg = 0
            return

        if self.state_reg == 'IDLE':
            if bit == 0b0:  # start bit detected
                self.state_reg = 'START'

        elif self.state_reg == 'START':
            if len(self.data_bits_reg) < 8:
                if bit in (0b0, 0b1):  # valid data bit
                    self.data_bits_reg.append(bit)
                else:
                    self.state_reg = 'IDLE'  # malformed data bit, reset to IDLE
            else:
                # Check for stop bit
                self.state_reg = 'STOP' if bit == 0b1 else 'WAIT_FOR_STOP'

        elif self.state_reg == 'STOP':
            self.state_reg = 'IDLE'
            self.data_bits_reg = []
            self.done_reg = 1

        elif self.state_reg == 'WAIT_FOR_STOP':
            if bit == 0b1:
                self.state_reg = 'IDLE'
                self.done_reg = 1

        # Always set done_reg to 0 when not stopping
        if self.state_reg != 'STOP':
            self.done_reg = 0

    def check(self, signal_vector):
        # Check the expected output "done" against the provided signal vector
        done_observed = signal_vector['done']
        if done_observed != self.done_reg:
            print(f"Scenario: {signal_vector['scenario']}, expected: done={self.done_reg}, observed done={done_observed}")
            return False
        return True

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

