class GoldenDUT:
    def __init__(self):
        # Initializing the registers and state
        self.state_reg = 0  # IDLE
        self.bit_counter_reg = 0
        self.data_byte_reg = 0
        self.done_reg = 0

    def load(self, signal_vector):
        # Load input signals and update the state machine
        in_signal = signal_vector['in']
        reset_signal = signal_vector['reset']

        if reset_signal == 1:
            self.__reset()
        else:
            if self.state_reg == 0:  # IDLE
                if in_signal == 0:
                    self.state_reg = 1  # START_BIT
                    self.bit_counter_reg = 0

            elif self.state_reg == 1:  # START_BIT
                self.state_reg = 2  # DATA_BITS

            elif self.state_reg == 2:  # DATA_BITS
                if self.bit_counter_reg < 8:
                    self.data_byte_reg |= (in_signal << self.bit_counter_reg)
                    self.bit_counter_reg += 1
                if self.bit_counter_reg == 8:
                    self.state_reg = 3  # STOP_BIT

            elif self.state_reg == 3:  # STOP_BIT
                if in_signal == 1:
                    self.done_reg = 1
                else:
                    self.done_reg = 0
                    self.state_reg = 4  # ERROR

            elif self.state_reg == 4:  # ERROR
                if in_signal == 1:
                    self.state_reg = 0  # IDLE
                    self.done_reg = 0

    def check(self, signal_vector):
        # Compare expected done with DUT's output and return the result
        done_observed = signal_vector['done']
        if self.done_reg != done_observed:
            print(f"Scenario: {signal_vector['scenario']}, expected: done={self.done_reg}, observed done={done_observed}")
            return False
        return True

    def __reset(self):
        # Reset all registers
        self.state_reg = 0  # IDLE
        self.bit_counter_reg = 0
        self.data_byte_reg = 0
        self.done_reg = 0

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

