class GoldenDUT:
    def __init__(self):
        self.state_reg = 'IDLE'
        self.bit_count_reg = 0
        self.data_reg = 0
        self.expected_out_byte_reg = 0
        self.done_reg = False

    def load(self, signal_vector):
        if signal_vector['reset']:
            self.reset()
            return

        current_input = signal_vector['in']

        if self.state_reg == 'IDLE':
            if current_input == 0:  # Start bit detected
                self.state_reg = 'RECEIVING'
                self.bit_count_reg = 0
                self.data_reg = 0
                self.done_reg = False  # Prepare for new sequence

        elif self.state_reg == 'RECEIVING':
            # Capture incoming bits into data_reg
            self.data_reg |= (current_input << self.bit_count_reg)
            self.bit_count_reg += 1

            if self.bit_count_reg == 8:
                self.state_reg = 'STOP_BIT'

        elif self.state_reg == 'STOP_BIT':
            if current_input == 1:
                self.expected_out_byte_reg = self.data_reg & 0xFF
                self.done_reg = True
            else:
                self.done_reg = False
            # Transition to IDLE and prepare for potential next sequence
            self.data_reg = 0
            self.bit_count_reg = 0
            self.state_reg = 'IDLE'

    def reset(self):
        self.state_reg = 'IDLE'
        self.bit_count_reg = 0
        self.data_reg = 0
        self.expected_out_byte_reg = 0
        self.done_reg = False

    def check(self, signal_vector):
        if signal_vector['check_en']:
            observed_out_byte = signal_vector['out_byte']
            observed_done = signal_vector['done']

            if self.done_reg != observed_done or (self.done_reg and self.expected_out_byte_reg != observed_out_byte):
                print(f"Scenario: {signal_vector['scenario']}, expected: out_byte={self.expected_out_byte_reg}, done={self.done_reg}, observed: out_byte={observed_out_byte}, done={observed_done}")
                return False
            return True
        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

