class GoldenDUT:
    def __init__(self):
        self.state_reg = "IDLE"  # Initial state
        self.out_byte_reg = 0  # 8-bit register for output byte
        self.bit_count_reg = 0  # Counter to track number of bits received
        self.done_reg = 0  # Done signal register

    def load(self, signal_vector):
        # Reset logic
        if signal_vector['reset']:
            self.state_reg = "IDLE"
            self.out_byte_reg = 0
            self.bit_count_reg = 0
            self.done_reg = 0
            return

        current_bit = signal_vector['in']

        # FSM Logic
        if self.state_reg == "IDLE":
            if current_bit == 0:  # Start bit detected
                self.state_reg = "RECEIVING"
                self.out_byte_reg = 0
                self.bit_count_reg = 0
                self.done_reg = 0

        elif self.state_reg == "RECEIVING":
            self.out_byte_reg |= (current_bit << self.bit_count_reg)
            self.bit_count_reg += 1
            if self.bit_count_reg == 8:  # 8 data bits received
                self.state_reg = "CHECK_STOP"

        elif self.state_reg == "CHECK_STOP":
            if current_bit == 1:  # Stop bit detected
                self.done_reg = 1
                self.state_reg = "IDLE"
            else:  # Incorrect stop bit
                self.state_reg = "WAIT_FOR_STOP"
                self.done_reg = 0

        elif self.state_reg == "WAIT_FOR_STOP":
            if current_bit == 1:  # Waiting for stop bit
                self.state_reg = "IDLE"
            self.done_reg = 0

        # Ensure transition consistency
        if self.state_reg == "IDLE" and current_bit == 1:
            self.done_reg = 0

    def check(self, signal_vector):
        if signal_vector['check_en']:
            expected_out_byte = self.out_byte_reg & 0xFF  # Ensure 8-bit value
            expected_done = self.done_reg

            out_byte_observed = signal_vector['out_byte'] & 0xFF  # Ensure 8-bit value
            done_observed = signal_vector['done']

            if expected_out_byte == out_byte_observed and expected_done == done_observed:
                return True
            else:
                print(f"Scenario: {signal_vector['scenario']}, expected: out_byte={expected_out_byte}, done={expected_done}, "
                      f"observed: out_byte={out_byte_observed}, done={done_observed}")
                return False
        return True

    # Additional helper methods can be added if needed
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

