class GoldenDUT:
    def __init__(self):
        # Initialize internal state registers
        self.state_reg = "IDLE"
        self.bit_count_reg = 0
        self.data_reg = 0
        self.out_byte_reg = 0
        self.done_reg = 0

    def load(self, signal_vector):
        # Load input signals
        input_signal = signal_vector['in']
        reset_signal = signal_vector['reset']

        # Handle reset
        if reset_signal:
            self.reset_registers()
        else:
            # Finite State Machine Logic
            if self.state_reg == "IDLE":
                if input_signal == 0:
                    self.state_reg = "RECEIVING"
                    self.bit_count_reg = 0
                    self.data_reg = 0

            elif self.state_reg == "RECEIVING":
                if self.bit_count_reg < 8:  # Ensure we only process up to 8 bits
                    # Only accumulate bits if still valid, otherwise reset upon error or noise
                    self.data_reg |= (input_signal << self.bit_count_reg)
                    self.bit_count_reg += 1

                if self.bit_count_reg == 8:  # Transition after 8 bits received
                    self.state_reg = "STOP_BIT"

            elif self.state_reg == "STOP_BIT":
                # Check for correct stop bit
                if input_signal == 1:
                    self.out_byte_reg = self.data_reg & 0xFF
                    self.done_reg = 1
                else:
                    self.done_reg = 0  # Incorrect stop bit, FSM remains in IDLE waiting for next start
                # Reset after processing a complete byte regardless of stop bit status
                self.reset_after_byte()

    def check(self, signal_vector):
        # Compare outputs
        expected_done = self.done_reg
        expected_out_byte = self.out_byte_reg

        observed_done = signal_vector['done']
        observed_out_byte = signal_vector['out_byte']

        # Return the result of comparison
        if (expected_done == observed_done) and (expected_out_byte == observed_out_byte):
            return True
        else:
            print(f"Scenario: {signal_vector['scenario']}, expected: done={expected_done}, out_byte={expected_out_byte}, observed: done={observed_done}, out_byte={observed_out_byte}")
            return False

    def reset_registers(self):
        """ Resets the internal registers to their initial states """
        self.state_reg = "IDLE"
        self.bit_count_reg = 0
        self.data_reg = 0
        self.out_byte_reg = 0
        self.done_reg = 0

    def reset_after_byte(self):
        """ Resets necessary registers after processing a full byte sequence """
        self.state_reg = "IDLE"
        self.bit_count_reg = 0
        self.done_reg = 0  # Clear the done register as we are in IDLE state again

# End of GoldenDUT class
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

