class GoldenDUT:
    def __init__(self):
        # Initialize state machine registers
        self.state_reg = 'IDLE'
        self.data_bits_reg = []
        self.out_byte_reg = 0
        self.done_reg = False

    def load(self, signal_vector):
        if signal_vector['reset']:
            self.__init__()  # Reset state machine
            return

        bit = signal_vector['in']

        if self.state_reg == 'IDLE':
            if bit == 0:  # Start bit detected
                self.state_reg = 'START_BIT'
                self.data_bits_reg = []

        elif self.state_reg == 'START_BIT':
            self.data_bits_reg.append(bit)  # Collect data bits
            if len(self.data_bits_reg) == 8:
                self.state_reg = 'STOP_BIT'

        elif self.state_reg == 'STOP_BIT':
            if bit == 1:  # Correct stop bit
                # Correctly received a byte
                self.out_byte_reg = sum(val << idx for idx, val in enumerate(self.data_bits_reg))
                self.done_reg = True
                self.state_reg = 'IDLE'  # Transition back to IDLE after completing
            else:
                # Incorrect stop bit, reset FSM and wait for next start bit
                self.state_reg = 'IDLE'

    def check(self, signal_vector):
        if not signal_vector['check_en']:
            return True  # No check needed

        expected_done = self.done_reg
        expected_out_byte = self.out_byte_reg & 0xFF  # Ensure 8-bit output

        observed_done = signal_vector['done']
        observed_out_byte = signal_vector['out_byte'] & 0xFF  # Ensure 8-bit observed output

        if expected_done != observed_done or expected_out_byte != observed_out_byte:
            print(f"Scenario: {signal_vector['scenario']}, expected: done={expected_done}, out_byte={expected_out_byte}, "
                  f"observed: done={observed_done}, out_byte={observed_out_byte}")
            return False

        # Reset done to False for future checks
        self.done_reg = False

        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

