class GoldenDUT:
    def __init__(self):
        self.data_bits_reg = []
        self.is_receiving_reg = False
        self.out_byte_reg = 0
        self.done_reg = 0
        self.START_BIT = 0
        self.STOP_BIT = 1
        self.DATA_BITS_LENGTH = 8

    def load(self, signal_vector):
        # Synchronous reset
        if signal_vector['reset']:
            self.data_bits_reg.clear()
            self.is_receiving_reg = False
            self.out_byte_reg = 0
            self.done_reg = 0
            return

        # Process input signal
        bit = signal_vector['in']

        if self.is_receiving_reg:
            # Receiving data bits
            if len(self.data_bits_reg) < self.DATA_BITS_LENGTH:
                self.data_bits_reg.append(bit)
            else:
                # Expecting the stop bit after data bits
                if bit == self.STOP_BIT:
                    # Convert the collected data bits to a byte in little-endian format
                    self.out_byte_reg = int("".join(map(str, self.data_bits_reg[::-1])), 2)
                    self.done_reg = 1
                else:
                    self.done_reg = 0  # Incorrect bit, stop bit expected
                self.data_bits_reg.clear()
                self.is_receiving_reg = False
        else:
            # Looking for start bit
            if bit == self.START_BIT:
                self.is_receiving_reg = True
                self.data_bits_reg.clear()
                self.done_reg = 0  # Ensure done is reset when starting new reception

    def check(self, signal_vector):
        if not signal_vector['check_en']:
            return True

        expected_out_byte = self.out_byte_reg
        expected_done = self.done_reg

        out_byte_observed = signal_vector['out_byte']
        done_observed = signal_vector['done']

        if expected_out_byte != out_byte_observed or expected_done != done_observed:
            print(f"Scenario: {signal_vector['scenario']}, expected: out_byte={expected_out_byte}, done={expected_done}, observed out_byte={out_byte_observed}, done={done_observed}")
            return False

        return True

    # You can add more helper methods here if needed.
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

