class GoldenDUT:
    def __init__(self):
        self.state_reg = "IDLE"
        self.data_bits_reg = []
        self.out_byte_reg = 0
        self.done_reg = 0

    def load(self, signal_vector):
        in_bit = signal_vector['in']
        reset = signal_vector['reset']

        if reset:
            self.state_reg = "IDLE"
            self.data_bits_reg = []
            self.out_byte_reg = 0
            self.done_reg = 0
        else:
            if self.state_reg == "IDLE":
                if in_bit == 0:
                    self.state_reg = "RECEIVING"
                    self.data_bits_reg = []
                self.done_reg = 0

            elif self.state_reg == "RECEIVING":
                self.data_bits_reg.append(in_bit)
                if len(self.data_bits_reg) == 8:
                    self.state_reg = "STOP_BIT"

            elif self.state_reg == "STOP_BIT":
                if in_bit == 1:
                    self.out_byte_reg = int("".join(map(str, self.data_bits_reg[::-1])), 2)
                    self.done_reg = 1
                    self.state_reg = "IDLE"
