class GoldenDUT:
    def __init__(self):
        self.state_reg = 'IDLE'
        self.data_bits_reg = []
        self.out_byte_reg = 0
        self.done_reg = False
        self.bit_count = 0  # Additional register to count data bits

    def load(self, signal_vector):
        # Reset logic
        if signal_vector['reset'] == 1:
            self.__init__()
            return

        # State machine logic
        in_bit = signal_vector['in']

        if self.state_reg == 'IDLE':
            if in_bit == 0:  # Valid start bit
                self.state_reg = 'START'
                self.data_bits_reg = []
                self.bit_count = 0

        elif self.state_reg == 'START':
            self.data_bits_reg.append(in_bit)
            self.bit_count += 1
            if self.bit_count == 8:
                self.state_reg = 'STOP'

        elif self.state_reg == 'STOP':
            if in_bit == 1:  # Expected stop bit is 1
                self.out_byte_reg = int(''.join(map(str, self.data_bits_reg[::-1])), 2)
                self.done_reg = True
            else:
                self.done_reg = False  # Incorrect stop bit

            # Transition back to IDLE, clear data for next byte
            self.data_bits_reg = []
            self.state_reg = 'IDLE'
            self.bit_count = 0

    def check(self, signal_vector):
        if signal_vector['check_en']:
            observed_out_byte = signal_vector['out_byte']
            observed_done = signal_vector['done']

            if (self.out_byte_reg == observed_out_byte) and (self.done_reg == observed_done):
                return True
            else:
                print(f"Scenario: {signal_vector['scenario']}, expected: out_byte={self.out_byte_reg}, done={self.done_reg}, observed: out_byte={observed_out_byte}, done={observed_done}")
                return False
        return True

    def _reset_for_next_byte(self):
        """Clears data and sets state to IDLE for the next byte processing."""
        self.data_bits_reg = []
        self.state_reg = 'IDLE'
        self.done_reg = False
        self.bit_count = 0
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

