class GoldenDUT:
    def __init__(self):
        self.state_reg = 'idle'
        self.bit_count_reg = 0
        self.data_reg = 0
        self.out_byte_reg = 0
        self.done_reg = 0

    def load(self, signal_vector):
        in_signal = signal_vector['in']
        reset = signal_vector['reset']

        if reset:
            self.state_reg = 'idle'
            self.bit_count_reg = 0
            self.data_reg = 0
            self.out_byte_reg = 0
            self.done_reg = 0
        else:
            if self.state_reg == 'idle':
                if in_signal == 0:  # Start bit detected
                    self.state_reg = 'receiving'
                    self.bit_count_reg = 0
                    self.data_reg = 0
                    self.done_reg = 0

            elif self.state_reg == 'receiving':
                if self.bit_count_reg < 8:
                    # Shift in the bits correctly
                    self.data_reg = (self.data_reg >> 1) | (in_signal << 7)
                    self.bit_count_reg += 1
                else:  # 8 bits have been received
                    if in_signal == 1:  # Stop bit expected
                        self.out_byte_reg = self.data_reg & 0xFF
                        self.done_reg = 1
                        self.state_reg = 'idle'
                    else:
                        self.state_reg = 'wait_for_stop'  # If stop bit is wrong, wait for correct stop
                    # Commented out because we only reset these in idle & wait states
                    # self.bit_count_reg = 0
                    # self.data_reg = 0

            elif self.state_reg == 'wait_for_stop':
                if in_signal == 1:  # Correct stop bit finally received
                    self.state_reg = 'idle'  # Reset to idle to start fresh
                    self.done_reg = 0  # Reset done

    def check(self, signal_vector):
        if not signal_vector['check_en']:
            return True

        out_byte_observed = signal_vector['out_byte']
        done_observed = signal_vector['done']

        if self.out_byte_reg != out_byte_observed or self.done_reg != done_observed:
            print(f"Scenario: {signal_vector['scenario']}, "
                  f"expected: out_byte={self.out_byte_reg}, done={self.done_reg}, "
                  f"observed: out_byte={out_byte_observed}, done={done_observed}")
            return False

        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
