import numpy as np

# Constants
PHT_SIZE = 128
COUNTER_BITS = 2
MAX_COUNTER_VALUE = 0b11
MIN_COUNTER_VALUE = 0b00
HISTORY_BITS = 7

def xor_hash(pc, history):
    return pc ^ history

def saturating_counter_update(counter, taken):
    if taken:
        return min(counter + 1, MAX_COUNTER_VALUE)
    else:
        return max(counter - 1, MIN_COUNTER_VALUE)

class GoldenDUT:
    def __init__(self):
        # Initialize internal states
        self.pht_reg = np.full(PHT_SIZE, 0b01, dtype=int)
        self.history_reg = 0
        self.predict_taken_reg = False  # Initialize predict_taken_reg
        self.predict_history_reg = 0    # Initialize predict_history_reg

    def load(self, signal_vector):
        # Load inputs and update internal state
        self.predict_valid = signal_vector.get('predict_valid', False)
        self.predict_pc = signal_vector.get('predict_pc', 0)
        self.train_valid = signal_vector.get('train_valid', False)
        self.train_taken = signal_vector.get('train_taken', False)
        self.train_mispredicted = signal_vector.get('train_mispredicted', False)
        self.train_history = signal_vector.get('train_history', 0)
        self.train_pc = signal_vector.get('train_pc', 0)
        self.check_en = signal_vector.get('check_en', False)

        if signal_vector.get('areset', 0):
            self.reset()

        if self.train_valid:
            self.train()

        if self.predict_valid:
            self.predict()

    def predict(self):
        index = xor_hash(self.predict_pc, self.history_reg)
        self.predict_taken_reg = (self.pht_reg[index] >> 1) == 1
        self.predict_history_reg = self.history_reg

    def train(self):
        index = xor_hash(self.train_pc, self.train_history)
        self.pht_reg[index] = saturating_counter_update(self.pht_reg[index], self.train_taken)

        if self.train_mispredicted:
            # Update the global history register with the outcome of the current branch
            self.history_reg = ((self.train_history << 1) | self.train_taken) & ((1 << HISTORY_BITS) - 1)
        else:
            # Regular update of the history register
            self.history_reg = ((self.history_reg << 1) | self.train_taken) & ((1 << HISTORY_BITS) - 1)

    def check(self, signal_vector):
        if self.check_en:
            predict_taken_observed = signal_vector.get('predict_taken', False)
            predict_history_observed = signal_vector.get('predict_history', 0)

            # Check expected vs observed
            if (self.predict_taken_reg != predict_taken_observed or 
                self.predict_history_reg != predict_history_observed):
                print(f"Scenario: {signal_vector['scenario']}, expected: predict_taken={self.predict_taken_reg}, observed predict_taken={predict_taken_observed}")
                print(f"Scenario: {signal_vector['scenario']}, expected: predict_history={self.predict_history_reg}, observed predict_history={predict_history_observed}")
                return False
        return True

    def reset(self):
        self.pht_reg = np.full(PHT_SIZE, 0b01, dtype=int)
        self.history_reg = 0
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
