import numpy as np

class GoldenDUT:
    def __init__(self):
        self.pht = np.zeros(128, dtype=int)  # 128-entry table of 2-bit counters (initialized to 0)
        self.global_history_reg = 0  # 7-bit global history register
        self.predict_taken_reg = 0
        self.predict_history_reg = 0
        self.next_global_history = 0  # Maintain next global history for misprediction recovery

    def load(self, signal_vector):
        if signal_vector['predict_valid']:
            # Perform prediction and store results internally
            self.predict_taken_reg, self.predict_history_reg = self.predict(signal_vector['predict_pc'])

        if signal_vector['train_valid']:
            # Perform training updates and capture new global history
            self.next_global_history = self.train(
                signal_vector['train_pc'],
                signal_vector['train_history'],
                signal_vector['train_taken'],
                signal_vector['train_mispredicted']
            )
            if signal_vector['train_mispredicted']:
                # Apply global history recovery immediately on misprediction
                self.global_history_reg = self.next_global_history
            else:
                # If training was correct, update the global history as per the prediction result
                self.global_history_reg = self.update_global_history(self.global_history_reg, self.predict_taken_reg)

    def check(self, signal_vector):
        if signal_vector['check_en']:
            expected_predict_taken, expected_predict_history = self.predict(signal_vector['predict_pc'])

            if expected_predict_taken != self.predict_taken_reg:
                print(f"Scenario: {signal_vector['scenario']}, expected: predict_taken={expected_predict_taken}, observed predict_taken={self.predict_taken_reg}")
                return False

            if expected_predict_history != self.predict_history_reg:
                print(f"Scenario: {signal_vector['scenario']}, expected: predict_history={expected_predict_history}, observed predict_history={self.predict_history_reg}")
                return False

        return True

    def xor_index(self, pc, global_history):
        # XOR to generate the index for the PHT
        return pc ^ global_history

    def saturating_counter_update(self, counter, taken):
        # Update the saturating counter
        if taken:
            return min(counter + 1, 3)
        else:
            return max(counter - 1, 0)

    def update_global_history(self, global_history, taken):
        # Update global history with new outcome
        return ((global_history << 1) | taken) & 0x7F

    def predict(self, pc):
        # Make prediction using the current global history
        index = self.xor_index(pc, self.global_history_reg)
        counter = self.pht[index]
        predicted_taken = counter >= 2
        predicted_history = self.update_global_history(self.global_history_reg, predicted_taken)
        return predicted_taken, predicted_history

    def train(self, pc, global_history, actual_outcome, mispredicted):
