import numpy as np

# Constants
GHR_BITS = 7          # Global History Register bits
TABLE_ENTRIES = 128   # Number of PHT entries
COUNTER_BITS = 2      # Bits for the saturating counter

def xor_hash(pc, history):
    """Generate index by XORing pc and history."""
    return pc ^ history

def saturating_counter_update(counter, taken):
    """Update the 2-bit saturating counter based on whether the branch was taken."""
    if taken:
        return min(counter + 1, (1 << COUNTER_BITS) - 1)
    else:
        return max(counter - 1, 0)

class GoldenDUT:
    def __init__(self):
        self.pht_reg = np.zeros(TABLE_ENTRIES, dtype=int)  # Pattern History Table
        self.global_history_reg = 0b0                      # Global History Register

    def load(self, signal_vector):
        if signal_vector['areset']:
            self.reset()
        else:
            # Save the current global history for potential recovery
            if signal_vector['train_valid']:
                self.train(signal_vector['train_pc'], signal_vector['train_history'],
                           signal_vector['train_taken'], signal_vector['train_mispredicted'])

            if signal_vector['predict_valid']:
                predict_taken, predict_history = self.predict(signal_vector['predict_pc'])

                # Only update the global history register for predictions if no training happens
                if not signal_vector['train_valid'] or not signal_vector['train_mispredicted']:
                    self.global_history_reg = ((self.global_history_reg << 1) | predict_taken) & ((1 << GHR_BITS) - 1)

    def reset(self):
        self.pht_reg.fill(0)
        self.global_history_reg = 0b0

    def predict(self, predict_pc):
        index = xor_hash(predict_pc, self.global_history_reg)
        counter_value = self.pht_reg[index]
        predict_taken = counter_value >= (1 << (COUNTER_BITS - 1))
        return predict_taken, self.global_history_reg

    def train(self, train_pc, train_history, train_taken, train_mispredicted):
        index = xor_hash(train_pc, train_history)
        current_state = self.pht_reg[index]
        self.pht_reg[index] = saturating_counter_update(current_state, train_taken)

        # Update the global history register only if the training indicates a misprediction
        if train_mispredicted:
            self.global_history_reg = train_history

    def check(self, signal_vector):
        predict_taken_observed = signal_vector['predict_taken']
        predict_history_observed = signal_vector['predict_history']

        predict_taken_expected, predict_history_expected = self.predict(signal_vector['predict_pc'])

        if (predict_taken_observed != predict_taken_expected or
                predict_history_observed != predict_history_expected):
            print(f"Scenario: {signal_vector['scenario']}, "
                  f"expected: predict_taken={predict_taken_expected}, predict_history={predict_history_expected}, "
                  f"observed predict_taken={predict_taken_observed}, predict_history={predict_history_observed}")
            return False

        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

