import numpy as np

class GoldenDUT:
    def __init__(self):
        # Initialize the registers
        self.global_history_reg = 0
        self.PHT = np.zeros(128, dtype=np.uint8)  # Initialize the PHT with 2-bit saturating counters

    def load(self, signal_vector):
        # Load input signals and update internal states
        if signal_vector['areset']:
            self.global_history_reg = 0
            self.PHT = np.zeros(128, dtype=np.uint8)
        else:
            if signal_vector['train_valid']:
                # Training is prioritized per the specification
                self.train_update(signal_vector)
            elif signal_vector['predict_valid']:
                # Ensure prediction is checked separately when not training
                self.predict_update(signal_vector)

    def check(self, signal_vector):
        if not signal_vector['check_en']:
            return True

        expected_taken, expected_history = self.gshare_predict(signal_vector)

        predict_taken_observed = signal_vector['predict_taken']
        predict_history_observed = signal_vector['predict_history']

        correct = True

        if expected_taken != predict_taken_observed:
            print(f"Scenario: {signal_vector['scenario']}, expected taken: {expected_taken}, observed taken: {predict_taken_observed}")
            correct = False

        if expected_history != predict_history_observed:
