import numpy as np

class GoldenDUT:
    def __init__(self):
        self.PHT_reg = np.zeros(128, dtype=np.int8)  # Two-bit saturating counters
        self.global_history_reg = 0  # 7-bit global history
        self.predict_taken_reg = 0
        self.predict_history_reg = 0

    def xor_index(self, pc, history):
        # Calculate the 7-bit index by XORing pc and history
        return pc ^ history

    def saturating_counter_update(self, value, increment):
        # Update the two-bit saturating counter
        if increment:
            return min(value + 1, 3)  # max value is 0b11
        else:
            return max(value - 1, 0)  # min value is 0b00

    def load(self, signal_vector):
        # Load important signals and calculate predictions
        if signal_vector['predict_valid']:
            self.predict_taken_reg, self.predict_history_reg = self.predict(
                signal_vector['predict_pc']
            )
            # Update global history after prediction, only if no concurrent training
            if not signal_vector['train_valid']:
                self.global_history_reg = (self.global_history_reg << 1) | self.predict_taken_reg
                self.global_history_reg &= 0x7F  # Keep only the last 7 bits

        if signal_vector['train_valid']:
            self.train(
                signal_vector['train_pc'], 
                signal_vector['train_taken'], 
                signal_vector['train_mispredicted'],
                signal_vector['train_history']
            )

    def predict(self, pc):
        index = self.xor_index(pc, self.global_history_reg)
        counter = self.PHT_reg[index]
        predict_taken = counter >= 2  # Using the two most significant bits for prediction
        return predict_taken, self.global_history_reg

    def train(self, pc, actual_taken, mispredicted, train_history):
        # Retrieve the current index and counter
        index = self.xor_index(pc, train_history)
        counter = self.PHT_reg[index]

        # Update the saturation counter based on actual outcome
        self.PHT_reg[index] = self.saturating_counter_update(counter, actual_taken)

        # Handle misprediction recovery
        if mispredicted:
            # Properly update the global history register by considering recovery
            self.global_history_reg = (train_history << 1) | actual_taken
            self.global_history_reg &= 0x7F  # Keep only the last 7 bits
        else:
            # When training without misprediction, update history normally
            self.global_history_reg = (self.global_history_reg << 1) | actual_taken
            self.global_history_reg &= 0x7F  # Keep last 7 bits

    def check(self, signal_vector):
        # Check outputs only if check_en is True
        if signal_vector['check_en']:
            predict_taken_expected, predict_history_expected = self.predict(signal_vector['predict_pc'])

            # Compare with DUT outputs
            if (predict_taken_expected != self.predict_taken_reg or
                predict_history_expected != self.predict_history_reg):
                print(f"Scenario: {signal_vector['scenario']}, "
                      f"expected: predict_taken={predict_taken_expected}, "
                      f"predict_history={predict_history_expected}, "
                      f"observed: predict_taken={self.predict_taken_reg}, "
                      f"predict_history={self.predict_history_reg}")
                return False

        return True

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

