import numpy as np

class GoldenDUT:
    def __init__(self):
        # Initialize registers
        self.global_history_reg = 0  # 7-bit global history register
        self.PHT_reg = np.zeros(128, dtype=np.uint8)  # 128-entry table of 2-bit saturating counters
        self.counter_max = 0b11  # Two-bit saturating counter max value

    def load(self, signal_vector):
        if signal_vector['areset']:
            self.reset()

        if signal_vector['train_valid']:
            self.train(signal_vector['train_pc'], 
                       signal_vector['train_taken'], 
                       signal_vector['train_mispredicted'], 
                       signal_vector['train_history'])

        if signal_vector['predict_valid']:
            self.update_global_history(signal_vector['predict_taken'])

    def reset(self):
        self.global_history_reg = 0b0000000
        self.PHT_reg.fill(0)

    def predict(self, pc):
        index = pc ^ self.global_history_reg
        counter = self.PHT_reg[index]
        predict_taken = counter >= 2
        predict_history = self.global_history_reg
        return predict_taken, predict_history

    def update_global_history(self, branch_taken):
        self.global_history_reg = ((self.global_history_reg << 1) | branch_taken) & 0b1111111

    def train(self, pc, actual_outcome, mispredicted, train_history):
        index = pc ^ train_history
        counter = self.PHT_reg[index]

        # Update the counter
        if actual_outcome:
            if counter < self.counter_max:
                self.PHT_reg[index] += 1
        else:
            if counter > 0:
                self.PHT_reg[index] -= 1

        # Handle misprediction to recover history
        if mispredicted:
            self.global_history_reg = train_history
        else:
            self.update_global_history(actual_outcome)

    def check(self, signal_vector):
        if signal_vector['check_en']:
            expected_taken, expected_history = self.predict(signal_vector['predict_pc'])

            if signal_vector['predict_taken'] != expected_taken:
                print(f"Scenario: {signal_vector['scenario']}, expected: predict_taken={expected_taken}, observed predict_taken={signal_vector['predict_taken']}")
                return False

            if signal_vector['predict_history'] != expected_history:
                print(f"Scenario: {signal_vector['scenario']}, expected: predict_history={expected_history}, observed predict_history={signal_vector['predict_history']}")
                return False

        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

