import numpy as np

class GoldenDUT:
    def __init__(self):
        # Initialize the PHT and global history register with initial values
        self.BIT_WIDTH = 7
        self.PHT_SIZE = 128
        self.SATURATING_COUNTER_MAX = 3

        self.pht = np.zeros(self.PHT_SIZE, dtype=np.int32)
        self.global_history_register = 0

        # Internal registers with initial values
        self.predict_taken_reg = False
        self.predict_history_reg = 0
        self.train_taken_reg = False
        self.train_history_reg = 0

    def load(self, signal_vector):
        # Load input signals and update internal registers
        if signal_vector['predict_valid']:
            index = self.xor_hash(signal_vector['predict_pc'], self.global_history_register)
            self.predict_taken_reg = self.pht[index] >= 2
            # Output the pre-update history
            self.predict_history_reg = ((self.global_history_register << 1) | int(self.predict_taken_reg)) & 0b1111111

        if signal_vector['train_valid']:
            index = self.xor_hash(signal_vector['train_pc'], signal_vector['train_history'])
            self.pht[index] = self.saturating_counter_update(self.pht[index], signal_vector['train_taken'])

            # Update the global history based on train result if there's no misprediction
            if not signal_vector['train_mispredicted']:
                self.global_history_register = ((self.global_history_register << 1) | int(signal_vector['train_taken'])) & 0b1111111
            else:
                # Recover the global history register based on the pre-misprediction state
                self.global_history_register = ((signal_vector['train_history'] << 1) | int(signal_vector['train_taken'])) & 0b1111111

    def check(self, signal_vector):
        if signal_vector['check_en']:
            # Expected values from the Golden DUT
            expected_predict_taken, expected_predict_history = self.predict(signal_vector['predict_pc'], signal_vector['predict_valid'])

            # Compare expected values with observed DUT values
            observed_predict_taken = self.predict_taken_reg
            observed_predict_history = self.predict_history_reg

            is_correct = (expected_predict_taken == observed_predict_taken) and (expected_predict_history == observed_predict_history)
            if not is_correct:
                print(f"Scenario: {signal_vector['scenario']}, expected: predict_taken={expected_predict_taken}, predict_history={expected_predict_history}, observed: predict_taken={observed_predict_taken}, predict_history={observed_predict_history}")
            return is_correct
        return True

    def xor_hash(self, pc, history):
        return pc ^ history

    def saturating_counter_update(self, counter, taken):
        if taken:
            if counter < self.SATURATING_COUNTER_MAX:
                counter += 1
        else:
            if counter > 0:
                counter -= 1
        return counter

    def predict(self, predict_pc, predict_valid):
        if predict_valid:
            index = self.xor_hash(predict_pc, self.global_history_register)
            predict_taken = self.pht[index] >= 2
            new_history = ((self.global_history_register << 1) | int(predict_taken)) & 0b1111111
            return predict_taken, new_history
        else:
            return None, self.global_history_register
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

