import numpy as np

class GoldenDUT:
    def __init__(self):
        # Initialize internal registers of the golden DUT
        self.ghr_reg = 0    # 7-bit Global History Register
        self.pht_reg = [1] * 128  # Pattern History Table (PHT) initialized to 1 (weak not taken)
        self.predict_taken_reg = 0
        self.predict_history_reg = 0

    def load(self, signal_vector):
        # Update the internal states using the signal vector inputs
        if signal_vector['train_valid']:
            self._train(signal_vector)

        if signal_vector['predict_valid']:
            # Modify the order of operations and handling for `predict_valid`
            self._predict(signal_vector)

    def check(self, signal_vector):
        # Verify the outputs from DUT using the expected values
        expected_taken, expected_history = self.predict_taken_reg, self.predict_history_reg
        observed_taken, observed_history = self._get_observed_outputs(signal_vector)

        if expected_taken != observed_taken or expected_history != observed_history:
            print(f"Scenario: {signal_vector['scenario']}, expected: predict_taken={expected_taken}, "
                  f"predict_history={bin(expected_history)}, "
                  f"observed: predict_taken={observed_taken}, predict_history={bin(observed_history)}")
            return False
        return True

    def _predict(self, signal_vector):
        # Perform a prediction
        index = self._gshare_index(signal_vector['predict_pc'], self.ghr_reg)
        counter_value = self.pht_reg[index]
        self.predict_taken_reg = counter_value >= 2  # Strong and weak taken
        self.predict_history_reg = self.ghr_reg
        # Update the GHR for the next cycle based on the prediction
        self.ghr_reg = ((self.ghr_reg << 1) | self.predict_taken_reg) & 0x7F

    def _train(self, signal_vector):
        # Perform training, possibly correcting for misprediction
        index = self._gshare_index(signal_vector['train_pc'], signal_vector['train_history'])
        self.pht_reg[index] = self._saturating_counter_update(self.pht_reg[index], signal_vector['train_taken'])

        if signal_vector['train_mispredicted']:
            # Recover GHR if the branch is mispredicted
            self.ghr_reg = signal_vector['train_history']
        else:
            # Update GHR only if not recovering from misprediction
            self.ghr_reg = ((self.ghr_reg << 1) | signal_vector['train_taken']) & 0x7F

    def _saturating_counter_update(self, counter, taken):
        # Update a 2-bit saturating counter based on whether a branch was taken
        if taken:
            return min(counter + 1, 3)
        else:
            return max(counter - 1, 0)

    def _gshare_index(self, pc, ghr):
        # Compute the index for the PHT using XOR of PC and GHR
        return pc ^ ghr

    def _get_observed_outputs(self, signal_vector):
        # Observe outputs from DUT for comparison
        return signal_vector.get('predict_taken'), signal_vector.get('predict_history')
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

