import numpy as np

class GoldenDUT:
    def __init__(self):
        self.q_reg = 0  # Initialize the 256-bit state vector

    def load(self, signal_vector):
        if signal_vector['load']:
            self.q_reg = signal_vector['data'] & ((1 << 256) - 1)  # Apply bitmask to ensure the value is within 256 bits.

    def check(self, signal_vector):
        q_expected = self.expected_output(self.q_reg)
        q_observed = signal_vector['q']

        if q_expected != q_observed:
            print(f"Scenario: {signal_vector['scenario']}, expected: q={hex(q_expected)}, observed q={hex(q_observed)}")
            return False
        return True

    def expected_output(self, initial_state_vector):
        grid = self.grid_from_vector(initial_state_vector)
        next_grid = self.ideal_rule(grid)
        return self.vector_from_grid(next_grid)

    def grid_from_vector(self, vector):
        return np.array([[(vector >> (row * 16 + col)) & 0b1 for col in range(16)] for row in range(16)], dtype=int)

    def vector_from_grid(self, grid):
        return sum(cell << (row * 16 + col) for row in range(16) for col in range(16) for cell in [grid[row, col]])

    def count_neighbors(self, grid, row, col):
        total_rows, total_cols = grid.shape
        row_indices = [(row - 1) % total_rows, row, (row + 1) % total_rows]
        col_indices = [(col - 1) % total_cols, col, (col + 1) % total_cols]
        neighbor_count = sum(grid[r, c] for r in row_indices for c in col_indices) - grid[row, col]
        return neighbor_count

    def ideal_rule(self, grid):
        rows, cols = grid.shape
        new_grid = np.zeros((rows, cols), dtype=int)

        for r in range(rows):
            for c in range(cols):
                alive_neighbors = self.count_neighbors(grid, r, c)

                if alive_neighbors < 2 or alive_neighbors > 3:  # Rule 1 and 4: Die due to under/overpopulation
                    new_grid[r, c] = 0
                elif alive_neighbors == 3:  # Rule 3: Cell becomes 1 if exactly 3 neighbors
                    new_grid[r, c] = 1
                elif alive_neighbors == 2:  # Rule 2: Cell state does not change if 2 neighbors
                    new_grid[r, c] = grid[r, c]

        return new_grid
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

