import numpy as np

class GoldenDUT:
    def __init__(self):
        # Initialize the 16x16 grid as a 256-bit integer
        self.q_reg = 0

    def load(self, signal_vector):
        # Load data if 'load' signal is high
        if signal_vector['load']:
            self.q_reg = signal_vector['data'] & ((1 << 256) - 1)
        # Update the grid state if 'load' is not high
        else:
            self.q_reg = self._game_of_life_rule(self.q_reg)

    def check(self, signal_vector):
        # Compare the expected q with the actual q from the DUT
        q_observed = signal_vector['q']

        # Producing expected q from internal state
        expected_q = self.q_reg

        if expected_q != q_observed:
            print(f"Scenario: {signal_vector['scenario']}, expected: q={expected_q:0256b}, observed: q={q_observed:0256b}")
            return False
        return True

    def _count_neighbors(self, grid, x, y):
        count = 0
        # Check all 8 neighbors in a toroidal manner
        for dx in [-1, 0, 1]:
            for dy in [-1, 0, 1]:
                if dx == 0 and dy == 0:
                    continue
                nx = (x + dx) % 16
                ny = (y + dy) % 16
                count += grid[nx, ny]
        return count

    def _game_of_life_rule(self, current_state):
        grid = np.array([(current_state >> (16*r + c)) & 1 for r in range(16) for c in range(16)]).reshape((16, 16))
        next_state_grid = np.zeros((16, 16), dtype=int)

        for x in range(16):
            for y in range(16):
                alive_neighbors = self._count_neighbors(grid, x, y)
                if alive_neighbors == 3 or (alive_neighbors == 2 and grid[x, y] == 1):
                    next_state_grid[x, y] = 1
                else:
                    next_state_grid[x, y] = 0

        next_state = 0
        for r in range(16):
            for c in range(16):
                next_state |= (next_state_grid[r, c] << (16*r + c))

        return next_state

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

