class GoldenDUT:
    def __init__(self):
        # Initialize the internal state values with the default values
        self.hh_reg = 0x12  # 12 AM
        self.mm_reg = 0x00  # 00 minutes
        self.ss_reg = 0x00  # 00 seconds
        self.pm_reg = 0  # Starting with AM

    def load(self, signal_vector):
        # If reset is high, reset the internal values
        if signal_vector['reset']:
            self.hh_reg = 0x12
            self.mm_reg = 0x00
            self.ss_reg = 0x00
            self.pm_reg = 0
        # If enabled, increment time
        elif signal_vector['ena']:
            self.ss_reg, carry_sec = self.increment_second(self.ss_reg)
            if carry_sec:
                self.mm_reg, carry_min = self.increment_minute(self.mm_reg)
                if carry_min:
                    self.hh_reg, self.pm_reg = self.increment_hour(self.hh_reg, self.pm_reg)

    def check(self, signal_vector):
        # Check if this is the time to verify outputs
        if not signal_vector['check_en']:
            return True

        a_observed = signal_vector['hh']
        b_observed = signal_vector['mm']
        c_observed = signal_vector['ss']
        d_observed = signal_vector['pm']

        if (a_observed != self.hh_reg) or (b_observed != self.mm_reg) or (c_observed != self.ss_reg) or (d_observed != self.pm_reg):
            print(f"Scenario: {signal_vector['scenario']}, expected: hh={self.hh_reg}, mm={self.mm_reg}, ss={self.ss_reg}, pm={self.pm_reg}, observed: hh={a_observed}, mm={b_observed}, ss={c_observed}, pm={d_observed}")
            return False

        return True

    def bcd_addition(self, a, b, carry_in=0):
        result = a + b + carry_in
        if result > 9:
            return (result - 10, 1)  # Return adjusted sum and carry
        else:
            return (result, 0)  # Return sum and zero carry

    def increment_second(self, ss_bcd):
        low_digit = ss_bcd & 0x0F
        high_digit = (ss_bcd >> 4) & 0x0F

        low_result, carry = self.bcd_addition(low_digit, 1)
        if carry:
            high_result, _ = self.bcd_addition(high_digit, 1)
        else:
            high_result = high_digit

        if high_result == 6:
            return 0x00, True
        else:
            return (high_result << 4) | low_result, False

    def increment_minute(self, mm_bcd):
        low_digit = mm_bcd & 0x0F
        high_digit = (mm_bcd >> 4) & 0x0F

        low_result, carry = self.bcd_addition(low_digit, 1)
        if carry:
            high_result, _ = self.bcd_addition(high_digit, 1)
        else:
            high_result = high_digit

        if high_result == 6:
            return 0x00, True
        else:
            return (high_result << 4) | low_result, False

    def increment_hour(self, hh_bcd, is_pm):
        low_digit = hh_bcd & 0x0F
        high_digit = (hh_bcd >> 4) & 0x0F

        low_result, carry = self.bcd_addition(low_digit, 1)
        if carry:
            high_result, _ = self.bcd_addition(high_digit, 1)
        else:
            high_result = high_digit

        if high_result == 1 and low_result == 3:
            return 0x01, not is_pm
        else:
            return (high_result << 4) | low_result, is_pm

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
