class GoldenDUT:
    def __init__(self):
        # Internal states initialized
        self.q_reg = 0x0000  # 4-digit BCD counter initialized to 0
        self.ena_reg = 0b000  # Enable signals for digits 3:1 initialized to 0

    def load(self, signal_vector):
        # Load input signals and update internal states
        if signal_vector['reset']:
            self.q_reg = 0x0000
            self.ena_reg = 0b000
        else:
            self.q_reg, self.ena_reg = self.bcd_increment(self.q_reg)

    def check(self, signal_vector):
        # Verify outputs against expected values
        if not signal_vector['check_en']:
            return True

        # Expected values
        expected_q = self.q_reg
        expected_ena = self.ena_reg

        # Observed values from DUT
        observed_q = signal_vector['q']
        observed_ena = signal_vector['ena']

        if expected_q == observed_q and expected_ena == observed_ena:
            return True
        else:
            print(f"Scenario: {signal_vector['scenario']}, expected: q={expected_q}, ena={expected_ena}, observed: q={observed_q}, ena={observed_ena}")
            return False

    def bcd_increment(self, value):
        digits = [(value >> (4 * i)) & 0xF for i in range(4)]
        ena = 0b000

        carry = 1  # Start with an initial increment of 1 (i.e., carry)

        for i in range(4):
            if carry:
                digits[i] += 1
            if digits[i] > 9:
                digits[i] = 0
                carry = 1
                if i < 3:
                    ena |= (1 << i)  # Set enable for carry propagation
            else:
                carry = 0  # No carry needed further if current digit < 10

        incremented_value = sum((digit << (4 * i)) for i, digit in enumerate(digits))
        return incremented_value, ena
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

