        observed_ena = [signal_vector.get(f'ena[{i}]', 0) for i in range(3, 0, -1)]

        if expected_q == observed_q and expected_ena == observed_ena:
            return True
        else:
            print(f"Scenario: {signal_vector['scenario']}, expected: q={expected_q}, ena={expected_ena}, "
