            ena_observed = signal_vector['ena']
            if expected_ena != ena_observed:
                print(f"Scenario: {signal_vector['scenario']}, expected: ena={expected_ena}, observed ena={ena_observed}")
                return False

        return True

    def bcd_increment(self, value):
        if value == 'x':  
            value = 0x0000

        # Unpack BCD digits
        ones = value & 0xF
        tens = (value >> 4) & 0xF
        hundreds = (value >> 8) & 0xF
        thousands = (value >> 12) & 0xF

        # Increment the ones place and handle carryovers
